update public.course_modules set title = 'Prendre en main Linux', description = 'Ce module pose les repères indispensables avant toute administration : ce qu’est Linux, où l’utiliser sans risque, puis comment lire une commande et se déplacer dans l’arborescence sans se perdre. Critères de réussite : choisir un environnement d’entraînement adapté ; décomposer une commande et trouver son aide ; te repérer dans « / », « /etc », « /var/log » et « /home » sans confusion.'
