update public.quiz_questions set explanation = 'La permission « r » signifie bien lecture. Sur un fichier, elle permet d’en lire le contenu. Sur un dossier, elle permet surtout d’en lister les noms. L’option « exécuter » correspond à « x », et « supprimer tous les comptes » n’a aucun rapport avec les droits Unix.'
where id = 'c2f3bbf5-291e-99a1-9048-59a2c6c231f9' and explanation = 'r signifie read, donc lecture.';
update public.quiz_questions set explanation = 'Limiter les permissions applique le moindre privilège : chaque personne ou service reçoit seulement ce qui lui est utile. Donner tous les droits à tous simplifie parfois un dépannage de quelques minutes, mais crée ensuite un risque durable d’erreur, de fuite ou de modification malveillante.'
where id = '1183e4e0-7efc-b599-6dda-e02b13d57008' and explanation = 'Chaque utilisateur ou processus doit disposer uniquement des droits nécessaires.';

update public.courses c set estimated_duration = least(10000, s.total)
from (select course_id, sum(duration_minutes)::integer as total from public.lessons group by course_id) s
where c.id = '776b1633-dd76-67f4-532f-87063a481f11' and s.course_id = c.id and c.estimated_duration < s.total;

update public.courses set short_description = 'Du terminal aux scripts, en passant par les droits, les services, SSH, les sauvegardes et le durcissement : le parcours pour administrer, surveiller et auditer un serveur Linux.', description = 'Ce parcours t’apprend à utiliser et à administrer un système Linux avec un regard de défenseur : te repérer dans le terminal, manipuler les fichiers et le texte, gérer les droits et les comptes, surveiller les processus et les services, mettre à jour, sécuriser l’accès à distance, sauvegarder, chiffrer, automatiser avec des scripts, puis auditer un serveur et rédiger un rapport. Neuf modules progressifs couvrent le terminal et l’arborescence, les fichiers et le traitement du texte, les droits et les utilisateurs, les processus, les services et les tâches planifiées, les logiciels et les mises à jour, le réseau, SSH et le pare-feu, le stockage, les sauvegardes et le chiffrement, les scripts shell, et l’audit d’un système Linux.

Chaque leçon propose un cours détaillé, des exemples corrigés et un quiz avec correction. Six travaux pratiques guidés, un incident à reconstituer et un projet final d’audit te font manipuler ce que tu apprends sur des exports réalistes de serveur : listings de droits, comptes, processus, journaux SSH et web, configurations, sauvegardes et scripts, avec des critères de réussite vérifiés par la plateforme.

Compétences visées : lire et filtrer des fichiers et des journaux en ligne de commande, auditer les droits et les comptes, repérer un processus ou une tâche planifiée anormale, durcir SSH et le pare-feu, juger une politique de sauvegarde, écrire et relire un script sûr, reconstituer une intrusion et noter un serveur avec une grille d’audit.

Aucun prérequis Linux : un ordinateur Windows avec WSL ou Git Bash, une machine virtuelle gratuite, ou un téléphone avec Termux suffit pour rejouer les commandes, et les travaux pratiques se font à partir de fichiers fournis, sans serveur. Les vidéos sont en préparation : chaque leçon indique clairement quand la sienne n’est pas encore disponible, et le cours écrit couvre déjà l’essentiel.'
