insert into public.course_modules (id, course_id, title, description, position) values
  ('81b15f40-49e1-bba2-e8bf-a5d6dfeee7fd', '776b1633-dd76-67f4-532f-87063a481f11', 'Fichiers et texte', 'Tu apprends ici à manipuler des fichiers et à faire parler du texte sans casser ton système. Le cœur du module est la méthode : prévisualiser, filtrer, comparer puis archiver proprement avant d’aller vers des usages plus sensibles. Critères de réussite : déplacer et supprimer avec prudence ; retrouver une information utile dans un journal ou un CSV ; construire un pipeline simple avec « grep », « sort », « uniq », « awk » et « find ».', 2),
  ('b627b2dc-a183-e111-0a15-c8b9bcb32c3c', '776b1633-dd76-67f4-532f-87063a481f11', 'Processus et services', 'Ce module te donne une lecture opérationnelle de ce qui tourne, démarre et se planifie sur un système Linux. Critères de réussite : identifier un processus ou un service inhabituel ; distinguer action immédiate et démarrage automatique ; calculer le comportement d’une tâche planifiée et juger son risque.', 4),
  ('78ad27d1-b01f-0f1a-dcfa-425e9cd3350a', '776b1633-dd76-67f4-532f-87063a481f11', 'Logiciels et mises à jour', 'Ce module t’apprend à faire confiance avec méthode : d’où viennent les paquets, comment appliquer un correctif et comment vérifier qu’il protège réellement le système. Critères de réussite : distinguer dépôt, paquet et signature ; lire des mises à jour en attente et leur source ; décider quand un service ou le noyau doit être relancé après correction.', 5),
  ('49f77eed-6e73-8f18-15b6-259a2c2d2cb9', '776b1633-dd76-67f4-532f-87063a481f11', 'Réseau et accès à distance', 'Tu y développes une lecture défensive du réseau Linux : interfaces, routes, ports, SSH et filtrage local, toujours avec le moindre privilège en tête. Critères de réussite : diagnostiquer du poste au service sans brûler les étapes ; sécuriser l’accès SSH sans se verrouiller dehors ; relire des règles de pare-feu et en déduire l’exposition réelle.', 6),
  ('35577acc-dd9f-fb64-5e46-c4db2e0534b8', '776b1633-dd76-67f4-532f-87063a481f11', 'Stockage, sauvegardes et chiffrement', 'Ce module relie disponibilité et confidentialité : lire les volumes, protéger la capacité, sauvegarder avec vérification et choisir le bon niveau de chiffrement selon le besoin. Critères de réussite : interpréter « lsblk », « df » et « fstab » ; juger si une sauvegarde est vraiment restaurable ; choisir entre empreinte, signature, chiffrement de fichier et chiffrement de volume.', 7),
  ('5cfc6ce3-ee6c-80e9-8659-bda9989f2329', '776b1633-dd76-67f4-532f-87063a481f11', 'Scripts shell', 'Ce module te fait passer de la commande ponctuelle à l’automatisation défensive lisible et testée. Critères de réussite : écrire un script Bash qui prend des arguments, corriger un défaut de guillemets ou de gestion d’erreur, et produire une alerte ou un rapport simple réutilisable par un autre administrateur.', 8)
insert into public.lessons (id, course_id, module_id, title, summary, content, duration_minutes, xp_reward, position) values
  ('f638f916-d05f-bae5-b2cd-9ac3e323da67', '776b1633-dd76-67f4-532f-87063a481f11', '62477308-a201-76f1-057c-f297445d9139', 'Linux, distributions et environnements : s’exercer gratuitement', 'Comprends ce qu’est Linux, comment choisir une distribution, et comment t’exercer sans risque depuis Windows, une machine virtuelle ou un téléphone Android.', '{"blocks":[{"type":"callout","content":"Objectifs : définir le noyau Linux et une distribution, distinguer Ubuntu, Debian, Fedora, RHEL et Arch, choisir un environnement d’entraînement gratuit, identifier le système utilisé, et expliquer pourquoi Linux compte dans un métier de défenseur."},{"type":"callout","content":"Prérequis : aucun."},{"type":"callout","content":"Mise en situation : Awa aide Baobab Tech à préparer un futur serveur web, mais elle travaille encore sur un poste Windows et n’a pas de machine dédiée. Son collègue Moussa n’a qu’un vieux portable, et Fatou n’a parfois que son téléphone Android. Avant d’apprendre des commandes, l’équipe doit choisir un terrain d’exercice gratuit, réaliste et sans danger pour la machine de travail."},{"type":"callout","content":"Vidéo à venir : Découvrir Linux et choisir un environnement d’entraînement sûr"},{"type":"text","content":"Linux est d’abord un noyau : la partie du système qui parle au matériel, gère la mémoire, les processus et les périphériques. Une distribution ajoute autour du noyau des outils, un gestionnaire de paquets, des réglages et une documentation. Ubuntu et Debian appartiennent à la même famille et servent souvent de base pour des serveurs ou des laboratoires. Fedora et RHEL représentent une autre grande famille, très présente en entreprise. Arch est plus minimaliste et très pédagogique, mais moins simple pour un débutant pressé."},{"type":"schema","content":"Noyau Linux\n   +\nOutils, paquets, configuration, documentation\n   =\nDistribution\n\nFamilles courantes\nDebian, Ubuntu : apprentissage et serveurs courants\nRHEL, Fedora   : entreprise, dnf, SELinux\nArch           : système très manuel, très formateur"},{"type":"text","content":"Un défenseur doit connaître Linux parce que beaucoup de services en ligne, de journaux, de conteneurs, d’outils d’audit et de systèmes embarqués reposent dessus. Android utilise lui aussi un noyau Linux, même si son interface ne ressemble pas à un serveur. Linux est un logiciel libre : le code source peut être lu, étudié et redistribué selon sa licence. Cela n’assure pas la sécurité par magie, mais permet d’inspecter et d’améliorer les briques utilisées."},{"type":"text","content":"Pour t’exercer gratuitement, trois options reviennent souvent. Sous Windows, Microsoft documente l’installation de WSL avec « wsl --install » dans un terminal ouvert en administrateur, puis un redémarrage : c’est pratique pour apprendre les commandes et les chemins, mais il faut rester prudent sur les prérequis et la version de Windows, donc suis la page officielle. Une machine virtuelle avec VirtualBox isole mieux les essais et permet de prendre un instantané avant une manipulation risquée. Termux sur Android donne un vrai terminal et beaucoup d’outils, mais ce n’est pas une distribution Linux classique : pas de systemd, pas de vrais droits root, et une arborescence différente de Debian ou Ubuntu. Une clé USB « live » et les conteneurs existent aussi : le premier sert à essayer sans installer, le second sert à lancer vite un environnement applicatif, pas à remplacer tout un serveur d’apprentissage."},{"type":"schema","content":"Choix rapide\nWSL               : pratique sous Windows, installation guidée\nMachine virtuelle : plus fidèle, instantané avant essai\nTermux            : utile sur téléphone, limites franches\nLive USB          : essai temporaire sans installation\nConteneur         : utile pour une appli, pas pour tout le système"},{"type":"text","content":"Démonstration guidée : ouvre un terminal d’une vraie distribution, par exemple dans WSL, une machine virtuelle ou Termux, puis lis quatre informations de base. « uname -a » décrit le noyau, « cat /etc/os-release » annonce la distribution, « hostname » donne le nom de la machine et « whoami » te rappelle avec quel compte tu travailles. Si tu n’as que Git Bash sous Windows, garde-le pour t’entraîner au shell, puis refais cette lecture dans un vrai environnement Linux dès que possible."},{"type":"code","content":"# lire le noyau et la distribution\nuname -a\ncat /etc/os-release\nhostname\nwhoami\n\n# exemple de sortie (valeurs fictives)\n# Linux portable-awa 6.8.0-45-generic #45-Ubuntu SMP PREEMPT_DYNAMIC Mon Aug 12 10:00:00 UTC 2026 x86_64 x86_64 x86_64 GNU/Linux\n# PRETTY_NAME=\"Ubuntu 24.04.1 LTS\"\n# NAME=\"Ubuntu\"\n# portable-awa\n# awa","language":"bash"},{"type":"example","content":"Exemple corrigé : poste Windows récent de bureau, choisis WSL si tu veux apprendre vite les commandes et les chemins sans réinstaller la machine. Vieux portable récupéré, préfère une machine virtuelle légère ou même une installation Linux dédiée si l’ordinateur ne sert plus à autre chose. Téléphone Android seul, Termux est mieux que rien pour lire, filtrer et écrire de petits scripts, mais il ne remplace pas un serveur complet pour « systemctl », les services réseau ou les droits d’administration."},{"type":"callout","content":"Erreurs fréquentes : installer Linux sur le disque principal sans sauvegarde préalable ; croire que Termux reproduit exactement un serveur Debian ou Ubuntu ; copier des commandes sans lire les options ; oublier de prendre un instantané de machine virtuelle avant les expériences plus risquées."},{"type":"callout","content":"Sécurité : entraîne-toi sur ta propre machine, ta machine virtuelle ou un environnement explicitement autorisé. Avant une expérience qui touche au stockage ou au réseau, fais une sauvegarde ou au minimum un instantané. Un environnement de test sert à apprendre sans casser le poste de production."},{"type":"callout","content":"À retenir : Linux est un noyau, une distribution est un système complet construit autour de ce noyau. Ubuntu, Debian, Fedora et RHEL reviennent souvent en administration. WSL, la machine virtuelle et Termux sont trois portes d’entrée utiles, mais avec des limites différentes."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 1 : explorer l’arborescence et chercher dans les fichiers », puis refais la partie découverte de l’environnement : repère où tu es, quel compte tu utilises et quels fichiers de base sont présents. Termine par le quiz de la leçon."},{"type":"resource","content":"Microsoft : installer WSL pour utiliser Linux sous Windows","url":"https://learn.microsoft.com/fr-fr/windows/wsl/install"},{"type":"resource","content":"VirtualBox : manuel de l’utilisateur (en anglais)","url":"https://www.virtualbox.org/manual/"},{"type":"resource","content":"Termux : un terminal Linux sur Android (en anglais)","url":"https://termux.dev/"}]}'::jsonb, 22, 30, 1),
  ('3ac2de8c-8efe-cb68-9862-50f315950e7b', '776b1633-dd76-67f4-532f-87063a481f11', '62477308-a201-76f1-057c-f297445d9139', 'Le terminal et le shell : lire une commande et trouver de l’aide', 'Apprends à décortiquer une commande Linux, à trouver de l’aide fiable, et à utiliser l’historique, les guillemets et le code de retour sans te piéger.', '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître les parties d’une commande, utiliser « man », « --help », « type » et « which », lire une invite de shell, expliquer le rôle de PATH et du code de retour, et interrompre proprement une commande."},{"type":"callout","content":"Prérequis : avoir suivi « Linux, distributions et environnements : s’exercer gratuitement » ou déjà disposer d’un terminal Linux, WSL, machine virtuelle ou Termux."},{"type":"callout","content":"Mise en situation : Nadia reçoit une ligne copiée dans un groupe de discussion : « grep -rn motdepasse /home/awa/notes ». Elle voit bien des mots connus, mais ne sait pas encore ce qui est le programme, l’option ou l’argument. Comme elle devra un jour lire des commandes d’audit, de sauvegarde ou de dépannage, elle veut comprendre avant d’exécuter."},{"type":"callout","content":"Vidéo à venir : Lire une commande Linux sans paniquer"},{"type":"text","content":"Le terminal est la fenêtre dans laquelle tu écris des commandes. Le shell, souvent bash, est l’interpréteur qui lit ce que tu tapes puis lance les programmes. Une invite comme « awa@portable-awa:~$ » indique souvent l’utilisateur, la machine et le dossier courant. Le symbole « $ » rappelle qu’il s’agit d’un compte ordinaire. Le symbole « # » est généralement utilisé pour root : c’est un signal à prendre au sérieux, pas un décor."},{"type":"schema","content":"Commande : grep -rn motdepasse /home/awa/notes\n\ngrep              : programme lancé\n-r                : option courte\n-n                : option courte\nmotdepasse        : motif recherché\n/home/awa/notes   : argument, ici le dossier à parcourir"},{"type":"text","content":"Quand tu ne connais pas une commande, commence par l’aide. « man ls » ouvre le manuel, « /mot » cherche dans la page, « n » passe au résultat suivant et « q » quitte. « ls --help » donne un résumé plus court. « apropos archive » cherche des pages de manuel par mot-clé. « type grep » dit si « grep » est une commande interne du shell, un alias ou un programme, et « which grep » montre le chemin du binaire trouvé via PATH. Ce PATH est une liste de dossiers que le shell parcourt pour trouver un programme : y ajouter « . », le dossier courant, est une très mauvaise habitude, car tu pourrais lancer un faux programme simplement en te trouvant dans le mauvais dossier."},{"type":"text","content":"Le shell effectue aussi des traitements avant de lancer un programme. Les jokers comme « * » sont développés, les variables d’environnement sont remplacées, puis la commande est exécutée. Les guillemets simples gardent le texte presque tel quel. Les guillemets doubles laissent encore passer des variables comme « $HOME ». Attention : les jokers du shell et les motifs de « grep » ne parlent pas le même langage. Si tu veux chercher littéralement un motif, protège-le d’abord des expansions du shell. Quand une commande échoue, regarde son message d’erreur puis son code de retour avec « echo $? ». En général, 0 signifie succès. Tu peux enchaîner avec « ; » pour lancer plusieurs commandes l’une après l’autre, ou avec « && » pour n’exécuter la seconde que si la première a réussi."},{"type":"schema","content":"Raccourcis utiles\nTab        : complète un nom de commande ou de fichier\nFlèche haut : relit une commande précédente\nCtrl+R     : cherche dans l’historique\nCtrl+C     : interrompt la commande courante\nCtrl+L     : efface l’écran sans fermer le shell"},{"type":"text","content":"Démonstration guidée : quand tu découvres un outil, interroge d’abord le shell au lieu d’improviser. Regarde de quel type de commande il s’agit, où elle se trouve, puis teste une aide courte. Cette discipline paraît lente au début, mais elle évite beaucoup de copier-coller aveugle et t’apprend à lire la documentation officielle directement depuis le terminal."},{"type":"code","content":"# identifier une commande\ntype grep\nwhich grep\nls --help | head -n 3\n\n# exemple de sortie (valeurs fictives)\n# grep is /usr/bin/grep\n# /usr/bin/grep\n# Usage: ls [OPTION]... [FILE]...\n# List information about the FILEs (the current directory by default).\n# Sort entries alphabetically if none of -cftuvSUX nor --sort is specified.","language":"bash"},{"type":"example","content":"Exemple corrigé : dans « grep -rn motdepasse /home/awa/notes », « grep » est le programme, « -r » demande de parcourir récursivement les sous-dossiers et « -n » d’afficher les numéros de ligne. « motdepasse » est le motif recherché, et « /home/awa/notes » le dossier cible. Si Nadia oublie qu’un mot avec espace doit être protégé par des guillemets, le shell le coupera en plusieurs arguments avant même que « grep » ne démarre."},{"type":"callout","content":"Erreurs fréquentes : confondre une option et un argument ; ignorer le message d’erreur pour relancer exactement la même commande ; travailler en root par habitude ; coller directement une commande trouvée sur un site sans l’avoir d’abord lue dans un éditeur ou comprise option par option."},{"type":"callout","content":"Sécurité : une commande collée depuis un site ou une messagerie peut cacher des retours à la ligne ou des caractères trompeurs. Colle-la d’abord dans un éditeur, relis-la, puis comprends ce qu’elle fera. Utilise « sudo » seulement quand tu sais pourquoi il est nécessaire."},{"type":"callout","content":"À retenir : Le shell n’est pas magique : il lit, développe puis lance une commande précise. « man », « --help », « type » et « which » sont tes premiers réflexes. Un code de retour et un message d’erreur valent souvent plus qu’une intuition."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 1 : explorer l’arborescence et chercher dans les fichiers », puis prends chaque commande demandée et décompose-la comme dans la leçon : programme, options, arguments et résultat attendu. Termine par le quiz de la leçon."},{"type":"resource","content":"Ubuntu : tutoriel de la ligne de commande pour débutants (en anglais)","url":"https://ubuntu.com/tutorials/command-line-for-beginners"},{"type":"resource","content":"Linux : manuel de l’interpréteur bash (en anglais)","url":"https://man7.org/linux/man-pages/man1/bash.1.html"},{"type":"resource","content":"GNU : le manuel de référence de Bash (en anglais)","url":"https://www.gnu.org/software/bash/manual/bash.html"}]}'::jsonb, 22, 30, 2),
  ('3051c24b-403b-e40b-cb1a-a07b924c1519', '776b1633-dd76-67f4-532f-87063a481f11', '81b15f40-49e1-bba2-e8bf-a5d6dfeee7fd', 'Créer, copier, déplacer et supprimer sans rien casser', 'Maîtrise les commandes de base pour manipuler des fichiers et des dossiers, avec les bons réflexes de prudence avant une copie, un renommage ou une suppression.', '{"blocks":[{"type":"callout","content":"Objectifs : utiliser « mkdir », « touch », « cp », « mv », « rm », « rmdir » et « ln -s », expliquer les jokers et les accolades, prévisualiser une suppression avec le shell, et protéger les noms contenant des espaces ou commençant par un tiret."},{"type":"callout","content":"Prérequis : avoir suivi « Naviguer dans le système de fichiers Linux » ou savoir te déplacer dans une arborescence simple."},{"type":"callout","content":"Mise en situation : Fatou doit ranger des exports reçus de plusieurs équipes dans « /srv/atelier ». Les fichiers arrivent avec des extensions mélangées, certains noms contiennent des espaces, et une collègue lui demande de supprimer les doublons. Pour éviter un effacement irréversible, elle veut une méthode où chaque étape se vérifie avant la suivante."},{"type":"callout","content":"Vidéo à venir : Manipuler des fichiers Linux sans accident"},{"type":"text","content":"Pour créer un dossier, utilise « mkdir ». Avec « -p », la commande crée aussi les parents manquants. « touch » crée un fichier vide ou met à jour sa date. « cp » copie : « -r » est nécessaire pour un dossier, et « -i » demande confirmation avant d’écraser. « mv » déplace ou renomme selon la destination : si elle est un dossier existant, le fichier y entre ; sinon il prend ce nouveau nom. « rm » supprime, « rm -i » demande confirmation, « rmdir » ne supprime qu’un dossier vide. « ln -s » crée un lien symbolique, c’est-à-dire un raccourci vers un autre chemin. Garde toujours en tête qu’il n’y a pas de corbeille intégrée dans « rm » : une suppression réussie est en général définitive."},{"type":"schema","content":"Commandes de base\nmkdir -p dossiers/archives\ntouch note.txt\ncp -i rapport.txt rapport.txt.bak\ncp -r source/ copie/\nmv ancien.txt nouveau.txt\nrm -i fichier.txt\nrmdir dossier_vide\nln -s /srv/atelier/config.conf config-actuelle"},{"type":"text","content":"Le shell développe les jokers avant d’appeler la commande. « * » signifie « n’importe quelle suite de caractères », « ? » un seul caractère et « [abc] » un caractère parmi plusieurs. Les accolades, comme dans « facture-{01..03}.txt », servent à générer plusieurs noms. Ces jokers sont ceux du shell : ils ne se comportent pas comme les motifs de « grep ». Avant une suppression, « echo *.txt » montre ce que le shell sélectionnera vraiment. C’est une habitude simple qui évite de supprimer plus que prévu."},{"type":"text","content":"Pour écrire vite un petit fichier, tu peux utiliser « cat > note.txt », taper le contenu, puis finir avec Ctrl+D. « nano » est plus confortable pour modifier : Ctrl+O enregistre, Ctrl+X quitte. Deux pièges reviennent souvent. Le premier concerne les espaces : sans guillemets, « Rapport final.txt » devient deux arguments séparés. Le second concerne les noms qui commencent par un tiret : un fichier nommé « -rapport.txt » peut être pris pour une option. Dans ce cas, ajoute « -- » avant le nom pour dire à la commande que les options sont terminées. De manière générale, fais une copie de sauvegarde avant de modifier un fichier de configuration, par exemple « cp fichier fichier.bak »."},{"type":"text","content":"Démonstration guidée : travaille dans un dossier d’essai créé avec « mktemp -d », puis vérifie chaque résultat. Crée une arborescence, prévisualise un groupe de fichiers, classe-les par type et relis le résultat avec « find ». Cette discipline te servira aussi plus tard pour préparer une sauvegarde ou nettoyer des journaux sans toucher à la production."},{"type":"code","content":"# préparer un dossier d’essai\nworkdir=$(mktemp -d)\ncd \"$workdir\"\nmkdir -p notes source/{images,textes,archives}\ntouch notes/guide.txt notes/lecture.txt notes/photo.jpg notes/tableau.csv\n\n# prévisualiser puis classer\ncd notes\nprintf ''%s\\n'' *.txt\nmv -- *.jpg ../source/images/\nmv -- *.txt ../source/textes/\nmv -- *.csv ../source/archives/\ncd \"$workdir\"\nfind source -maxdepth 2 -type f | sort\n\n# exemple de sortie (valeurs fictives)\n# guide.txt\n# lecture.txt\n# source/archives/tableau.csv\n# source/images/photo.jpg\n# source/textes/guide.txt\n# source/textes/lecture.txt","language":"bash"},{"type":"example","content":"Exemple corrigé : pour trier 12 fichiers en 3 dossiers, tu peux d’abord créer « images », « textes » et « archives », puis déplacer « *.jpg » vers le premier, « *.txt » vers le second et « *.csv », « *.zip » et « *.tar.gz » vers le troisième. Le résultat attendu est celui montré par « find » : 3 images, 4 textes et 5 archives. Ce tri fonctionne parce que les jokers sont évalués par le shell avant « mv »."},{"type":"callout","content":"Erreurs fréquentes : utiliser « rm » sans avoir d’abord listé ce que le joker vise ; croire que « mv » ne fait que renommer alors qu’il peut aussi déplacer ; oublier les guillemets autour d’un nom avec espace ; réutiliser une variable vide dans une commande destructive au lieu de vérifier sa valeur avant."},{"type":"callout","content":"Sécurité : supprimer récursivement doit rester une opération exceptionnelle et préparée. Vérifie le dossier cible avec « pwd » et « ls » avant toute suppression large. Sur un fichier de configuration, préfère une copie « .bak » et un dossier de test à une modification directe en production."},{"type":"callout","content":"À retenir : Créer, copier, déplacer et supprimer sont des gestes simples seulement quand tu vérifies d’abord les chemins et les jokers. Le shell prépare les arguments avant le programme. Les guillemets, « -- » et une copie de sauvegarde évitent beaucoup d’accidents."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 1 : explorer l’arborescence et chercher dans les fichiers », puis refais la partie rangement et reconstitution de chemins avant les filtres sur journaux et CSV. Termine par le quiz de la leçon."},{"type":"resource","content":"Ubuntu-fr : les commandes de base de la console","url":"https://doc.ubuntu-fr.org/tutoriel/console_commandes_de_base"},{"type":"resource","content":"Linux : manuel de la commande ln (en anglais)","url":"https://man7.org/linux/man-pages/man1/ln.1.html"},{"type":"resource","content":"GNU : le manuel des coreutils (en anglais)","url":"https://www.gnu.org/software/coreutils/manual/coreutils.html"}]}'::jsonb, 22, 30, 1),
  ('aa1266fd-0742-e5a4-2295-cc48b368ed14', '776b1633-dd76-67f4-532f-87063a481f11', '81b15f40-49e1-bba2-e8bf-a5d6dfeee7fd', 'Lire et chercher dans du texte : less, tail et grep', 'Lis rapidement un journal ou un export, puis retrouve des lignes utiles avec « less », « head », « tail », « wc » et « grep » sans te perdre dans le volume.', '{"blocks":[{"type":"callout","content":"Objectifs : utiliser « cat », « less », « head », « tail », « wc -l » et « grep », expliquer les options « -i », « -n », « -v », « -c », « -r », « -E » et « -w », lire une expression régulière simple, et interpréter le code de retour de « grep »."},{"type":"callout","content":"Prérequis : avoir suivi « Créer, copier, déplacer et supprimer sans rien casser » ou déjà savoir ouvrir un fichier texte depuis le terminal."},{"type":"callout","content":"Mise en situation : Mamadou reçoit un extrait de journal SSH, un fichier CSV et plusieurs notes de configuration. Les fichiers sont trop longs pour être lus avec « cat » d’un seul bloc, et il veut d’abord retrouver les échecs de connexion puis vérifier si un mot de passe en clair traîne dans ses propres dossiers de test. Il lui faut donc des commandes de lecture et de recherche rapides, pas une lecture ligne par ligne à l’aveugle."},{"type":"callout","content":"Vidéo à venir : Chercher dans un journal Linux avec less, tail et grep"},{"type":"text","content":"« cat » affiche un fichier tel quel, ce qui devient vite pénible sur un gros journal. « less » est plus adapté : tu défiles avec les flèches, tu cherches avec « /mot », tu répètes avec « n », tu vas au début avec « g », à la fin avec « G », puis tu quittes avec « q ». « head -n » montre les premières lignes, « tail -n » les dernières et « tail -f » suit un journal qui grandit. « wc -l » compte les lignes : c’est utile pour mesurer rapidement la taille d’un fichier avant de choisir l’outil."},{"type":"schema","content":"Repères de lecture\nhead -n 5 journal.log  : voir le début\ntail -n 20 journal.log : voir la fin\nless journal.log       : lire et chercher\nwc -l journal.log      : compter les lignes\n\ngrep utile\ngrep -n motif fichier            : afficher le numéro de ligne\ngrep -c motif fichier            : compter les lignes qui correspondent\ngrep -v motif fichier            : exclure\ngrep -E ''motif1|motif2'' fichier  : alternatives"},{"type":"text","content":"« grep » cherche un motif dans du texte. Avec « -i », la casse est ignorée. Avec « -n », le numéro de ligne apparaît. « -c » compte les lignes qui correspondent, et non le nombre total d’occurrences sur une même ligne, puis « -r » parcourt récursivement un dossier. « -w » demande un mot entier. Les guillemets autour du motif évitent que le shell interprète certains caractères avant « grep ». C’est important, car « *.log » n’est pas un joker de shell une fois passé à « grep » : c’est une expression régulière qui ne veut pas dire la même chose. Les expressions régulières simples suffisent déjà souvent : « ^ » pour le début de ligne, « $ » pour la fin, « . » pour un caractère quelconque, « * » pour une répétition et « [ ] » pour une classe de caractères. Avec « -E », tu peux écrire une alternative comme « erreur|warning »."},{"type":"text","content":"Le code de retour de « grep » est très utile dans un script ou un audit rapide : 0 si le motif a été trouvé, 1 si rien ne correspond, et 2 avec GNU grep en cas d’erreur de lecture ou de syntaxe. Pour de la sécurité défensive, « grep » sert à retrouver des échecs de connexion dans un journal d’authentification, à repérer des secrets oubliés dans ses propres fichiers, par exemple avec « grep -rn ''password'' ~/projets », ou à extraire les lignes d’un CSV avant un autre traitement. Évite en revanche de lire un journal volumineux avec « cat » puis de défiler pendant des minutes : commence par cibler."},{"type":"text","content":"Démonstration guidée : lis d’abord deux lignes pour reconnaître le format, puis filtre. Sur l’extrait suivant, « head » donne le début du journal, « grep -n » montre les lignes d’échec pour un compte précis, et « grep -c » t’indique combien d’échecs il y a au total. Cette progression fonctionne aussi bien dans WSL, en machine virtuelle, dans Termux ou sur un vrai serveur où tu n’as pas envie de faire défiler 50 000 lignes à la main."},{"type":"code","content":"# reconnaître le format puis filtrer\nhead -n 2 auth.log\ngrep -n ''Failed password for nadia'' auth.log\ngrep -c ''Failed password'' auth.log\ntail -n 3 auth.log\n\n# exemple de sortie (valeurs fictives)\n# Oct 03 09:10:01 srv-demo sshd[101]: Failed password for nadia from 192.168.1.20 port 55210 ssh2\n# Oct 03 09:10:08 srv-demo sshd[102]: Failed password for invalid user admin from 192.168.1.21 port 55211 ssh2\n# 1:Oct 03 09:10:01 srv-demo sshd[101]: Failed password for nadia from 192.168.1.20 port 55210 ssh2\n# 4:Oct 03 09:10:18 srv-demo sshd[104]: Failed password for nadia from 192.168.1.20 port 55213 ssh2\n# 7:Oct 03 09:10:33 srv-demo sshd[107]: Failed password for nadia from 192.168.1.20 port 55216 ssh2\n# 10:Oct 03 09:11:02 srv-demo sshd[110]: Failed password for nadia from 192.168.1.20 port 55219 ssh2\n# 7\n# Oct 03 09:10:41 srv-demo sshd[108]: Failed password for invalid user test from 172.16.5.4 port 55217 ssh2\n# Oct 03 09:10:55 srv-demo sshd[109]: Accepted publickey for koffi from 192.168.1.23 port 55218 ssh2: ED25519 SHA256:test456\n# Oct 03 09:11:02 srv-demo sshd[110]: Failed password for nadia from 192.168.1.20 port 55219 ssh2","language":"bash"},{"type":"example","content":"Exemple corrigé : sur cet extrait de 10 lignes, Nadia apparaît 4 fois dans des lignes « Failed password ». La commande « grep -c ''Failed password for nadia'' auth.log » renvoie donc 4. Ce nombre est utile pour un premier tri, mais ne prouve pas à lui seul une compromission : il faut encore regarder les adresses IP, la période et d’éventuelles lignes de succès."},{"type":"callout","content":"Erreurs fréquentes : oublier les guillemets autour d’un motif contenant des caractères spéciaux ; confondre le motif recherché avec une chaîne littérale plus large que prévu ; lire un énorme journal avec « cat » au lieu d’utiliser « less », « head » ou « tail » ; oublier qu’un fichier binaire n’est pas agréable à lire avec des outils prévus pour du texte."},{"type":"callout","content":"Sécurité : cherche des secrets ou des mots comme « password » seulement dans tes propres fichiers, tes exports de laboratoire ou un environnement autorisé. Un simple « grep -rn » peut révéler des données personnelles ou des identifiants, donc manipule les résultats avec la même prudence que les fichiers d’origine."},{"type":"callout","content":"À retenir : Pour lire vite, commence par « head », « tail » ou « less ». Pour chercher, « grep » reste l’outil central, surtout avec « -n », « -c », « -i » et « -E ». Un bon filtrage remplace des minutes de défilement aveugle."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 1 : explorer l’arborescence et chercher dans les fichiers », puis concentre-toi sur la partie filtrage de journal, historique de commandes et fichier CSV avec « grep », « sort », « uniq » et « awk ». Termine par le quiz de la leçon."},{"type":"resource","content":"Ubuntu-fr : les commandes de base de la console","url":"https://doc.ubuntu-fr.org/tutoriel/console_commandes_de_base"},{"type":"resource","content":"Linux : manuel de la commande grep (en anglais)","url":"https://man7.org/linux/man-pages/man1/grep.1.html"},{"type":"resource","content":"Linux : regex(7), les expressions régulières (en anglais)","url":"https://man7.org/linux/man-pages/man7/regex.7.html"}]}'::jsonb, 22, 30, 2),
  ('d74434e9-8226-0a66-6d20-71a5f0a6aed8', '776b1633-dd76-67f4-532f-87063a481f11', '81b15f40-49e1-bba2-e8bf-a5d6dfeee7fd', 'Redirections et tubes : composer des commandes', 'Comprends les flux standard, puis compose des filtres avec redirections, tubes, « sort », « uniq », « cut », « tr », « wc », « awk », « tee » et « xargs ».', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer entrée, sortie et erreur standard, utiliser « > », « >> », « 2> », « 2>&1 » et « | », construire un pipeline pas à pas, expliquer pourquoi « uniq -c » attend un tri, et extraire une colonne utile avec « cut » ou « awk »."},{"type":"callout","content":"Prérequis : avoir suivi « Lire et chercher dans du texte : less, tail et grep » ou déjà savoir retrouver des lignes dans un fichier."},{"type":"callout","content":"Mise en situation : Rokia reçoit un export d’accès web et un CSV d’inscrits. Elle ne veut pas écrire un script complet pour chaque question simple : top des adresses, nombre d’inscrits par ville, lignes à exclure. Elle a besoin d’une boîte à outils pour faire parler le texte en plusieurs petites étapes vérifiables."},{"type":"callout","content":"Vidéo à venir : Composer des commandes Linux avec des tubes et des redirections"},{"type":"text","content":"Chaque commande travaille avec trois flux standard : l’entrée standard 0, la sortie standard 1 et l’erreur standard 2. « > » redirige la sortie vers un fichier en l’écrasant, « >> » ajoute à la fin, « 2> » redirige seulement l’erreur et « 2>&1 » fusionne l’erreur avec la sortie. « < » fournit un fichier en entrée. « /dev/null » agit comme une poubelle pour une sortie dont tu ne veux pas. Ces gestes simples suffisent déjà à capter un rapport ou à faire taire un bruit inutile, à condition de te souvenir que « > » écrase."},{"type":"schema","content":"Flux standard\n0 : entrée standard\n1 : sortie standard\n2 : erreur standard\n\nExemples\ncommande > rapport.txt      : écrase rapport.txt\ncommande >> rapport.txt     : ajoute en fin de fichier\ncommande 2> erreurs.log     : garde seulement les erreurs\ncommande > tout.log 2>&1    : fusionne sortie et erreur"},{"type":"text","content":"Le tube « | » envoie la sortie d’une commande vers l’entrée de la suivante. C’est la base de la philosophie Unix : faire une chose simple, puis combiner. « sort » trie, « uniq -c » compte les doublons mais seulement si les lignes identiques sont déjà regroupées, « cut -d, -f3 » extrait une colonne selon un séparateur, « tr » transforme des caractères, « wc » compte, « head » garde le début et « awk ''{print $1}'' » extrait vite la première colonne. « tee » duplique la sortie vers l’écran et un fichier. « xargs » transforme des lignes d’entrée en arguments, ce qui est puissant mais demande de la prudence, surtout avec les espaces et les caractères spéciaux."},{"type":"text","content":"La bonne méthode est de construire un pipeline maillon par maillon. Lance d’abord « awk ''{print $1}'' acces.log » et vérifie. Ajoute ensuite « sort », relis, puis « uniq -c », puis le tri numérique final. Ainsi, si le résultat devient bizarre, tu sais à quel étage il faut corriger. Cette méthode compte aussi pour des commandes défensives plus sensibles, comme des recherches de fichiers ou des listes à archiver."},{"type":"text","content":"Démonstration guidée : voici un pipeline classique pour obtenir le top des adresses vues dans un journal d’accès. La première commande extrait la première colonne, la seconde trie, la troisième compte les répétitions, la quatrième retrie numériquement en ordre décroissant et « head -5 » ne garde que les cinq premières lignes. La sortie ci-dessous a été relue étape par étape, ce qui est exactement la discipline à garder en administration."},{"type":"code","content":"# top des adresses dans un journal d’accès\nawk ''{print $1}'' access.log | sort | uniq -c | sort -rn | head -5\n\n# exemple de sortie (valeurs fictives)\n#       4 10.1.0.8\n#       3 192.168.1.20\n#       2 172.16.5.4\n#       1 192.168.1.21","language":"bash"},{"type":"text","content":"Un CSV se traite souvent avec « cut » et un tri. Sur « inscrits.csv », « cut -d, -f3 » extrait la colonne ville. « tail -n +2 » saute l’en-tête, puis « sort | uniq -c | sort -rn » donne le nombre d’inscrits par ville. « tr ''A-Z'' ''a-z'' » sert par exemple à normaliser la casse avant de compter. Garde cependant en tête qu’un CSV réel peut contenir des virgules internes ou des guillemets : pour un format irrégulier, un parseur dédié est plus fiable qu’un pipeline improvisé."},{"type":"code","content":"# compter des lignes par ville dans un CSV simple\ncut -d, -f3 inscrits.csv | tail -n +2 | sort | uniq -c | sort -rn\nprintf ''ALERTE SSH\\n'' | tr ''A-Z'' ''a-z''\n\n# exemple de sortie (valeurs fictives)\n#       4 Dakar\n#       2 Lome\n#       2 Abidjan\n#       1 Cotonou\n# alerte ssh","language":"bash"},{"type":"example","content":"Exemple corrigé : sur le CSV d’exemple, Dakar apparaît 4 fois, Lome 2 fois, Abidjan 2 fois et Cotonou 1 fois. Sans le premier « sort », « uniq -c » ne compterait pas correctement des valeurs identiques dispersées dans le fichier. Le piège classique est donc de lire « uniq » comme un compteur universel, alors qu’il ne voit que les répétitions déjà consécutives."},{"type":"callout","content":"Erreurs fréquentes : oublier que « > » écrase un fichier existant ; utiliser « uniq -c » sans trier avant ; construire un pipeline complet d’un seul coup puis ne plus savoir où le résultat se déforme ; parser un format irrégulier avec « cut » sans vérifier la structure réelle du fichier."},{"type":"callout","content":"Sécurité : sur un fichier important, redirige d’abord vers un nouveau nom plutôt que d’écraser l’original. Quand tu utilises « xargs », privilégie les couples sûrs comme « -print0 » et « -0 » pour éviter les surprises avec les espaces, les retours à la ligne ou les noms inhabituels."},{"type":"callout","content":"À retenir : Les redirections commandent où vont la sortie et l’erreur. Les tubes enchaînent de petits outils spécialisés. Un bon pipeline se construit et se vérifie morceau par morceau, surtout avant un traitement qui écrira sur disque ou préparera une action plus sensible."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 1 : explorer l’arborescence et chercher dans les fichiers », puis refais les parties filtre de journal, historique et CSV en lisant chaque étape du pipeline. Termine par le quiz de la leçon."},{"type":"resource","content":"Linux : manuel de la commande sort (en anglais)","url":"https://man7.org/linux/man-pages/man1/sort.1.html"},{"type":"resource","content":"POSIX : manuel de la commande awk (en anglais)","url":"https://man7.org/linux/man-pages/man1/awk.1p.html"},{"type":"resource","content":"GNU : le manuel des coreutils (en anglais)","url":"https://www.gnu.org/software/coreutils/manual/coreutils.html"}]}'::jsonb, 24, 30, 3),
  ('3f6583c5-5716-81a0-a116-6e6fc94dd63c', '776b1633-dd76-67f4-532f-87063a481f11', '81b15f40-49e1-bba2-e8bf-a5d6dfeee7fd', 'Trouver, comparer et archiver : find, diff, tar', 'Retrouve des fichiers utiles avec « find », compare deux versions avec « diff », puis prépare et vérifie une archive « tar » sans extraire n’importe quoi.', '{"blocks":[{"type":"callout","content":"Objectifs : utiliser « find » avec « -name », « -type », « -size », « -mtime », « -user » et « -perm », lancer une action sûre avec « -exec » ou « -print0 | xargs -0 », comparer deux fichiers avec « diff » ou « cmp », et créer puis vérifier une archive avec « tar » et « sha256sum »."},{"type":"callout","content":"Prérequis : avoir suivi « Redirections et tubes : composer des commandes » ou déjà savoir enchaîner quelques filtres simples."},{"type":"callout","content":"Mise en situation : Tidiane doit retrouver d’anciens journaux, comparer deux configurations reçues à une heure d’écart et préparer une archive propre avant de la transférer. Il sait déjà lire des chemins, mais veut éviter deux erreurs fréquentes : lancer une recherche trop large sans la tester et extraire aveuglément une archive inconnue dans le mauvais dossier."},{"type":"callout","content":"Vidéo à venir : Trouver et archiver sous Linux avec prudence"},{"type":"text","content":"« find » parcourt une arborescence en testant des conditions. « -name » filtre par nom, « -type f » ou « -type d » distingue fichiers et dossiers, « -size » regarde la taille, « -mtime » l’ancienneté en jours, « -user » le propriétaire et « -perm » les droits. Commence toujours par « -print » ou simplement la recherche seule avant d’ajouter une action. Avec « -exec commande {} \\; », « find » lance la commande une fois par chemin trouvé ; avec « {} + », il peut en regrouper plusieurs. Quand un nom de fichier peut contenir des espaces, le duo « -print0 | xargs -0 » est plus sûr qu’un passage naïf à « xargs »."},{"type":"schema","content":"Modèles utiles avec find\nfind ./logs -type f -name ''*.log''\nfind /srv/atelier -type f -mtime +7\nfind /srv/atelier -type f -perm -0002\nfind /srv/atelier -type f -user awa\n\nActions\n-print                    : afficher\n-exec commande {} \\;      : agir fichier par fichier\n-print0 | xargs -0        : transmettre sans casser les noms"},{"type":"text","content":"Pour comparer deux versions d’un fichier, « diff -u » montre les lignes retirées et ajoutées, ce qui convient très bien à une configuration. « cmp » compare plus directement deux fichiers binaires ou texte et te dit s’ils diffèrent. Côté intégrité, « sha256sum » calcule une empreinte, puis « sha256sum -c » vérifie qu’un fichier correspond bien à l’empreinte attendue. Cela ne remplace pas une signature complète, mais c’est déjà un contrôle utile avant une restauration ou un transfert."},{"type":"text","content":"Une archive « tar » regroupe plusieurs fichiers dans un seul conteneur. Avec « -czf », tu crées une archive compressée en gzip. Avec « -tzf », tu listes son contenu sans l’extraire. Avec « -xzf -C dossier », tu l’extrais dans le dossier voulu. Par défaut, GNU tar retire le « / » initial des chemins absolus et l’annonce par un avertissement, sauf si tu forces « -P », mais il ne faut pas compter sur cette protection pour tout. Ce réflexe de listing avant extraction reste donc important : une archive inconnue peut contenir des chemins inattendus, voire des « ../ » qu’il faut inspecter avant de la déballer. « locate » peut trouver vite un nom si sa base est à jour, mais sa rapidité vient justement de cette base, pas d’un parcours temps réel."},{"type":"schema","content":"Avant d’extraire une archive inconnue\n1. lister avec « tar -tzf archive.tar.gz »\n2. vérifier les chemins affichés\n3. choisir un dossier cible avec « -C »\n4. vérifier l’empreinte si elle est fournie\n5. extraire seulement ensuite"},{"type":"text","content":"Démonstration guidée : sur un dossier d’essai, commence par retrouver les journaux vieux de plus de 7 jours. Compare ensuite deux fichiers de configuration avec « diff -u », liste le contenu d’une archive, puis vérifie son empreinte. Cette chaîne correspond à un vrai usage défensif : retrouver des preuves, comparer un avant et un après, puis archiver proprement sans supposer que le conteneur reçu est sain."},{"type":"code","content":"# retrouver des journaux anciens\nfind ./logs -type f -name ''*.log'' -mtime +7 | sort\n\n# comparer deux versions d’un fichier\ndiff -u comparaison/config-v1.conf comparaison/config-v2.conf\n\n# lister et vérifier une archive\ntar -tzf sauvegarde/demo.tar.gz\nsha256sum -c sauvegarde/SHA256SUMS\n\n# exemple de sortie (valeurs fictives)\n# ./logs/app/ancien.log\n# ./logs/app/tres-ancien.log\n# --- comparaison/config-v1.conf\n# +++ comparaison/config-v2.conf\n# @@ -1,2 +1,2 @@\n#  mode=prod\n# -port=8080\n# +port=9090\n# dossier/\n# dossier/a.txt\n# dossier/b.txt\n# sauvegarde/demo.tar.gz: OK","language":"bash"},{"type":"example","content":"Exemple corrigé : sur le dossier d’essai, la commande « find ./logs -type f -name ''*.log'' -mtime +7 » renvoie 2 fichiers, « ancien.log » et « tres-ancien.log ». C’est un bon point de départ pour un audit, mais pas une preuve suffisante d’incident : une date de modification se change, donc elle sert à orienter la recherche, pas à conclure seule."},{"type":"callout","content":"Erreurs fréquentes : lancer « -exec » avant d’avoir vérifié la liste produite par « find » ; extraire une archive inconnue sans la lister d’abord ; confondre comparaison de contenu et preuve d’intégrité ; oublier que « xargs » simple se casse facilement sur des noms avec espaces ou retours à la ligne."},{"type":"callout","content":"Sécurité : reste sur tes propres dossiers, tes exports de laboratoire ou un environnement autorisé. N’extrais jamais une archive inconnue directement dans un chemin sensible. Pour une recherche d’audit sur un vrai système, commence par une commande en lecture seule puis documente ce que tu trouves avant toute action."},{"type":"callout","content":"À retenir : « find » sert à retrouver vite des fichiers selon plusieurs critères, « diff » à comprendre ce qui a changé, et « tar » à regrouper ou restaurer proprement. Liste d’abord, vérifie ensuite, puis agis. En défense, la prudence de la méthode compte autant que la commande elle-même."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 1 : explorer l’arborescence et chercher dans les fichiers », puis travaille surtout la partie chemins, recherche ciblée et filtres avant de relier le tout à une petite archive de travail. Termine par le quiz de la leçon."},{"type":"resource","content":"Linux : manuel de la commande find (en anglais)","url":"https://man7.org/linux/man-pages/man1/find.1.html"},{"type":"resource","content":"Linux : manuel de la commande tar (en anglais)","url":"https://man7.org/linux/man-pages/man1/tar.1.html"},{"type":"resource","content":"Wikipédia : tar","url":"https://fr.wikipedia.org/wiki/Tar_(informatique)"}]}'::jsonb, 22, 30, 4),
  ('9c9efce7-463b-a8a6-880b-ab4af74d08dd', '776b1633-dd76-67f4-532f-87063a481f11', 'afc5997d-3502-efa2-3239-290921bbaa77', 'Utilisateurs, groupes et fichiers de comptes', 'Comprends ce que racontent « /etc/passwd », « /etc/shadow » et « /etc/group », puis repère les comptes à risque avant qu’ils ne deviennent un problème.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer compte humain, compte système et compte de service, lire une ligne de « /etc/passwd » et de « /etc/shadow », vérifier UID et groupes, puis repérer des anomalies simples lors d’un audit."},{"type":"callout","content":"Prérequis : avoir compris les permissions Linux de base et savoir qu’un service ne doit pas disposer de plus de droits que nécessaire."},{"type":"callout","content":"Mise en situation : Nadia rejoint Baobab Tech et découvre un vieux serveur Debian partagé par plusieurs collègues. Certains scripts tournent encore avec des comptes oubliés, et un ancien stagiaire a peut-être laissé un accès trop large. Avant de supprimer quoi que ce soit, Nadia doit lire correctement les fichiers de comptes et comprendre quels utilisateurs sont humains, système ou techniques."},{"type":"callout","content":"Vidéo à venir : Lire « passwd » et « shadow » sans te tromper"},{"type":"text","content":"Un compte Linux n’est pas toujours une personne. Les comptes humains servent à ouvrir une session. Les comptes système et de service lancent des tâches ou des programmes avec un périmètre réduit. L’identité réelle d’un compte repose sur son UID et son GID, pas seulement sur son nom. L’UID 0 est particulier : il donne les privilèges de root, même si le compte ne s’appelle pas « root ». Sur Debian et Ubuntu, les comptes ordinaires commencent souvent à 1000, tandis que beaucoup de comptes techniques sont en dessous."},{"type":"schema","content":"Fichier             Rôle principal\n/etc/passwd        identité du compte, UID, GID, dossier, shell\n/etc/shadow        empreinte du mot de passe et règles d’expiration\n/etc/group         groupes et membres secondaires\nCommandes utiles   whoami, id, groups, who, w, last, lastlog"},{"type":"text","content":"Une ligne de « /etc/passwd » comporte sept champs : nom, mot de passe historique, UID, GID, commentaire, dossier personnel et shell. Le plus souvent, le deuxième champ vaut « x » : cela signifie que l’empreinte du mot de passe est stockée dans « /etc/shadow ». Le shell final dit si le compte ouvre une vraie session. Un compte de service sain utilise souvent « /usr/sbin/nologin », « /sbin/nologin » ou « /bin/false » pour empêcher une connexion interactive."},{"type":"schema","content":"Exemple « /etc/passwd »\nawa:x:1001:1001:Awa Diop:/home/awa:/bin/bash\n|   | |    |    |        |         |\n|   | |    |    |        |         +-- shell\n|   | |    |    |        +------------ dossier personnel\n|   | |    |    +--------------------- commentaire\n|   | |    +-------------------------- GID principal\n|   | +------------------------------- UID\n|   +--------------------------------- empreinte dans shadow\n+------------------------------------- nom du compte"},{"type":"text","content":"« /etc/shadow » garde l’information sensible : une empreinte de mot de passe, puis des nombres liés au vieillissement. Le deuxième champ peut commencer par « $y$ » pour yescrypt, « $6$ » pour SHA-512-crypt, « $5$ » pour SHA-256-crypt, ou par un autre identifiant d’algorithme. Un « ! » signifie compte verrouillé pour la connexion par mot de passe. Un « * » signale qu’aucun mot de passe utilisable n’est prévu. Le cas grave est le champ vide : il n’y a alors pas de mot de passe. Le troisième champ compte les jours depuis le 1er janvier 1970. Par exemple, 20360 jours correspondent au 29 septembre 2025 : ce n’est pas une heure lisible pour un humain, mais c’est suffisant pour les outils comme « chage -l »."},{"type":"text","content":"Le fichier « /etc/group » complète cette lecture avec des lignes « nom:x:GID:membres ». C’est là que tu retrouves les groupes secondaires. Pour administrer proprement, retiens surtout quelques actions : « adduser » ou « useradd » créent un compte, « usermod -aG sudo awa » ajoute un groupe sans effacer les autres, « passwd » change un mot de passe, « passwd -l » le verrouille, « userdel » supprime un compte, et « chage -l awa » lit la politique d’expiration. En audit, cherche les UID 0 multiples, les comptes de service avec shell interactif, les comptes jamais utilisés et les champs de mot de passe vides."},{"type":"text","content":"Démonstration guidée : commence par ton identité réelle, puis lis trois exemples commentés. Sur WSL, une machine virtuelle ou un vrai Linux, « id » et « groups » fonctionnent sans danger. La lecture de « /etc/shadow » demande en revanche les droits d’administration et reste à réserver à ta machine ou à un serveur de test autorisé."},{"type":"code","content":"# Voir ton identité et tes groupes\nwhoami\nid\ngroups\n\n# Lire quelques comptes\ngetent passwd | head -3\nsudo getent shadow | head -3\n# exemple de sortie (valeurs fictives)\n# root:x:0:0:root:/root:/bin/bash\n# awa:x:1001:1001:Awa Diop:/home/awa:/bin/bash\n# backup:x:998:998:Sauvegarde:/var/backups:/usr/sbin/nologin\n# root:$y$j9T$sel$abcd...:20310:0:99999:7:::\n# awa:$y$j9T$sel$efgh...:20360:0:99999:7:::\n# backup:!:20310:0:99999:7:::\n\n# Voir le vieillissement d’un compte\nsudo chage -l awa","language":"bash"},{"type":"example","content":"Exemple corrigé : « audit:x:0:0:Compte audit:/home/audit:/bin/bash » est risqué, car ce compte possède l’UID 0. « nadia::20360:0:99999:7::: » est critique, car le champ de mot de passe est vide. « backup:!:20310:0:99999:7::: » est au contraire cohérent pour un compte technique verrouillé. Lors d’un audit, cherche d’abord les UID 0 multiples, les shells interactifs inutiles et les champs de mot de passe vides."},{"type":"callout","content":"Erreurs fréquentes : croire qu’un nom de compte suffit à juger son niveau de privilège ; oublier que « usermod -aG » a besoin du « -a » pour ajouter un groupe sans effacer les autres ; supprimer un compte sans vérifier s’il possède des fichiers ; considérer qu’un compte verrouillé avec « ! » est identique à un champ vide, alors que le premier est défensif et le second dangereux."},{"type":"callout","content":"Sécurité : ne modifie des comptes que sur ta propre machine, une machine virtuelle ou un serveur pour lequel tu as une autorisation écrite. Un changement de groupe, de shell ou d’expiration peut bloquer un service ou un collègue si tu agis sans préparation."},{"type":"callout","content":"À retenir : les fichiers « passwd », « shadow » et « group » racontent qui est qui et comment un compte peut se connecter. L’UID 0 prime sur le nom, un shell interactif doit être justifié, et un champ de mot de passe vide exige une correction immédiate."},{"type":"callout","content":"Pour pratiquer : dans « TP 2 : auditer les droits, les comptes et sudo », lis des extraits de « passwd », « shadow » et « group », puis classe les comptes en humains, services ou anomalies à corriger. Termine par le quiz de la leçon."},{"type":"resource","content":"Ubuntu-fr : la gestion des utilisateurs","url":"https://doc.ubuntu-fr.org/gestion_des_utilisateurs"},{"type":"resource","content":"Debian : le manuel de l’administrateur Debian (en anglais)","url":"https://www.debian.org/doc/manuals/debian-handbook/"},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives à un système GNU/Linux","url":"https://cyber.gouv.fr/publications/recommandations-de-securite-relatives-un-systeme-gnulinux"}]}'::jsonb, 24, 30, 2),
  ('e6f045fb-94c2-2f29-10b9-10195a9a19b6', '776b1633-dd76-67f4-532f-87063a481f11', 'afc5997d-3502-efa2-3239-290921bbaa77', 'sudo, su et root : élever ses droits proprement', 'Utilise « sudo » sans transformer chaque maintenance en session root permanente, puis lis une règle « sudoers » avec l’œil d’un auditeur.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer pourquoi root doit rester exceptionnel, distinguer « sudo », « sudo -i » et « su - », lire une règle « sudoers », vérifier ses droits avec « sudo -l », puis repérer une délégation dangereuse."},{"type":"callout","content":"Prérequis : savoir lire des comptes Linux et comprendre le principe du moindre privilège."},{"type":"callout","content":"Mise en situation : Moussa administre deux petites machines pour l’association Teranga. Un collègue lui demande un accès complet à root “pour gagner du temps”, tandis qu’un autre script redémarre un service web plusieurs fois par jour. Moussa veut déléguer juste ce qu’il faut, sans laisser un raccourci qui ouvrirait toute la machine."},{"type":"callout","content":"Vidéo à venir : Élever ses droits sans vivre en root"},{"type":"text","content":"Le compte root peut presque tout faire. C’est précisément pour cela qu’il doit être utilisé le moins possible. Une erreur de frappe, un mauvais chemin ou un script lancé trop vite ont alors un impact maximal. « sudo » élève les droits pour une commande précise, puis rend la main. « sudo -i » ouvre un shell proche d’une session root. « su - » bascule vers un autre compte, souvent root, avec son environnement complet. En pratique, un défenseur préfère garder une trace claire et un périmètre réduit avec « sudo » plutôt qu’une habitude de travail permanente en root."},{"type":"schema","content":"Commande        Effet principal\nsudo cmd       élève une seule commande\nsudo -l        liste ce que tu peux faire\nsudo -i        ouvre un shell root de maintenance\nsu -           ouvre une session d’un autre compte\nvisudo         édite sudoers avec vérification de syntaxe"},{"type":"text","content":"Sur Debian et Ubuntu, l’accès « sudo » passe souvent par le groupe « sudo ». Sur RHEL et Fedora, on parle plutôt de « wheel ». Les règles vivent dans « /etc/sudoers » et dans « /etc/sudoers.d/ ». On ne modifie pas ces fichiers avec un éditeur ordinaire : « visudo » teste la syntaxe avant d’enregistrer, ce qui évite de se bloquer hors de la machine. Une règle décrit qui peut agir, sur quelle machine, comme quel utilisateur cible, et sur quelles commandes."},{"type":"schema","content":"Exemples de règles\nawa ALL=(ALL:ALL) ALL\n%admins ALL=(root) /usr/bin/systemctl restart nginx\n%sauvegarde ALL=(root) NOPASSWD: /usr/local/bin/backup.sh\n\nLecture rapide\nqui          où    = (comme qui) commande autorisée"},{"type":"text","content":"Le danger commence quand une règle semble pratique, mais ouvre beaucoup plus que prévu. « NOPASSWD: ALL » supprime toute friction pour toutes les commandes. Autoriser un éditeur interactif, un pager ou une commande comme « find » peut aussi être risqué si elle sait lancer d’autres commandes. Tu n’as pas besoin de connaître des astuces offensives pour comprendre le principe : si la commande autorisée peut ouvrir un shell ou écrire n’importe où, elle élargit fortement le pouvoir réel de l’utilisateur. La parade consiste à autoriser des commandes précises, avec des chemins complets, et à préférer « sudoedit » pour l’édition contrôlée."},{"type":"text","content":"Démonstration guidée : sur ta machine de test, commence par voir tes droits avec « sudo -l ». Lis ensuite une petite règle dédiée à un service, puis regarde les traces de journal. Selon la distribution, tu trouveras ces traces dans le journal systemd, dans « /var/log/auth.log » ou dans « /var/log/secure ». Tu peux reproduire cette lecture sur une machine virtuelle ou un vrai serveur dont tu es responsable."},{"type":"code","content":"# Voir les droits sudo disponibles\nsudo -l\n# exemple de sortie (valeurs fictives)\n# User awa may run the following commands on web01:\n#     (root) /usr/bin/systemctl restart nginx\n#     (root) /usr/bin/systemctl status nginx\n\n# Éditer une règle dédiée sans casser la syntaxe\nsudo visudo -f /etc/sudoers.d/nginx-maintenance\n\n# Lire les traces récentes\nsudo journalctl -b _COMM=sudo --since \"1 hour ago\"\n# ou selon la distribution\nsudo tail -n 20 /var/log/auth.log","language":"bash"},{"type":"example","content":"Exemple corrigé : « awa ALL=(ALL:ALL) ALL » donne un pouvoir très large, mais reste plus traçable qu’un mot de passe root partagé. « %admins ALL=(root) /usr/bin/systemctl restart nginx » est ciblé et raisonnable si le groupe est bien géré. « %staff ALL=(root) NOPASSWD: ALL » est dangereux : toute personne du groupe devient root sans contrôle. « awa ALL=(root) /usr/bin/vim /etc/nginx/nginx.conf » paraît précis, mais l’éditeur interactif mérite une relecture sérieuse, car il sait faire bien plus qu’ouvrir un fichier."},{"type":"callout","content":"Erreurs fréquentes : modifier « sudoers » sans « visudo » ; autoriser « ALL » parce qu’un dépannage presse ; oublier les chemins complets des commandes ; confondre « sudo -i » utile pour une maintenance courte et habitude de travailler toute la journée en root."},{"type":"callout","content":"Sécurité : n’accorde des droits sudo que sur ta propre machine, une machine de test ou un serveur pour lequel tu as une autorisation écrite. Une règle trop large peut offrir un accès complet à une personne qui n’en avait pas besoin."},{"type":"callout","content":"À retenir : « sudo » sert à élever des droits de façon ciblée et journalisée. Une bonne règle délègue une action précise, avec un chemin clair et un groupe maîtrisé. Le vrai risque vient des règles larges ou des commandes capables d’en lancer beaucoup d’autres."},{"type":"callout","content":"Pour pratiquer : dans « TP 2 : auditer les droits, les comptes et sudo », classe des règles « sudoers » selon leur risque, vérifie si elles respectent le moindre privilège et justifie une correction réaliste. Termine par le quiz de la leçon."},{"type":"resource","content":"Ubuntu-fr : sudo","url":"https://doc.ubuntu-fr.org/sudo"},{"type":"resource","content":"Debian : sudoers(5), le fichier de règles sudo (en anglais)","url":"https://manpages.debian.org/stable/sudo/sudoers.5.en.html"},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives à un système GNU/Linux","url":"https://cyber.gouv.fr/publications/recommandations-de-securite-relatives-un-systeme-gnulinux"}]}'::jsonb, 22, 30, 3),
  ('2a3f7f17-a151-2135-cf31-99a084c5f58b', '776b1633-dd76-67f4-532f-87063a481f11', 'afc5997d-3502-efa2-3239-290921bbaa77', 'SUID, SGID, sticky bit, umask et ACL', 'Va au-delà des trois triplets « rwx » : comprends les bits spéciaux, calcule l’effet d’une « umask » et reconnais une délégation fine avec ACL.', '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître SUID, SGID et sticky bit, expliquer quand ils sont utiles ou dangereux, calculer l’effet d’une « umask », lire un « + » d’ACL dans « ls -l », puis vérifier un cas simple avec « getfacl »."},{"type":"callout","content":"Prérequis : avoir suivi la leçon sur les permissions Linux classiques et savoir traduire un mode octal simple."},{"type":"callout","content":"Mise en situation : Koffi audite un serveur de fichiers partagé. Il voit « /tmp » en « drwxrwxrwt », un dossier de travail en « 2775 » et un binaire SUID oublié dans « /usr/local/bin ». Pour décider ce qui est normal et ce qui doit être corrigé, il doit connaître les bits spéciaux, pas seulement les triplets « rwx »."},{"type":"callout","content":"Vidéo à venir : Les bits spéciaux Linux sans jargon inutile"},{"type":"text","content":"Les bits spéciaux complètent les droits classiques. Le SUID, valeur octale 4000, fait exécuter un programme avec les droits de son propriétaire. Le SGID, 2000, donne les droits du groupe propriétaire au programme et, sur un dossier, force les nouveaux fichiers à hériter du groupe. Le sticky bit, 1000, change surtout le comportement des dossiers partagés : dans un dossier comme « /tmp », tout le monde peut créer, mais seuls le propriétaire du fichier, le propriétaire du dossier ou root peuvent supprimer ou renommer."},{"type":"schema","content":"Bits spéciaux et affichage\n4755  -> -rwsr-xr-x  SUID actif\n2755  -> -rwxr-sr-x  SGID actif\n1777  -> drwxrwxrwt  sticky bit sur dossier partagé\nSi « x » manque : S ou T au lieu de s ou t"},{"type":"text","content":"Tous ces bits ne sont pas suspects. « /usr/bin/passwd » est légitimement SUID root, car un utilisateur ordinaire doit modifier sa propre empreinte stockée dans « /etc/shadow ». En revanche, un programme maison SUID placé dans « /usr/local/bin » mérite une revue sévère : il fait confiance à quiconque l’exécute avec les droits de son propriétaire. En audit, compare toujours la présence d’un SUID ou d’un SGID au besoin métier réel."},{"type":"text","content":"La « umask » agit au moment de la création. Elle retire des droits par défaut, elle n’en ajoute jamais. Avec « 022 », un fichier ordinaire naît en 644 et un dossier en 755. Avec « 027 », tu obtiens 640 et 750. Avec « 077 », tu fermes à 600 et 700. Les ACL, elles, servent à déléguer finement un droit à un utilisateur ou à un groupe précis sans changer complètement le propriétaire ou le groupe principal, par exemple avec « setfacl -m u:awa:r rapport.txt ». Leur présence se voit souvent par un « + » en fin de colonne « ls -l ». Tu peux aussi rencontrer « chattr +i » pour rendre un fichier immuable, « lsattr » pour voir cet attribut, et « getcap » pour repérer des capacités Linux accordées à un binaire sans passer par le SUID."},{"type":"schema","content":"Umask à retenir\n022  -> fichiers 644, dossiers 755\n027  -> fichiers 640, dossiers 750\n077  -> fichiers 600, dossiers 700\n\nACL : un « + » dans « ls -l » indique des entrées supplémentaires"},{"type":"text","content":"Démonstration guidée : observe d’abord les droits spéciaux, puis lis leur effet attendu. Sur une machine de test, tu peux créer un dossier collaboratif avec SGID, vérifier un dossier temporaire protégé par sticky bit, puis afficher l’ACL d’un fichier. Les commandes de découverte sont sûres. En revanche, n’ajoute pas un SUID sur un binaire au hasard : ce type de test reste à réserver à un laboratoire contrôlé."},{"type":"code","content":"# Repérer les bits spéciaux sur des dossiers connus\nls -ld /tmp /usr/bin/passwd\n# exemple de sortie (valeurs fictives)\n# drwxrwxrwt 18 root root   4096 Jun  7 09:20 /tmp\n# -rwsr-xr-x 1 root root  68248 Jun  7 09:20 /usr/bin/passwd\n\n# Rechercher les binaires SUID sur ton propre système\nfind / -xdev -perm -4000 -type f 2>/dev/null | head\n\n# Voir l’effet d’une ACL\ngetfacl rapport.txt\n# exemple de sortie (valeurs fictives)\n# user::rw-\n# user:awa:r--\n# group::r--\n# mask::r--\n# other::---","language":"bash"},{"type":"example","content":"Exemple corrigé : dans une liste de six binaires SUID, « /usr/bin/passwd » et « /usr/bin/su » peuvent être attendus selon la distribution, alors qu’un « /usr/local/bin/convert-paie » SUID root serait un signal fort d’audit. Pour la « umask », retiens les résultats vérifiés suivants : 022 donne 644 et 755, 027 donne 640 et 750, 077 donne 600 et 700. Si « ls -l » affiche « -rw-r-----+ », le « + » t’indique qu’une ACL complète l’histoire."},{"type":"callout","content":"Erreurs fréquentes : croire qu’un bit spécial est toujours malveillant ; confondre SGID sur un programme et SGID sur un dossier collaboratif ; penser que « umask 027 » ajoute des droits, alors qu’elle en retire ; oublier que l’ACL peut autoriser un accès même si le groupe principal ne l’explique pas à lui seul."},{"type":"callout","content":"Sécurité : n’expérimente les changements de bits spéciaux que sur ta machine, une machine virtuelle ou un conteneur de test. Un SUID mal choisi ou une ACL trop large peuvent créer une élévation de privilèges très difficile à voir au premier coup d’œil."},{"type":"callout","content":"À retenir : les bits spéciaux changent le contexte d’exécution ou de partage. « /tmp » en 1777 est normal, un binaire SUID maison ne l’est presque jamais. La « umask » ferme les droits par défaut, et l’ACL ajoute une délégation plus fine quand les trois triplets ne suffisent plus."},{"type":"callout","content":"Pour pratiquer : dans « TP 2 : auditer les droits, les comptes et sudo », vérifie les bits spéciaux attendus, calcule l’effet d’une « umask » et relis l’épreuve « Audit Linux : droits, sudo et cron » pour t’entraîner à juger un cas ambigu. Termine par le quiz de la leçon."},{"type":"resource","content":"Ubuntu-fr : les permissions","url":"https://doc.ubuntu-fr.org/permissions"},{"type":"resource","content":"GNU : le manuel des coreutils (en anglais)","url":"https://www.gnu.org/software/coreutils/manual/coreutils.html"},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives à un système GNU/Linux","url":"https://cyber.gouv.fr/publications/recommandations-de-securite-relatives-un-systeme-gnulinux"}]}'::jsonb, 24, 30, 4),
  ('28cbb157-284f-9dce-6c58-c745ebd003df', '776b1633-dd76-67f4-532f-87063a481f11', 'b627b2dc-a183-e111-0a15-c8b9bcb32c3c', 'Les processus : ps, top, signaux et kill', 'Apprends à lire « ps », à repérer un processus suspect, puis à choisir le bon signal sans détruire des indices utiles pendant une investigation.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer programme et processus, lire les colonnes de « ps aux » et « ps -ef », expliquer les états courants, choisir entre SIGTERM, SIGHUP et SIGKILL, puis reconnaître un comportement suspect."},{"type":"callout","content":"Prérequis : savoir qu’un compte Linux peut lancer un service ou un script avec des droits propres."},{"type":"callout","content":"Mise en situation : Fatou reçoit une alerte : « le serveur est lent ». En ouvrant un terminal, elle voit plusieurs processus, dont un binaire lancé depuis « /tmp » et un autre marqué « (deleted) ». Si elle tue tout trop vite, elle risque d’effacer des indices. Si elle ne lit rien correctement, elle risque de manquer la vraie cause."},{"type":"callout","content":"Vidéo à venir : Lire « ps » avant de lancer « kill »"},{"type":"text","content":"Un programme est un fichier sur disque. Un processus est ce programme en cours d’exécution, avec un PID, un parent, une mémoire et un contexte d’utilisateur. Le PID 1 correspond à « systemd » sur beaucoup de distributions modernes. Quand tu dépannes ou enquêtes, tu regardes surtout quatre choses : qui possède le processus, qui l’a lancé, ce qu’il exécute réellement, et dans quel état il se trouve."},{"type":"schema","content":"États fréquents\nR  -> en cours d’exécution\nS  -> en sommeil, attend un événement\nD  -> sommeil non interrompable, souvent lié à une E/S\nT  -> stoppé\nZ  -> zombie, terminé mais pas encore récupéré par son parent"},{"type":"text","content":"« ps aux » et « ps -ef » affichent les mêmes processus avec des colonnes différentes. Dans « ps aux », tu rencontres USER, PID, %CPU, %MEM, VSZ, RSS, TTY, STAT, START, TIME et COMMAND. Dans « ps -ef », les colonnes clés sont UID, PID, PPID, STIME, TTY, TIME et CMD. « top » ajoute une vue dynamique. Un défenseur n’a pas besoin de tout mémoriser d’un coup : il doit surtout savoir où trouver le PID, l’utilisateur, le parent et la commande complète."},{"type":"schema","content":"Lecture rapide de « ps aux »\nUSER       PID %CPU %MEM    VSZ   RSS TTY      STAT START   TIME COMMAND\nroot       861  0.0  0.8 121000 16480 ?        Ss   08:10   0:01 /usr/sbin/sshd -D\nwww-data  2140  3.8  4.1 286000 84200 ?        S    09:02   0:22 php-fpm: pool www\nawa       7312 98.0  0.2  23440  4212 pts/0    R    09:14   1:48 /tmp/.cache-update"},{"type":"text","content":"Les signaux servent à demander une action au processus. « kill PID » envoie SIGTERM par défaut : on demande un arrêt propre. « kill -HUP » sert souvent à recharger une configuration. « kill -9 » force avec SIGKILL : le processus ne peut ni l’ignorer ni nettoyer ses fichiers temporaires. En investigation, SIGKILL est donc un dernier recours. Avant d’arrêter un processus suspect, note son PID, son chemin, son parent, son utilisateur, son port éventuel et les liens « /proc/PID/exe » et « /proc/PID/cwd ». Lis aussi « /proc/PID/cmdline » pour voir la commande complète. Un binaire lancé depuis « /tmp », un nom qui imite un service système, une consommation CPU inexplicable ou un exécutable marqué « (deleted) » sont des indices importants."},{"type":"text","content":"Pour le tri rapide, « top » reste utile : la touche « P » trie par CPU, « M » par mémoire, « k » prépare l’envoi d’un signal et « q » quitte. Tu peux aussi lancer une commande en tâche de fond avec « & », revoir les tâches du shell avec « jobs » ou la détacher avec « nohup » si tu assumes de perdre le terminal. Enfin, « nice » règle la priorité de -20, très prioritaire, à 19, peu prioritaire. Ce n’est pas un outil de sécurité, mais c’est utile pour éviter qu’une tâche lourde gêne le reste."},{"type":"text","content":"Démonstration guidée : commence par lister, puis seulement après agir. Sur un Linux de test, « ps aux --sort=-%cpu | head » donne les processus les plus gourmands. « pgrep » retrouve un nom précis. « readlink » sur « /proc/PID/exe » ou « /proc/PID/cwd » montre le binaire et le dossier courant. Ce sont des commandes de lecture sûres et utiles sur un vrai serveur autorisé."},{"type":"code","content":"# Lister les processus les plus actifs\nps aux --sort=-%cpu | head\n# exemple de sortie (valeurs fictives)\n# USER       PID %CPU %MEM    VSZ   RSS TTY   STAT START   TIME COMMAND\n# awa       7312 98.0  0.2  23440  4212 pts/0 R    09:14   1:48 /tmp/.cache-update\n# root       861  0.0  0.8 121000 16480 ?     Ss   08:10   0:01 /usr/sbin/sshd -D\n\n# Retrouver un processus et ses chemins\npgrep -a sshd\ntr ''\\0'' '' '' < /proc/861/cmdline\nreadlink /proc/861/exe\nreadlink /proc/861/cwd\n# exemple de sortie (valeurs fictives)\n# /usr/sbin/sshd -D \n# /usr/sbin/sshd\n# /\n\n# Arrêt propre puis dernier recours seulement si nécessaire\nkill 7312\nkill -9 7312","language":"bash"},{"type":"example","content":"Exemple corrigé : parmi six lignes « ps aux », la plus suspecte est souvent celle qui cumule plusieurs signaux : utilisateur inattendu, chemin dans « /tmp » ou dans un dossier caché, CPU très élevé, parent étrange ou exécutable « (deleted) ». Une ligne « root 8451 95.0 0.3 23440 4212 pts/1 R 09:15 3:22 /tmp/.cache-update » mérite bien plus d’attention qu’un « sshd -D » lancé par root depuis « /usr/sbin »."},{"type":"callout","content":"Erreurs fréquentes : tuer un processus avant d’avoir noté son PID, son chemin et son parent ; utiliser « kill -9 » comme réflexe normal ; confondre un zombie avec un processus encore actif ; croire qu’un fort CPU suffit à prouver une compromission sans regarder le contexte."},{"type":"callout","content":"Sécurité : sur un serveur de production, documente d’abord puis isole si nécessaire. N’arrête un processus que sur ta propre machine ou sur un système dont tu as la responsabilité et l’autorisation écrite, surtout si une investigation est en cours."},{"type":"callout","content":"À retenir : un processus raconte qui exécute quoi, depuis où et dans quel état. « ps » sert d’abord à observer. SIGTERM est la voie normale, SIGKILL le dernier recours, et un binaire lancé depuis un emplacement inhabituel mérite une vérification immédiate."},{"type":"callout","content":"Pour pratiquer : dans « TP 3 : processus, services et tâches planifiées », lis un extrait de « ps aux », relie un port à un processus et justifie lequel paraît anormal avant toute action. Termine par le quiz de la leçon."},{"type":"resource","content":"The Linux Command Line : le livre gratuit de William Shotts (en anglais)","url":"https://linuxcommand.org/tlcl.php"},{"type":"resource","content":"Debian : le manuel de référence Debian (en anglais)","url":"https://www.debian.org/doc/manuals/debian-reference/"},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives à un système GNU/Linux","url":"https://cyber.gouv.fr/publications/recommandations-de-securite-relatives-un-systeme-gnulinux"}]}'::jsonb, 22, 30, 1),
  ('480204c5-5397-9f10-dfb1-b0a31bd466a7', '776b1633-dd76-67f4-532f-87063a481f11', 'b627b2dc-a183-e111-0a15-c8b9bcb32c3c', 'Services et systemd : systemctl, unités et démarrage', 'Pilote un service avec « systemctl », lis un statut utile, puis comprends comment une unité systemd peut aider à administrer proprement ou servir de persistance.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer le rôle de systemd, distinguer « start » et « enable », lire « systemctl status », repérer les fichiers d’unité prioritaires, puis modifier une unité proprement avec « daemon-reload »."},{"type":"callout","content":"Prérequis : avoir déjà lu des processus Linux et savoir qu’un service tourne sous un compte et un binaire précis."},{"type":"callout","content":"Mise en situation : Ama récupère un petit serveur web qui “redémarre parfois tout seul”. Le service fonctionne, mais personne ne sait s’il démarre au boot, quelle commande le lance, ni si une unité ajoutée récemment explique le comportement observé. Pour reprendre la main, Ama doit lire systemd au lieu de redémarrer à l’aveugle."},{"type":"callout","content":"Vidéo à venir : Comprendre systemd sans mémoriser mille commandes"},{"type":"text","content":"Sur Debian et Ubuntu actuels, systemd est le gestionnaire d’initialisation et de services. Il devient le PID 1 au démarrage, lance les unités nécessaires et garde l’état des services. Une unité peut représenter un service, un minuteur, un socket ou une cible logique. Pour l’administrateur, cela centralise le démarrage, l’arrêt, l’activation au boot et les journaux récents."},{"type":"schema","content":"Unités fréquentes\n.service  -> un service ou démon\n.timer    -> un déclencheur planifié\n.socket   -> une écoute activant un service\n.target   -> un ensemble logique d’unités"},{"type":"text","content":"Deux verbes sont souvent confondus. « systemctl start nom.service » agit maintenant. « systemctl enable nom.service » prépare le démarrage automatique plus tard. L’un n’implique pas l’autre. Pour savoir où tu en es, combine « status », « is-active » et « is-enabled ». « list-units » montre les unités chargées, alors que « list-unit-files » parcourt l’inventaire. Cette distinction t’évite de croire qu’un service “ne marche pas” alors qu’il tourne bien mais n’est pas activé au redémarrage, ou l’inverse."},{"type":"schema","content":"Commandes utiles\nsystemctl status ssh\nsystemctl start demo.service\nsystemctl stop demo.service\nsystemctl restart demo.service\nsystemctl reload nginx\nsystemctl enable demo.service\nsystemctl disable demo.service\nsystemctl mask demo.service\nsystemctl is-active demo.service\nsystemctl is-enabled demo.service"},{"type":"text","content":"Un fichier d’unité vit souvent dans « /usr/lib/systemd/system » ou « /lib/systemd/system » quand il vient d’un paquet, et dans « /etc/systemd/system » quand l’administrateur le crée ou le surcharge. Ce second emplacement est prioritaire. Après modification, « systemctl daemon-reload » demande à systemd de relire ses unités. En sécurité, retiens quatre idées : un service doit idéalement tourner sous un utilisateur dédié, des options comme « PrivateTmp=yes » ou « ProtectSystem=full » réduisent son exposition, toute unité inattendue déposée dans « /etc/systemd/system » peut être une persistance ajoutée par un attaquant ou par un script mal maîtrisé, et un audit gagne à lister les fichiers récents de ce répertoire avant de redémarrer quoi que ce soit."},{"type":"text","content":"Démonstration guidée : lis d’abord le statut, puis la définition complète. « systemctl cat » montre les fichiers réellement pris en compte. « journalctl -u nom -b » te donne le journal de la session de démarrage courante. Sur une machine virtuelle ou un serveur que tu administres, cela permet de comprendre un démarrage raté sans modifier le service à l’aveugle."},{"type":"code","content":"# Lire l’état et la définition d’un service\nsystemctl status ssh\n# exemple de sortie (valeurs fictives)\n# ● ssh.service - OpenBSD Secure Shell server\n#      Loaded: loaded (/lib/systemd/system/ssh.service; enabled; preset: enabled)\n#      Active: active (running) since Mon 2026-06-08 09:02:11 UTC; 14min ago\n#    Main PID: 861 (sshd)\n#       Tasks: 1\n#      Memory: 8.4M\n#         CPU: 152ms\n\nsystemctl cat ssh\njournalctl -u ssh -b --since \"30 minutes ago\"\n\n# Après modification d’une unité\nsudo systemctl daemon-reload\nsudo systemctl restart demo-backup.service","language":"bash"},{"type":"schema","content":"[Unit]\nDescription=Sauvegarde locale de démonstration\nAfter=network-online.target\n\n[Service]\nType=oneshot\nUser=backup\nExecStart=/usr/local/bin/backup-demo.sh\nRestart=no\n\n[Install]\nWantedBy=multi-user.target"},{"type":"example","content":"Exemple corrigé : si tu écris une unité « demo-backup.service » pour lancer une sauvegarde ponctuelle, place-la dans « /etc/systemd/system », relis-la avec « systemctl cat », puis exécute « daemon-reload ». Si « is-enabled » répond « disabled » mais « is-active » répond « active », le service tourne maintenant sans être prévu au prochain démarrage. C’est un état utile à comprendre lors d’un audit."},{"type":"callout","content":"Erreurs fréquentes : modifier directement le fichier fourni par le paquet au lieu d’utiliser « /etc/systemd/system » ; oublier « daemon-reload » après un changement ; croire que « enable » démarre immédiatement le service ; redémarrer sans lire le journal ni le statut complet."},{"type":"callout","content":"Sécurité : teste tes unités sur ta propre machine, une machine virtuelle ou un serveur autorisé. Une erreur dans « ExecStart » ou un « restart » répété peut empêcher un service critique de démarrer correctement."},{"type":"callout","content":"À retenir : systemd centralise le cycle de vie des services. « start » agit maintenant, « enable » prépare le futur. Les fichiers d’unité de l’administrateur dans « /etc/systemd/system » sont prioritaires et doivent être surveillés comme un point de persistance possible."},{"type":"callout","content":"Pour pratiquer : dans « TP 3 : processus, services et tâches planifiées », lis une liste de services, retrouve celui qui est activé au démarrage, puis juge si une unité ajoutée récemment paraît légitime ou suspecte. Termine par le quiz de la leçon."},{"type":"resource","content":"Debian : manuel de systemctl (en anglais)","url":"https://manpages.debian.org/stable/systemd/systemctl.1.en.html"},{"type":"resource","content":"Debian : systemd.service(5), les unités de service (en anglais)","url":"https://manpages.debian.org/stable/systemd/systemd.service.5.en.html"},{"type":"resource","content":"Debian : manuel de journalctl (en anglais)","url":"https://manpages.debian.org/stable/systemd/journalctl.1.en.html"}]}'::jsonb, 24, 30, 2),
  ('9608de54-e3ce-2388-335f-d8b1cc8058c3', '776b1633-dd76-67f4-532f-87063a481f11', 'b627b2dc-a183-e111-0a15-c8b9bcb32c3c', 'Tâches planifiées : cron et minuteurs systemd', 'Lis une règle cron sans te tromper, vérifie ses prochaines exécutions et comprends quand un minuteur systemd est plus propre qu’une vieille tâche planifiée.', '{"blocks":[{"type":"callout","content":"Objectifs : lire les cinq champs d’une règle cron, calculer la prochaine exécution, distinguer crontab utilisateur et table système, expliquer le piège du jour du mois et du jour de la semaine, puis comparer cron et minuteurs systemd."},{"type":"callout","content":"Prérequis : savoir lire des services Linux et comprendre qu’un script lancé automatiquement devient un point de maintenance ou de persistance."},{"type":"callout","content":"Mise en situation : Yacine enquête sur un serveur qui réapplique chaque nuit une mauvaise configuration. Aucun utilisateur ne s’en souvient, mais un vieux script root tourne peut-être encore. Pour retrouver la source, Yacine doit lire les tâches planifiées, calculer quand elles se déclenchent et vérifier si le script associé est sûr."},{"type":"callout","content":"Vidéo à venir : Comprendre cron sans rater l’horaire"},{"type":"text","content":"Une règle cron classique comporte cinq champs : minute, heure, jour du mois, mois et jour de la semaine. Les valeurs « */5 », « 1,15 » et « 1-5 » signifient respectivement toutes les cinq unités, une liste précise, ou un intervalle. Le piège connu est le suivant : si le jour du mois ET le jour de la semaine sont tous deux restreints, cron exécute la tâche quand l’un OU l’autre correspond. Beaucoup de personnes lisent cela comme un ET logique, puis s’étonnent d’un lancement inattendu."},{"type":"schema","content":"Champs cron\nm h dom mon dow  commande\n| |  |   |   |\n| |  |   |   +-- jour semaine, 0 ou 7 = dimanche\n| |  |   +------ mois\n| |  +---------- jour du mois\n| +------------- heure\n+--------------- minute"},{"type":"text","content":"Les tables d’utilisateur se gèrent avec « crontab -e » et « crontab -l ». Les fichiers système comme « /etc/crontab » et ceux de « /etc/cron.d/ » ajoutent un champ utilisateur avant la commande. Les dossiers « /etc/cron.daily », « .hourly », « .weekly » et « .monthly » offrent un autre style de planification. Dans tous les cas, l’environnement reste minimal : peu de variables, pas de terminal interactif et souvent un « PATH » réduit. Voilà pourquoi les scripts cron doivent employer des chemins absolus, définir leurs variables utiles et rediriger leurs sorties vers un journal."},{"type":"schema","content":"Exemples utiles\n*/5 * * * *          toutes les 5 minutes\n30 2 * * 1-5         à 02 h 30, du lundi au vendredi\n0 3 1 * *            le 1er jour du mois à 03 h 00\n15 6 * * 0           chaque dimanche à 06 h 15"},{"type":"text","content":"Les minuteurs systemd répondent au même besoin avec quelques avantages pratiques : journal intégré, dépendances explicites, expressions de calendrier avec « OnCalendar= », et option « Persistent=true » pour rejouer une tâche manquée après un arrêt. Tu les verras via « systemctl list-timers ». Pour une action ponctuelle, pense aussi à « at », qui exécute une commande une seule fois plus tard. En défense, retiens surtout que cron et les minuteurs peuvent servir à la maintenance comme à la persistance. Une tâche root qui exécute un script modifiable par un autre utilisateur devient par exemple une élévation de privilèges presque annoncée."},{"type":"text","content":"Démonstration guidée : pars d’horaires simples. Si nous sommes un lundi à 14 h 17, « */5 * * * * » déclenchera à 14 h 20, 14 h 25 puis 14 h 30. Si nous sommes un jeudi à 16 h 40, « 30 2 * * 1-5 » déclenchera vendredi à 02 h 30. Pour l’audit, pense aussi à lister toutes les tables. En root sur un serveur autorisé, la boucle qui parcourt les utilisateurs donne une vue d’ensemble très utile."},{"type":"code","content":"# Voir les tâches de l’utilisateur courant\ncrontab -l\n# exemple de sortie (valeurs fictives)\n# 30 2 * * 1-5 /usr/local/bin/backup.sh >> /var/log/backup.log 2>&1\n\n# Extrait de /etc/crontab\n# exemple de sortie (valeurs fictives)\n# 17 *    * * *   root    cd / && run-parts --report /etc/cron.hourly\n\n# Audit global en root\nfor u in $(cut -d: -f1 /etc/passwd); do\n  crontab -u \"$u\" -l 2>/dev/null\ndone\n\n# Voir les minuteurs systemd\nsystemctl list-timers --all","language":"bash"},{"type":"example","content":"Exemple corrigé : pour une sauvegarde tous les jours ouvrés à 02 h 30, la bonne règle est « 30 2 * * 1-5 ». Si tu écris « 30 2 1 * 1 », elle se lancera le premier jour du mois et aussi chaque lundi, pas seulement quand ces deux conditions tombent ensemble. Dans un audit, si tu vois une tâche root vers « /srv/atelier/backup.sh » alors que ce script est modifiable par le groupe « atelier », tu tiens un risque prioritaire. Pense aussi au scénario de persistance décrit dans « Incident : un serveur web Linux compromis » : cron fait partie des endroits à vérifier."},{"type":"callout","content":"Erreurs fréquentes : lire les champs dans le mauvais ordre ; croire que jour du mois et jour de la semaine fonctionnent en ET ; oublier les chemins absolus dans un script cron ; laisser une tâche root appeler un script modifiable par un autre compte."},{"type":"callout","content":"Sécurité : teste tes règles sur ta machine, une machine virtuelle ou un serveur que tu administres avec autorisation écrite. Une tâche planifiée mal écrite peut écraser des fichiers, saturer un disque ou relancer indéfiniment une mauvaise commande."},{"type":"callout","content":"À retenir : cron reste simple et puissant, mais il exige une lecture rigoureuse. Les tables utilisateur et système n’ont pas exactement le même format. Les minuteurs systemd offrent souvent une meilleure observabilité, et toute tâche planifiée doit être auditée comme un mécanisme de persistance potentiel."},{"type":"callout","content":"Pour pratiquer : dans « TP 3 : processus, services et tâches planifiées », calcule les prochains horaires de plusieurs règles, repère une tâche anormale et relis aussi « Incident : un serveur web Linux compromis » pour voir comment cron peut servir de persistance. Termine par le quiz de la leçon."},{"type":"resource","content":"Ubuntu-fr : cron","url":"https://doc.ubuntu-fr.org/cron"},{"type":"resource","content":"Debian : crontab(5), le format des tables cron (en anglais)","url":"https://manpages.debian.org/stable/cron/crontab.5.en.html"},{"type":"resource","content":"Debian : systemd.timer(5), les minuteurs (en anglais)","url":"https://manpages.debian.org/stable/systemd/systemd.timer.5.en.html"}]}'::jsonb, 22, 30, 3),
  ('aacaecda-468f-60c1-4041-3fb76ec68744', '776b1633-dd76-67f4-532f-87063a481f11', '78ad27d1-b01f-0f1a-dcfa-425e9cd3350a', 'Gérer les logiciels : apt, dnf, dépôts et signatures', 'Apprends comment Linux installe un logiciel, d’où viennent les paquets, pourquoi les signatures comptent, et comment limiter le risque lié aux dépôts tiers.', '{"blocks":[{"type":"callout","content":"Objectifs : repérer le rôle d’un paquet et d’un dépôt, distinguer « apt update », « apt upgrade » et « apt full-upgrade », retrouver à quel paquet appartient un fichier, expliquer la confiance accordée à une clé de signature, et comparer les réflexes Debian ou Ubuntu avec Fedora ou RHEL."},{"type":"callout","content":"Prérequis : avoir déjà ouvert un terminal et savoir lire une commande simple."},{"type":"callout","content":"Mise en situation : Awa administre un petit serveur web chez Baobab Tech et un poste Fedora pour la graphiste. Un collègue veut installer un outil en copiant une commande trouvée sur un forum, puis ajouter un dépôt tiers « parce que c’est plus rapide ». Awa doit expliquer ce que le système va vraiment faire, et à qui on choisit de faire confiance."},{"type":"callout","content":"Vidéo à venir : Comprendre les paquets Linux sans casser son système"},{"type":"text","content":"Sous Linux, un logiciel s’installe le plus souvent sous la forme d’un paquet. Un paquet contient des fichiers, des métadonnées et parfois des dépendances, c’est-à-dire d’autres paquets nécessaires à son fonctionnement. Sur Debian et Ubuntu, « apt » pilote l’installation et « dpkg » tient l’inventaire local. Sur Fedora et RHEL, le duo courant est « dnf » et « rpm ». Le principe reste le même : on prend des paquets depuis un dépôt, on vérifie leur authenticité, puis on les installe avec leurs dépendances."},{"type":"schema","content":"Dépôt signé\n   |\n   v\nListe des paquets  <- « apt update »\n   |\n   v\nPaquet choisi      <- « apt install »\n   |\n   +--> dépendances\n   |\n   v\nBase locale        <- « dpkg -l », « rpm -qa »"},{"type":"text","content":"Le point important pour la sécurité est la chaîne de confiance. « apt » vérifie surtout la signature des métadonnées du dépôt, puis l’intégrité des paquets annoncés. « dnf » et « rpm » peuvent aussi vérifier la signature des paquets. Ajouter un dépôt tiers revient donc à lui faire confiance pour te livrer du code avec des droits d’administration. C’est pour cela qu’un simple « curl ... | sudo bash » est une mauvaise habitude : tu laisses un site distant décider quoi exécuter sur ta machine sans contrôle intermédiaire. Quand tu peux, préfère les dépôts officiels, lis la documentation du projet, et garde les clés dans un emplacement prévu, comme « /etc/apt/keyrings/ » ou « /usr/share/keyrings/ »."},{"type":"text","content":"Sur Debian ou Ubuntu, « apt update » ne met rien à jour dans tes logiciels : il télécharge seulement la liste des versions disponibles. « apt upgrade » installe les nouvelles versions sans supprimer de paquet. « apt full-upgrade » peut supprimer des paquets pour résoudre des changements de dépendances. Cette nuance compte : lancer « update » seul donne une impression de sécurité trompeuse. Tu as des informations fraîches, mais pas encore de correctif appliqué. Pense aussi aux formats comme Snap, Flatpak ou AppImage : ils peuvent être pratiques, mais ils déplacent seulement la question de confiance vers une autre source ou un autre mécanisme de mise à jour."},{"type":"text","content":"Démonstration guidée : tu peux refaire cette lecture dans une machine virtuelle Debian ou Ubuntu, et en partie dans WSL si tu as les droits d’administration sur l’instance. Observe d’abord ce qui vient d’un dépôt, puis ce que le gestionnaire sait déjà d’un paquet installé. Regarde aussi d’où provient une version précise : cela sert à vérifier qu’un serveur ne tire pas sans le vouloir ses logiciels d’une source non prévue."},{"type":"code","content":"# Mettre à jour la liste des paquets disponibles\napt update\n# exemple de sortie (valeurs fictives)\n# Atteint :1 http://deb.debian.org/debian bookworm InRelease\n# Atteint :2 http://security.debian.org/debian-security bookworm-security InRelease\n# Lecture des listes de paquets... Fait\n\n# Voir les mises à jour en attente\napt list --upgradable\n# exemple de sortie (valeurs fictives)\n# Listing... Done\n# openssl/stable-security 3.0.11-1+deb12u3 amd64 [upgradable from: 3.0.11-1+deb12u2]\n# openssh-client/stable-security 1:9.2p1-2+deb12u5 amd64 [upgradable from: 1:9.2p1-2+deb12u4]\n# vim/stable 2:9.0.1378-2 amd64 [upgradable from: 2:9.0.1378-1]\n\n# Voir d’où vient une version et laquelle est installée\napt policy openssh-client\n# exemple de sortie (valeurs fictives)\n# openssh-client:\n#   Installed: 1:9.2p1-2+deb12u4\n#   Candidate: 1:9.2p1-2+deb12u5\n#   Version table:\n#      1:9.2p1-2+deb12u5 500\n#         500 http://security.debian.org/debian-security bookworm-security/main amd64 Packages\n\n# Identifier le paquet propriétaire d’un fichier\ndpkg -S /usr/bin/ssh\n# exemple de sortie (valeurs fictives)\n# openssh-client: /usr/bin/ssh","language":"bash"},{"type":"schema","content":"Commande              Effet principal\napt search motif      cherche un paquet\napt show paquet       décrit un paquet\napt install paquet    installe le paquet demandé\napt remove paquet     retire le logiciel, garde souvent sa config\napt purge paquet      retire aussi la configuration du paquet\napt autoremove        retire des dépendances devenues inutiles\ndpkg -l               liste les paquets connus localement\ndpkg -L paquet        liste les fichiers fournis par ce paquet\ndpkg -S /chemin       retrouve le paquet depuis un fichier\ndnf search ou dnf upgrade  équivalents courants côté Fedora ou RHEL"},{"type":"example","content":"Exemple corrigé : si « apt list --upgradable » montre cinq paquets et que deux lignes portent le suffixe « /stable-security », tu ne conclus pas que les trois autres sont sans importance. Tu conclus seulement que deux correctifs viennent explicitement du canal de sécurité, et que les autres peuvent être des corrections de bogues ou des dépendances. La bonne réaction est de lire « apt changelog » ou l’avis du fournisseur, pas de trier à l’aveugle entre « critique » et « optionnel » selon le nom du paquet."},{"type":"callout","content":"Erreurs fréquentes : confondre « apt update » avec l’installation des correctifs ; ajouter un dépôt tiers sans savoir qui le maintient ; supprimer un paquet « inutile » sans regarder ses dépendances ; croire qu’un format portable comme AppImage, Snap ou Flatpak annule tout risque de chaîne d’approvisionnement."},{"type":"callout","content":"Sécurité : installe sur ta propre machine, une machine virtuelle ou un serveur de test autorisé. N’exécute jamais une commande d’installation copiée depuis un site sans lire chaque option. Évite de modifier les dépôts d’un serveur de production sans sauvegarde et sans fenêtre de changement."},{"type":"callout","content":"À retenir : un paquet est un logiciel emballé avec ses métadonnées et ses dépendances. Le gestionnaire de paquets ne protège que si tu gardes une chaîne de confiance claire. « apt update » informe, « apt upgrade » corrige, et un dépôt tiers reçoit une confiance très large."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 5 : mises à jour, disques et sauvegardes » : identifie les paquets en attente, repère ceux du canal de sécurité et vérifie d’où vient une version avant de terminer par le quiz de la leçon."},{"type":"resource","content":"Ubuntu-fr : APT","url":"https://doc.ubuntu-fr.org/apt"},{"type":"resource","content":"Debian : manuel de apt (en anglais)","url":"https://manpages.debian.org/stable/apt/apt.8.en.html"},{"type":"resource","content":"Fedora : gérer les logiciels avec DNF (en anglais)","url":"https://docs.fedoraproject.org/en-US/quick-docs/dnf/"}]}'::jsonb, 22, 30, 1),
  ('704fbdc9-9b54-081c-baa5-0f8ad6255413', '776b1633-dd76-67f4-532f-87063a481f11', '78ad27d1-b01f-0f1a-dcfa-425e9cd3350a', 'Correctifs de sécurité, mises à jour et fin de support', 'Comprends comment réduire la fenêtre d’exposition d’un serveur Linux, distinguer une information de mise à jour d’un correctif réellement appliqué, et planifier le redémarrage utile.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer ce qu’est un correctif de sécurité, mesurer une fenêtre d’exposition, repérer une version encore supportée, vérifier si un redémarrage est nécessaire, et choisir entre mise à jour manuelle, testée ou automatisée."},{"type":"callout","content":"Prérequis : avoir suivi « Gérer les logiciels : apt, dnf, dépôts et signatures »."},{"type":"callout","content":"Mise en situation : Moussa maintient un petit serveur d’intranet pour l’association Teranga. Les avis de sécurité arrivent vite, mais le service doit aussi rester disponible pendant la journée. Moussa doit décider quand corriger, quoi redémarrer, et comment expliquer qu’un correctif téléchargé mais jamais appliqué ne protège personne."},{"type":"callout","content":"Vidéo à venir : Mettre à jour un serveur Linux sans se rassurer trop tôt"},{"type":"text","content":"Une mise à jour de sécurité contient un correctif pour une vulnérabilité connue. Entre la publication du correctif et son installation effective, ton système reste dans une fenêtre d’exposition. Cette durée dépend de ton organisation : vitesse de veille, validation, sauvegarde, déploiement, puis redémarrage éventuel. Dire « le paquet existe » ne suffit pas. Il faut vérifier que la version corrigée est bien installée et que le service concerné utilise encore ce code corrigé."},{"type":"schema","content":"Publication d’un avis\n        |\n        v\nLecture de l’impact\n        |\n        v\nTest ou sauvegarde\n        |\n        v\nInstallation du correctif\n        |\n        v\nRedémarrage du service ou du noyau"},{"type":"text","content":"Sous Debian ou Ubuntu, les correctifs de sécurité arrivent souvent via un dépôt « -security ». « apt list --upgradable » donne la vue d’ensemble, puis « apt changelog paquet » aide à lire ce qui change. Sur Fedora ou RHEL, le rôle équivalent passe plutôt par « dnf upgrade » et les avis du fournisseur. Dans tous les cas, la notion clé n’est pas la marque de la distribution, mais le support réel de la version utilisée. Une version en fin de support peut continuer à démarrer, tout en cessant de recevoir les correctifs attendus. Les variantes à support long existent pour aider à planifier, mais il faut toujours vérifier la date de fin de support publiée par le projet."},{"type":"text","content":"Le redémarrage compte. Un noyau mis à jour n’est pas en service tant que la machine n’a pas redémarré. De même, une bibliothèque ou un démon peut rester en mémoire avec l’ancienne version tant que son processus n’est pas relancé. Sur Debian ou Ubuntu, le fichier « /var/run/reboot-required » sert de drapeau simple. Des outils comme « needrestart » aident à repérer les services encore lancés avec d’anciens fichiers. Certaines offres proposent des correctifs en direct du noyau, mais elles ne remplacent pas une politique claire de suivi et de redémarrage."},{"type":"text","content":"Démonstration guidée : cette lecture se refait bien dans une machine virtuelle Debian ou Ubuntu, et parfois dans WSL pour les commandes de consultation. Sur un vrai serveur, ajoute toujours une sauvegarde ou un instantané avant un changement important. Lis d’abord les mises à jour disponibles, puis vérifie si un redémarrage est demandé après installation."},{"type":"code","content":"# Voir les paquets à mettre à jour\napt list --upgradable\n# exemple de sortie (valeurs fictives)\n# Listing... Done\n# openssl/stable-security 3.0.11-1+deb12u3 amd64 [upgradable from: 3.0.11-1+deb12u2]\n# linux-image-amd64/stable-security 6.1.148-1 amd64 [upgradable from: 6.1.124-1]\n\n# Lire le détail d’un changement\napt changelog openssl\n\n# Vérifier si un redémarrage système est attendu\ntest -f /var/run/reboot-required && echo \"redemarrage requis\"\n# exemple de sortie (valeurs fictives)\n# redemarrage requis","language":"bash"},{"type":"schema","content":"Automatique et prudent : unattended-upgrades, dnf-automatic\nÀ surveiller          : journaux, fenêtre de maintenance, sauvegarde\nÀ ne pas oublier      : relancer le service ou redémarrer si requis\nÀ vérifier            : support de la version et source officielle"},{"type":"example","content":"Exemple corrigé : un avis est publié le 12 mai 2026 à 09 h 00, le correctif est installé le 15 mai 2026 à 13 h 30. La fenêtre d’exposition vaut 76,5 heures, soit 3 jours et 4 h 30. Ce calcul n’indique pas le risque métier à lui seul, mais il montre combien de temps le serveur est resté vulnérable alors qu’un correctif existait déjà."},{"type":"callout","content":"Erreurs fréquentes : lancer « apt update » sans jamais appliquer les correctifs ; oublier qu’un noyau mis à jour demande souvent un redémarrage ; tout déployer en production sans test ni sauvegarde ; rester sur une version hors support parce qu’« elle marche encore »."},{"type":"callout","content":"Sécurité : sur un serveur de production, mets à jour pendant une fenêtre autorisée, avec sauvegarde ou instantané, et garde un moyen de retour arrière. Les tests se font sur ton propre environnement, une machine virtuelle ou un serveur dont tu as la charge et l’autorisation."},{"type":"callout","content":"À retenir : un correctif n’aide qu’après installation réelle, puis relance du service ou redémarrage nécessaire. La fenêtre d’exposition se mesure entre publication et application. Le support officiel de la version utilisée reste une condition de base pour recevoir les correctifs attendus."},{"type":"callout","content":"Pour pratiquer : Dans « TP 5 : mises à jour, disques et sauvegardes », repère les mises à jour en attente, estime lesquelles relèvent de la sécurité et juge si un redémarrage ou une relance de service manque encore, puis termine par le quiz."},{"type":"resource","content":"Cybermalveillance.gouv.fr : faire les mises à jour de sécurité","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/mises-a-jour"},{"type":"resource","content":"Ubuntu : avis de sécurité (en anglais)","url":"https://ubuntu.com/security/notices"},{"type":"resource","content":"Debian : l’équipe de sécurité et les avis (en anglais)","url":"https://www.debian.org/security/"}]}'::jsonb, 22, 30, 2),
  ('d2327bf3-67b9-5d93-6f32-799db0922bf3', '776b1633-dd76-67f4-532f-87063a481f11', '49f77eed-6e73-8f18-15b6-259a2c2d2cb9', 'Voir et diagnostiquer le réseau : ip, ss, dig, curl', 'Apprends à lire une interface, une route, un port à l’écoute et une résolution DNS pour diagnostiquer un souci réseau sans sauter directement à la mauvaise conclusion.', '{"blocks":[{"type":"callout","content":"Objectifs : lire une interface avec « ip », expliquer une route par défaut, interpréter une écoute dans « ss », vérifier une résolution DNS, et suivre une méthode de diagnostic simple de l’interface jusqu’au service."},{"type":"callout","content":"Prérequis : connaître le rôle d’une adresse IP, d’un port et d’un service réseau."},{"type":"callout","content":"Mise en situation : Nadia reçoit un appel de Sahel Services : l’application interne n’est plus joignable depuis un poste, alors que le serveur semble allumé. Le collègue dit seulement « le réseau est cassé ». Nadia doit vérifier si le problème vient de l’interface, de la passerelle, du DNS ou d’un service qui n’écoute plus."},{"type":"callout","content":"Vidéo à venir : Lire le réseau Linux sans paniquer devant les ports"},{"type":"text","content":"La commande « ip » remplace plusieurs anciens outils. « ip -br a » donne une vue courte des interfaces, de leur état et de leurs adresses. « ip a » montre plus de détails, comme les adresses IPv4 ou IPv6, leur portée et l’état complet de l’interface. « ip r » affiche la table de routage, c’est-à-dire le chemin choisi pour sortir du réseau local. La ligne commençant par « default via » indique la passerelle par défaut : c’est souvent la box ou le routeur local. Si l’interface est coupée, il est inutile de suspecter tout de suite le DNS ou le serveur distant."},{"type":"schema","content":"Diagnostic par couches\n1. interface : « ip -br a »\n2. route locale : « ip r »\n3. voisin et passerelle : « ip neigh », « ping -c 3 »\n4. nom DNS : « dig +short »\n5. service : « ss -tulpn », « curl -I »"},{"type":"text","content":"« ss -tulpn » sert à lire les sockets ouvertes. Les lettres de l’option rappellent ce que tu demandes : TCP, UDP, listening, process et numeric. Le tableau affiche notamment « Netid », « State », « Recv-Q », « Send-Q », « Local Address:Port », « Peer Address:Port » et le processus. Un port à l’écoute est une surface d’attaque potentielle : il faut donc savoir à quel processus il appartient et s’il écoute partout ou seulement en local. « 0.0.0.0:22 » signifie que le service écoute sur toutes les interfaces IPv4. « [::]:22 » fait de même en IPv6. En revanche « 127.0.0.1:5432 » n’est joignable qu’en local : c’est un bon réflexe pour une base de données qui n’a pas à accepter des connexions depuis le réseau."},{"type":"text","content":"Le DNS et HTTP se vérifient séparément. « dig +short nom » répond à la question « ce nom résout-il vers une adresse ? ». « curl -I https://... » demande seulement les en-têtes HTTP, ce qui suffit souvent pour voir si le service répond. Si le chemin réseau reste flou, « tracepath » ou « traceroute » aident à voir où le trafic se perd. Les fichiers « /etc/resolv.conf » et « /etc/hosts » complètent l’enquête : le premier décrit souvent les résolveurs DNS, le second peut forcer des correspondances locales. Si tu emploies « nmap », ce doit être seulement sur tes propres machines ou avec autorisation écrite."},{"type":"text","content":"Démonstration guidée : commence par lire l’interface, puis la route, puis les ports à l’écoute. Enfin, interroge un nom DNS et un service web. L’ordre compte : si « ip -br a » montre une interface DOWN, les étapes suivantes t’apprennent moins qu’un simple branchement ou qu’une mauvaise configuration locale."},{"type":"code","content":"# Vue courte des interfaces\nip -br a\n# exemple de sortie (valeurs fictives)\n# lo               UNKNOWN        127.0.0.1/8 ::1/128\n# eth0             UP             192.168.1.20/24 fe80::5054:ff:fe12:3456/64\n\n# Route par défaut\nip r\n# exemple de sortie (valeurs fictives)\n# default via 192.168.1.1 dev eth0 proto dhcp metric 100\n# 192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.20\n\n# Ports à l’écoute\nss -tulpn\n# exemple de sortie (valeurs fictives)\n# Netid State  Recv-Q Send-Q Local Address:Port  Peer Address:Port Process\n# tcp   LISTEN 0      128    0.0.0.0:22          0.0.0.0:*         users:((\"sshd\",pid=731,fd=3))\n# tcp   LISTEN 0      244    127.0.0.1:5432      0.0.0.0:*         users:((\"postgres\",pid=812,fd=5))","language":"bash"},{"type":"schema","content":"Écoute observée        Lecture utile\n0.0.0.0:22            service exposé sur toutes les interfaces IPv4\n127.0.0.1:5432        service limité à la machine locale\n[::]:80               service exposé sur toutes les interfaces IPv6\ndefault via 192.168.1.1  sortie réseau par la passerelle 192.168.1.1"},{"type":"example","content":"Exemple corrigé : dans une sortie « ss », le port 22 sur « 0.0.0.0 » mérite une vérification de pare-feu et de politique SSH. Le port 5432 sur « 127.0.0.1 » est plus rassurant : le serveur PostgreSQL n’écoute qu’en local. Si l’application web sur la même machine doit seule lui parler, cette limitation réduit la surface d’attaque sans casser le service."},{"type":"callout","content":"Erreurs fréquentes : croire qu’un service sur « 0.0.0.0 » est forcément visible depuis Internet, alors qu’un pare-feu peut encore le bloquer ; diagnostiquer le DNS avant d’avoir vérifié l’interface ; confondre un port en écoute locale avec un service publié ; oublier que le résultat de « curl -I » décrit l’application, pas la route réseau complète."},{"type":"callout","content":"Sécurité : scanne uniquement tes propres machines ou celles pour lesquelles tu as une autorisation. Sur un poste de production, contente-toi d’abord de commandes de lecture comme « ip », « ss », « dig » et « curl » avant d’envisager un changement."},{"type":"callout","content":"À retenir : diagnostiquer le réseau Linux commence par l’interface, puis la route, puis la résolution et le service. Chaque port à l’écoute compte comme une surface d’attaque potentielle. Lire « 0.0.0.0 », « [::] » et « 127.0.0.1 » t’aide à décider quoi fermer, limiter ou publier."},{"type":"callout","content":"Pour pratiquer : Dans « TP 4 : réseau, SSH et pare-feu », lis la configuration réseau, la route par défaut et les ports à l’écoute avant de relier chaque service à son exposition réelle, puis termine par le quiz."},{"type":"resource","content":"Linux : manuel de la commande ip (en anglais)","url":"https://man7.org/linux/man-pages/man8/ip.8.html"},{"type":"resource","content":"Linux : manuel de la commande ss (en anglais)","url":"https://man7.org/linux/man-pages/man8/ss.8.html"},{"type":"resource","content":"MDN : aperçu de HTTP","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Overview"}]}'::jsonb, 24, 30, 1),
  ('cb702636-1df2-e9c3-74dc-2d7d0c8b2ded', '776b1633-dd76-67f4-532f-87063a481f11', '49f77eed-6e73-8f18-15b6-259a2c2d2cb9', 'SSH : connexion, clés et durcissement de sshd_config', 'Apprends à te connecter proprement en SSH, à utiliser des clés plutôt qu’un mot de passe, et à lire « sshd_config » sans te couper toi-même l’accès.', '{"blocks":[{"type":"callout","content":"Objectifs : créer une paire de clés SSH, vérifier une empreinte de serveur, expliquer le rôle de « authorized_keys » et « known_hosts », tester une configuration « sshd_config », et déduire la valeur effective d’un réglage avec « Include » ou « Match »."},{"type":"callout","content":"Prérequis : avoir vu « Voir et diagnostiquer le réseau : ip, ss, dig, curl » et savoir ce qu’est un port réseau."},{"type":"callout","content":"Mise en situation : Koffi doit administrer un serveur Ubuntu chez Atlas sans rester devant l’écran physique. La connexion fonctionne encore au mot de passe, mais le journal montre des tentatives d’authentification répétées. Koffi veut passer aux clés, limiter les comptes autorisés et durcir « sshd_config » sans se verrouiller dehors."},{"type":"callout","content":"Vidéo à venir : SSH sans se couper l’accès : clés, empreintes et configuration"},{"type":"text","content":"SSH fournit un accès distant chiffré et authentifié. Le client vérifie l’identité du serveur, puis l’utilisateur s’authentifie par mot de passe ou, mieux, par paire de clés. SSH sert aussi à transférer des fichiers avec « scp », « sftp » ou « rsync -e ssh », et les tunnels permettent de faire passer un autre flux dans la connexion sans exposer un service de plus. Côté client, la clé privée reste dans « ~/.ssh/ » et ne se partage jamais. La clé publique, elle, peut être copiée sur le serveur dans « authorized_keys ». Quand tout est en place, la connexion par clé réduit fortement le risque lié aux mots de passe devinés ou réutilisés."},{"type":"schema","content":"Client                        Serveur\n~/.ssh/id_ed25519            /home/awa/.ssh/authorized_keys\nclé privée : 600             fichier : 600\nclé publique : partageable   dossier .ssh : 700\nknown_hosts : mémoire des    sshd_config : règles du service\nempreintes de serveur"},{"type":"text","content":"La première connexion demande un effort de vérification : l’empreinte du serveur doit correspondre à celle annoncée par l’administrateur ou vue depuis une console sûre. Si l’empreinte change sans raison connue, tu n’acceptes pas machinalement : cela peut signaler une réinstallation, mais aussi une interception. Le fichier « known_hosts » sert justement à mémoriser les serveurs déjà vus."},{"type":"text","content":"Le durcissement de « sshd_config » commence souvent par « PermitRootLogin no », « PasswordAuthentication no » une fois les clés testées, puis « AllowUsers » ou « AllowGroups » pour limiter qui peut entrer. Le détail à retenir est subtil : pour un mot-clé donné, la première valeur rencontrée compte. Comme Debian et Ubuntu placent souvent « Include /etc/ssh/sshd_config.d/*.conf » en tête, un fichier du dossier « .d » peut l’emporter sur une ligne plus bas dans le fichier principal."},{"type":"text","content":"Les blocs « Match » ajoutent une autre couche : ils s’appliquent seulement aux connexions concernées, par exemple un utilisateur ou une adresse, puis restent actifs jusqu’au prochain bloc « Match » ou jusqu’à la fin du fichier. Le fichier « ~/.ssh/config » côté client sert, lui, à mémoriser un nom d’hôte, un port ou une clé à utiliser. Tu testes toujours avec « sshd -t » avant de recharger. « sshd -T » affiche ensuite la configuration effective globale, et l’option « -C » permet de simuler un cas précis pour relire l’effet d’un bloc « Match ». Sur Debian et Ubuntu, le service s’appelle le plus souvent « ssh » ; sur RHEL et Fedora, c’est plutôt « sshd ». Garde toujours une session déjà ouverte pendant la modification : cette habitude évite de transformer un durcissement bien intentionné en coupure de service."},{"type":"text","content":"Démonstration guidée : tu peux créer une clé dans Git Bash, WSL, Termux ou une machine virtuelle. En revanche, modifier « sshd_config » demande un vrai serveur Linux ou au moins une machine virtuelle où tu es administrateur. Crée d’abord la clé, lis ensuite une empreinte publique, puis vérifie la syntaxe d’un extrait de configuration avant d’aller plus loin."},{"type":"code","content":"# Créer une paire de clés côté client\nssh-keygen -t ed25519\n\n# Lire l’empreinte d’une clé publique\nssh-keygen -lf ~/.ssh/id_ed25519.pub\n\n# Copier la clé publique vers un serveur\nssh-copy-id awa@192.168.1.20\n\n# Tester la syntaxe de la configuration serveur\nsshd -t\n\n# Voir la configuration effective hors bloc Match\nsshd -T | grep -E ''permitrootlogin|passwordauthentication|maxauthtries''\n\n# Simuler un cas precis pour un bloc Match\nsshd -T -C user=awa,host=srv-demo,addr=192.168.1.20 | grep -E ''passwordauthentication|maxauthtries''","language":"bash"},{"type":"code","content":"# Extrait de configuration et de journal (valeurs fictives)\nInclude /etc/ssh/sshd_config.d/*.conf\nPermitRootLogin yes\nPasswordAuthentication yes\n\nMatch User awa\n    PasswordAuthentication no\n\n# exemple de journal\n# Failed password for invalid user admin from 192.168.1.60 port 51234 ssh2\n# Accepted publickey for awa from 192.168.1.20 port 44218 ssh2: ED25519 SHA256:57qiy2BUfE1i...","language":"text"},{"type":"example","content":"Exemple corrigé : si « /etc/ssh/sshd_config.d/10-hardening.conf » contient déjà « PermitRootLogin no » et que le fichier principal plus bas dit encore « PermitRootLogin yes », la valeur effective reste « no » parce que la première occurrence compte. En revanche, un bloc « Match User awa » peut ensuite changer seulement l’authentification par mot de passe pour Awa, sans modifier le cas des autres utilisateurs."},{"type":"callout","content":"Erreurs fréquentes : désactiver les mots de passe avant d’avoir testé la clé ; accepter une nouvelle empreinte de serveur sans la vérifier ; laisser des droits trop ouverts sur « ~/.ssh » ou « authorized_keys » ; croire que changer le port SSH suffit à sécuriser le service."},{"type":"callout","content":"Sécurité : travaille sur un serveur à toi ou sous autorisation écrite. Garde toujours une session déjà ouverte pendant la modification de « sshd_config ». N’active pas une restriction que tu ne peux pas tester, et ne partage jamais une clé privée."},{"type":"callout","content":"À retenir : SSH protège la connexion, mais pas une configuration imprudente. Les clés limitent le risque lié aux mots de passe, « known_hosts » protège contre les changements d’identité non expliqués, et « sshd -t » doit précéder tout rechargement de configuration."},{"type":"callout","content":"Pour pratiquer : Dans « TP 4 : réseau, SSH et pare-feu », interprète une configuration avec « Include » et « Match », puis lis le journal d’authentification avant de finir par le quiz. Tu peux aussi rapprocher ce sujet de « Incident : un serveur web Linux compromis » pour l’analyse des tentatives SSH."},{"type":"resource","content":"Ubuntu-fr : SSH","url":"https://doc.ubuntu-fr.org/ssh"},{"type":"resource","content":"Debian : sshd_config(5), la configuration du serveur SSH (en anglais)","url":"https://manpages.debian.org/stable/openssh-server/sshd_config.5.en.html"},{"type":"resource","content":"OpenSSH : le manuel (en anglais)","url":"https://www.openssh.com/manual.html"}]}'::jsonb, 26, 30, 2),
  ('8844a6b5-0493-80d0-0fc0-f7150e367af1', '776b1633-dd76-67f4-532f-87063a481f11', '49f77eed-6e73-8f18-15b6-259a2c2d2cb9', 'Pare-feu sous Linux : ufw et nftables', 'Apprends à raisonner avec une politique par défaut, à lire des règles « ufw » ou « nftables », et à éviter de couper l’accès SSH en voulant bien faire.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer le rôle d’un pare-feu local, choisir une politique par défaut, lire l’ordre des règles « ufw », interpréter une règle « nftables », et décider si un paquet donné sera accepté ou bloqué."},{"type":"callout","content":"Prérequis : avoir suivi « Voir et diagnostiquer le réseau : ip, ss, dig, curl » et « SSH : connexion, clés et durcissement de sshd_config »."},{"type":"callout","content":"Mise en situation : Fatou doit ouvrir seulement ce qui est nécessaire sur un petit serveur Ubuntu chez Cabinet Moussa. Le service web doit être public, SSH seulement depuis le réseau local, et la base de données ne doit pas être exposée du tout. Elle veut appliquer un refus par défaut sans perdre sa session distante."},{"type":"callout","content":"Vidéo à venir : Pare-feu Linux : ouvrir juste ce qu’il faut"},{"type":"text","content":"Le pare-feu Linux s’appuie sur le filtrage du noyau, souvent appelé netfilter. L’idée défensive simple est de refuser par défaut ce qui entre, d’autoriser ce qui sort, puis d’ajouter des exceptions précises. Ce n’est pas une solution magique : un pare-feu ne corrige ni un logiciel vulnérable ni une authentification faible. En revanche, il réduit la surface d’attaque visible depuis le réseau."},{"type":"schema","content":"Politique sobre\nEntrée   : deny par défaut\nSortie   : allow par défaut\nBoucle locale : allow\nConnexions établies : allow\nExceptions utiles : SSH, HTTP, HTTPS, selon le besoin réel"},{"type":"text","content":"« ufw » simplifie la gestion sur Debian et Ubuntu. Tu peux définir les politiques par défaut, autoriser un port, restreindre une source, limiter les tentatives SSH et relire les règles numérotées. L’ordre compte : la première règle qui correspond décide. C’est pour cela qu’une exception très large placée trop haut peut rendre les lignes suivantes inutiles. Avant d’activer, tu autorises SSH ou tu prépares un accès console, sinon tu peux te bloquer dehors. Les journaux apparaissent souvent dans « /var/log/ufw.log » avec des lignes marquées « [UFW BLOCK] »."},{"type":"text","content":"« nftables » expose plus directement la logique du filtrage. Tu y lis des tables, des chaînes, une politique et des règles comme « ct state established,related accept » pour laisser passer les réponses à des connexions déjà établies. Une chaîne « input » avec « policy drop » annonce une philosophie claire : tout est rejeté sauf ce qui est explicitement accepté. La commande de lecture la plus directe est « nft list ruleset »."},{"type":"text","content":"Démonstration guidée : sur une machine virtuelle Ubuntu où tu es administrateur, commence par lire l’état du pare-feu, puis imagine le chemin d’un paquet SSH venant du réseau local. Vérifie enfin quelle règle le laisse passer. Sur un vrai serveur, garde une seconde session ou une console hors bande avant toute activation."},{"type":"code","content":"# Définir une politique simple avant activation\nufw default deny incoming\nufw default allow outgoing\nufw allow from 192.168.1.0/24 to any port 22 proto tcp\nufw allow 80/tcp\nufw allow 443/tcp\nufw limit ssh\nufw enable\n\n# Lire l’état et les règles numérotées\nufw status verbose\n# exemple de sortie (valeurs fictives)\n# Status: active\n# Logging: on (low)\n# Default: deny (incoming), allow (outgoing), disabled (routed)\n# New profiles: skip\n\nufw status numbered\n# exemple de sortie (valeurs fictives)\n# [ 1] 22/tcp                     ALLOW IN    192.168.1.0/24\n# [ 2] 80/tcp                     ALLOW IN    Anywhere\n# [ 3] 443/tcp                    ALLOW IN    Anywhere\n# [ 4] 22/tcp                     LIMIT IN    Anywhere\n\n# Supprimer une règle par son numéro\nufw delete 4\n\n# Journal typique\n# [UFW BLOCK] IN=eth0 SRC=192.168.1.60 DST=192.168.1.20 PROTO=TCP SPT=52314 DPT=22","language":"bash"},{"type":"code","content":"# Lire puis interpréter les règles nftables\nnft list ruleset\n# exemple de sortie (valeurs fictives)\ntable inet filter {\n  chain input {\n    type filter hook input priority 0; policy drop;\n    ct state established,related accept\n    iif \"lo\" accept\n    tcp dport 22 ip saddr 192.168.1.0/24 accept\n    tcp dport { 80, 443 } accept\n  }\n}","language":"text"},{"type":"example","content":"Exemple corrigé : avec les règles « ufw » ci-dessus, un paquet SSH venant de 192.168.1.50 est accepté par la règle 1 avant même que la règle 4 ne soit examinée. Un paquet SSH venant de 10.1.5.9 ne correspond pas à la règle 1. Il peut alors être autorisé par la règle « limit ssh » si les tentatives restent raisonnables, puis bloqué si elles deviennent trop fréquentes. La lecture correcte demande donc de suivre l’ordre et de comprendre que « limit » ne veut pas dire « deny immédiat »."},{"type":"callout","content":"Erreurs fréquentes : activer un refus par défaut sans avoir autorisé SSH ni préparé une console ; croire qu’ouvrir le port d’un service suffit à le rendre sûr ; oublier que l’ordre des règles décide ; laisser une base de données écouter et passer au pare-feu alors qu’elle devrait rester locale."},{"type":"callout","content":"Sécurité : teste sur ta propre machine, une machine virtuelle ou un serveur que tu administres. N’active jamais un pare-feu à distance sans second accès de secours. Garde aussi en tête que les règles réseau complètent le durcissement, elles ne le remplacent pas."},{"type":"callout","content":"À retenir : un pare-feu local met en œuvre le principe du refus par défaut. « ufw » simplifie les cas courants, « nftables » montre la logique plus bas niveau, et l’ordre des règles décide du résultat. Autorise seulement ce qui sert vraiment."},{"type":"callout","content":"Pour pratiquer : Dans « TP 4 : réseau, SSH et pare-feu », lis les règles, déduis si un paquet est accepté ou bloqué, puis vérifie si la politique correspond vraiment au besoin avant de répondre au quiz."},{"type":"resource","content":"ANSSI : définir une politique de filtrage réseau d’un pare-feu","url":"https://messervices.cyber.gouv.fr/guides/recommandations-pour-la-definition-dune-politique-de-filtrage-reseau-dun-pare-feu"},{"type":"resource","content":"Ubuntu-fr : le pare-feu ufw","url":"https://doc.ubuntu-fr.org/ufw"},{"type":"resource","content":"Debian : manuel de nft (nftables) (en anglais)","url":"https://manpages.debian.org/stable/nftables/nft.8.en.html"}]}'::jsonb, 24, 30, 3),
  ('2049fc87-1815-2f3f-1d59-4d54d7632a69', '776b1633-dd76-67f4-532f-87063a481f11', '35577acc-dd9f-fb64-5e46-c4db2e0534b8', 'Disques, partitions et systèmes de fichiers', 'Apprends à lire « lsblk », « df » et « /etc/fstab », à repérer un disque presque plein ou à court d’inodes, et à monter un système de fichiers sans pari risqué.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer disque, partition et système de fichiers, lire « lsblk -f » et « df -h », expliquer les 6 champs de « /etc/fstab », calculer un pourcentage d’occupation, et repérer des options de montage utiles au durcissement."},{"type":"callout","content":"Prérequis : savoir se repérer dans l’arborescence Linux et lire un bloc de code simple."},{"type":"callout","content":"Mise en situation : Amina reçoit une alerte : le serveur de fichiers de la coopérative Harmattan écrit mal ses journaux et l’application refuse de nouveaux documents. Le disque n’est pas « cassé », mais quelque chose manque. Amina doit lire l’état des volumes, comprendre « fstab » et décider si le problème vient de l’espace, des inodes ou d’un montage mal prévu."},{"type":"callout","content":"Vidéo à venir : Disques Linux : lire avant d’écrire"},{"type":"text","content":"Sous Linux, un disque est un périphérique bloc comme « /dev/sda », « /dev/vda » ou « /dev/nvme0n1 ». Il peut contenir des partitions, puis chaque partition porte souvent un système de fichiers comme ext4, xfs ou btrfs. « lsblk -f » montre cette hiérarchie et les points de montage. « df -h » répond à une autre question : combien d’espace reste-t-il sur les systèmes de fichiers montés ? Tu évites ainsi de confondre un disque présent mais non monté avec un volume réellement utilisé par le système."},{"type":"schema","content":"Disque            -> /dev/vda\nPartition système -> /dev/vda1  -> /\nPartition données -> /dev/vda2  -> /srv/atelier\nSystème de fichiers : ext4, xfs, btrfs\nPoint de montage    : endroit de l’arborescence où le volume apparaît"},{"type":"text","content":"« /etc/fstab » décrit les montages persistants. Les six champs, dans l’ordre, sont le périphérique, le point de montage, le type, les options, puis « dump » et « pass ». On préfère souvent « UUID=... » au nom brut du périphérique pour éviter les surprises de renommage au démarrage. Après une modification, « mount -a » permet de tester le fichier sans redémarrer. Si tu te trompes dans « fstab », tu peux retarder ou bloquer le démarrage du système."},{"type":"text","content":"Les commandes de lecture se complètent. « findmnt » montre où un volume est monté. « blkid » aide à retrouver UUID et type. « du -sh * » répond à une autre question que « df » : quels dossiers consomment vraiment l’espace dans un endroit donné ? Pour un montage ponctuel, « mount » attache un système de fichiers à l’arborescence et « umount » le détache proprement. Dans des environnements plus avancés, LVM ajoute une couche logique souple au-dessus des partitions."},{"type":"text","content":"Les options de montage servent aussi au durcissement. « nodev » empêche l’usage de fichiers spéciaux de périphérique sur le point de montage. « nosuid » ignore les bits SUID et SGID. « noexec » empêche l’exécution directe de binaires. Ces options sont souvent utiles pour « /tmp », « /var/tmp » ou des supports amovibles, à condition de vérifier qu’elles ne cassent pas un usage légitime. Pense aussi à la rotation des journaux : un « logrotate » mal réglé peut te laisser croire qu’un disque grossit mystérieusement alors que ce sont juste les journaux qui débordent."},{"type":"text","content":"L’espace n’est pas le seul piège : un système de fichiers peut manquer d’inodes avant de manquer d’octets. « df -i » répond à cette question. Un volume qui héberge beaucoup de petits fichiers, journaux ou caches peut donc tomber en panne alors qu’il reste encore plusieurs gigaoctets libres. C’est un problème de disponibilité, pas seulement d’administration « propre »."},{"type":"text","content":"Démonstration guidée : lis d’abord les volumes avec « lsblk -f », puis vérifie l’occupation avec « df -h » et « df -i ». Enfin, ouvre « /etc/fstab » pour voir comment le système retrouvera ses montages au prochain démarrage. Cette lecture se pratique bien dans une machine virtuelle ou un serveur de test. En revanche, les commandes destructrices comme « mkfs » ou « dd » ne se collent jamais sur un vrai disque sans procédure claire."},{"type":"code","content":"# Lire les volumes et leurs points de montage\nlsblk -f\n# exemple de sortie (valeurs fictives)\n# NAME   FSTYPE FSVER LABEL UUID                                 FSAVAIL FSUSE% MOUNTPOINTS\n# vda\n# ├─vda1 ext4   1.0         11111111-2222-3333-4444-555555555555   7.6G    81% /\n# └─vda2 ext4   1.0         66666666-7777-8888-9999-aaaaaaaaaaaa  15.2G    24% /srv/atelier\n\n# Vérifier l’espace et les inodes\ndf -h\n# exemple de sortie (valeurs fictives)\n# Filesystem      Size  Used Avail Use% Mounted on\n# /dev/vda1        80G   62G   18G  78% /\n# /dev/vda2        20G  4.8G   15G  24% /srv/atelier\n\ndf -i\n# exemple de sortie (valeurs fictives)\n# Filesystem       Inodes   IUsed   IFree IUse% Mounted on\n# /dev/vda1      2000000 1900000 100000   95% /","language":"bash"},{"type":"code","content":"# Extrait /etc/fstab (valeurs fictives)\nUUID=11111111-2222-3333-4444-555555555555 /           ext4 defaults                         0 1\nUUID=66666666-7777-8888-9999-aaaaaaaaaaaa /srv/atelier ext4 defaults,nosuid,nodev          0 2\nUUID=bbbbbbbb-cccc-dddd-eeee-ffffffffffff /tmp        ext4 defaults,nosuid,nodev,noexec    0 2\n\n# Tester sans redémarrer\nmount -a","language":"text"},{"type":"example","content":"Exemple corrigé : la racine « / » de 80 Gio contient 62 Gio utilisés, soit 77,5 %, donc environ 78 %. Cela n’est pas encore une panne, mais ce n’est plus confortable si les journaux grossissent vite. Le vrai signal d’alerte ici est aussi « df -i » : 1 900 000 inodes utilisés sur 2 000 000, soit 95 %. Même avec 18 Gio libres, le volume peut refuser de nouveaux fichiers. Deux problèmes sautent donc aux yeux : la marge d’espace se réduit, et la marge d’inodes est déjà critique."},{"type":"callout","content":"Erreurs fréquentes : se tromper de périphérique et écrire sur le mauvais disque ; croire que l’espace libre suffit toujours alors que les inodes peuvent manquer ; modifier « /etc/fstab » sans tester « mount -a » ; monter un volume de données sans options adaptées alors qu’il n’a pas besoin d’exécuter quoi que ce soit."},{"type":"callout","content":"Sécurité : n’exécute pas « mkfs », « dd » ni une commande de formatage sur un vrai disque pour « essayer ». Les manipulations de lecture se font sur ta propre machine, une machine virtuelle ou un serveur que tu administres. Toute écriture sur un disque doit suivre une procédure validée et sauvegardée."},{"type":"callout","content":"À retenir : un disque, une partition et un système de fichiers ne sont pas la même chose. « lsblk » décrit la structure, « df » décrit l’usage, et « /etc/fstab » décrit le prochain démarrage. L’espace libre et les inodes doivent être surveillés ensemble."},{"type":"callout","content":"Pour pratiquer : Dans « TP 5 : mises à jour, disques et sauvegardes », lis « df », « lsblk » et « fstab », puis repère ce qui menace la disponibilité ou le durcissement avant de finir par le quiz."},{"type":"resource","content":"Linux : manuel de la commande lsblk (en anglais)","url":"https://man7.org/linux/man-pages/man8/lsblk.8.html"},{"type":"resource","content":"Linux : fstab(5), le fichier /etc/fstab (en anglais)","url":"https://man7.org/linux/man-pages/man5/fstab.5.html"},{"type":"resource","content":"Arch Wiki : fstab (en anglais)","url":"https://wiki.archlinux.org/title/Fstab"}]}'::jsonb, 22, 30, 1),
  ('b166be31-17a9-c97b-a832-d0fe25236fad', '776b1633-dd76-67f4-532f-87063a481f11', '35577acc-dd9f-fb64-5e46-c4db2e0534b8', 'Sauvegarder sous Linux : tar, rsync, restic', 'Apprends à distinguer archive, synchronisation et sauvegarde versionnée, à relire une politique de rétention, et à tester une restauration au lieu de faire confiance à un simple journal « OK ».', '{"blocks":[{"type":"callout","content":"Objectifs : différencier « tar », « rsync » et « restic », expliquer la règle 3-2-1 appliquée à un serveur, vérifier l’effet d’une barre finale dans « rsync », calculer une rétention, et décrire une restauration de test crédible."},{"type":"callout","content":"Prérequis : avoir suivi « Disques, partitions et systèmes de fichiers » et connaître la différence entre un dossier source et un point de destination."},{"type":"callout","content":"Mise en situation : Seydou gère les documents et scripts d’un petit serveur pour l’association Teranga. Les sauvegardes semblent tourner chaque nuit, mais personne n’a jamais restauré un fichier pour vérifier. Seydou doit comprendre ce que fait chaque outil, lire la politique de rétention et éviter qu’une erreur de synchronisation efface aussi la copie de secours."},{"type":"callout","content":"Vidéo à venir : Sauvegarder sous Linux sans confondre copie et vraie restauration"},{"type":"text","content":"Sous Linux, plusieurs outils de sauvegarde répondent à des besoins différents. « tar » crée une archive, pratique pour regrouper et transporter un ensemble de fichiers. « rsync » synchronise efficacement un contenu entre une source et une destination, localement ou via SSH. « restic » ajoute un dépôt chiffré, des instantanés et de la déduplication, donc une vraie histoire des sauvegardes. Aucun de ces outils n’est « meilleur » en soi : tu choisis selon la fréquence, la taille, la rétention et le besoin de restauration."},{"type":"text","content":"Sur un serveur, tu ne sauvegardes pas seulement les documents : pense aussi aux fichiers de configuration, à la liste des paquets installés, et aux exports de bases de données. La règle 3-2-1 reste utile : au moins trois copies, sur deux supports différents, dont une hors site. Une synchronisation locale seule n’y suffit pas. La planification se fait souvent via cron ou un minuteur systemd, mais le plus important reste de vérifier qu’une restauration complète ou partielle est réaliste."},{"type":"schema","content":"Outil      Force principale                 Limite à garder en tête\ntar        archive simple et portable      peu de versionnement natif\nrsync      copie efficace et différentielle une mauvaise option peut refléter une erreur\nrestic     instantanés chiffrés, déduplication exige une gestion sérieuse du mot de passe"},{"type":"text","content":"« rsync » a un piège célèbre : la barre finale. « rsync -a src/ dest/ » copie le contenu de « src » dans « dest ». Sans barre finale, tu copies le dossier « src » lui-même. L’option « --delete » peut être utile pour garder un miroir fidèle, mais elle devient dangereuse si la source est incomplète ou mal ciblée. On la teste donc d’abord avec « --dry-run -v ». Si ton environnement d’exercice n’a pas « rsync » ou « restic », retiens au moins la logique et entraîne-toi ensuite dans WSL, une machine virtuelle Linux ou le laboratoire du parcours."},{"type":"text","content":"« restic » travaille autrement : chaque sauvegarde devient un instantané. Tu peux lancer « restic backup », lister avec « restic snapshots », restaurer le dernier avec « restic restore latest --target ... », oublier ceux qui dépassent la politique, puis lancer « restic check ». Le mot de passe du dépôt protège les données, mais sa perte rend la sauvegarde inutilisable. Une bonne hygiène comprend aussi le droit 600 sur le fichier qui contient ce secret, si tu automatises l’accès au dépôt."},{"type":"text","content":"Démonstration guidée : sur une machine de test, crée réellement une archive « tar », liste-la, extrais-la et compare le contenu restauré. Pour « rsync » et « restic », lis les commandes types puis vérifie ensuite leur comportement sur un Linux de test. Le réflexe défensif central reste le même : vérifier la restauration, pas seulement la copie."},{"type":"code","content":"# Créer puis lister une archive\ntar -czf sauvegarde-demo.tar.gz dossier-demo\ntar -tzf sauvegarde-demo.tar.gz\n# exemple de sortie (valeurs fictives)\n# dossier-demo/\n# dossier-demo/docs/\n# dossier-demo/docs/rapport.txt\n# dossier-demo/logs/\n# dossier-demo/logs/app.log\n\n# Extraire vers un dossier de test\nmkdir -p restauration-demo\ntar -xzf sauvegarde-demo.tar.gz -C restauration-demo\n\n# Vérifier l’archive avec une empreinte\nsha256sum sauvegarde-demo.tar.gz > SHA256SUMS\nsha256sum -c SHA256SUMS\n# exemple de sortie (valeurs fictives)\n# sauvegarde-demo.tar.gz: OK","language":"bash"},{"type":"code","content":"# Synchroniser sans modifier la destination au premier essai\nrsync -a --dry-run -v /srv/atelier/ /backup/atelier/\n# exemple de sortie (valeurs fictives)\n# sending incremental file list\n# docs/rapport.txt\n# logs/app.log\n# sent 184 bytes  received 24 bytes  416.00 bytes/sec\n# total size is 2048  speedup is 9.85 (DRY RUN)\n\n# Créer, relire, restaurer et contrôler un dépôt restic\nrestic backup /srv/atelier\nrestic snapshots\n# exemple de sortie (valeurs fictives)\n# ID        Time                 Host      Tags        Paths\n# 7ab31c42  2026-10-02 20:00:01  srv-demo              /srv/atelier\n# c91d8f10  2026-10-01 20:00:01  srv-demo              /srv/atelier\n\nrestic restore latest --target /tmp/restore\nrestic forget --keep-daily 7 --keep-weekly 4 --keep-monthly 6 --prune\nrestic check","language":"text"},{"type":"example","content":"Exemple corrigé : avec une sauvegarde chaque soir et un dernier instantané daté du samedi 3 octobre, la politique « --keep-daily 7 --keep-weekly 4 --keep-monthly 6 » conserve 13 instantanés distincts, pas 17. Tu gardes 7 daily du 27 septembre au 3 octobre, 2 weekly supplémentaires pour les semaines finies le 20 et le 13 septembre, puis 4 monthly supplémentaires aux fins de mois de mai, juin, juillet et août. Les instantanés du 3 octobre et du 30 septembre comptent déjà comme daily, et certains comptent aussi comme weekly ou monthly. De même, une complète de 18 Gio suivie de six incrémentales de 2, 1, 3, 2, 2 et 1 Gio représente 29 Gio de données à stocker avant déduplication."},{"type":"callout","content":"Erreurs fréquentes : appeler « sauvegarde » un simple miroir non versionné ; lancer « rsync --delete » sans « --dry-run » ; oublier que le mot de passe du dépôt restic est aussi vital que les données ; croire un journal « succès » sans jamais tester une restauration."},{"type":"callout","content":"Sécurité : travaille sur tes propres données de test, une machine virtuelle ou un serveur autorisé. Avant d’utiliser une option destructive comme « --delete », fais un essai à blanc. Ne stocke jamais le mot de passe d’un dépôt de sauvegarde dans l’historique d’un shell ou dans un dépôt Git."},{"type":"callout","content":"À retenir : une archive, une synchronisation et une sauvegarde versionnée répondent à des besoins différents. « rsync » demande de la prudence, « restic » ajoute la mémoire des instantanés, et une sauvegarde non restaurée en test reste une promesse plus qu’une preuve."},{"type":"callout","content":"Pour pratiquer : Dans « TP 5 : mises à jour, disques et sauvegardes », lis un journal de sauvegarde, juge la rétention, vérifie si la restauration paraît réaliste, puis termine avec le quiz."},{"type":"resource","content":"Cybermalveillance.gouv.fr : effectuer des sauvegardes régulières","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/sauvegardes"},{"type":"resource","content":"Ubuntu-fr : rsync","url":"https://doc.ubuntu-fr.org/rsync"},{"type":"resource","content":"restic : la documentation (en anglais)","url":"https://restic.readthedocs.io/"}]}'::jsonb, 24, 30, 2),
  ('b064a56b-ffb8-202b-ce1c-8ec612a480eb', '776b1633-dd76-67f4-532f-87063a481f11', '35577acc-dd9f-fb64-5e46-c4db2e0534b8', 'Chiffrer sous Linux : LUKS, GnuPG et OpenSSL', 'Apprends à distinguer chiffrement de disque, de fichier et vérification d’intégrité, puis à utiliser GnuPG, OpenSSL et les empreintes sans te mettre en danger avec une commande destructive.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer le chiffrement d’un disque, d’un fichier et d’une signature, expliquer à quoi sert LUKS, vérifier une empreinte avec « sha256sum » ou OpenSSL, signer puis vérifier avec GnuPG, et reconnaître une commande trop risquée pour être collée telle quelle."},{"type":"callout","content":"Prérequis : avoir suivi « Sauvegarder sous Linux : tar, rsync, restic » et connaître la notion d’empreinte."},{"type":"callout","content":"Mise en situation : Rokia doit transmettre une archive sensible à un collègue et préparer le chiffrement d’un disque externe de sauvegarde. Elle veut aussi vérifier qu’un fichier téléchargé n’a pas été modifié. Rokia doit donc choisir le bon outil selon le besoin : chiffrer un volume entier, protéger un fichier, ou prouver l’intégrité et l’origine d’un téléchargement."},{"type":"callout","content":"Vidéo à venir : Chiffrer sous Linux sans confondre hash, signature et secret"},{"type":"text","content":"Le chiffrement ne sert pas toujours au même niveau. LUKS protège un disque ou une partition entière : utile pour un portable perdu ou un support de sauvegarde volé. GnuPG protège ou signe des fichiers : pratique pour un export de base, une archive ou un document à transmettre. « sha256sum » et « openssl dgst -sha256 » ne chiffrent rien : ils calculent une empreinte, c’est-à-dire un résumé détectant une modification accidentelle ou malveillante."},{"type":"schema","content":"Besoin                            Outil adapté\nprotéger un disque entier         LUKS avec cryptsetup\nprotéger un fichier à envoyer     GnuPG\nvérifier qu’un fichier n’a pas changé  sha256sum ou openssl dgst\nprouver l’origine d’un fichier    signature GnuPG + clé de confiance"},{"type":"text","content":"Avec LUKS, le danger principal est simple : « luksFormat » efface le périphérique visé. Cette commande n’est donc jamais un exemple à coller sur un vrai disque sans préparation. En revanche, il faut connaître le vocabulaire : « open » déverrouille, « close » referme, « luksDump » décrit l’en-tête, et « luksHeaderBackup » sauvegarde une partie critique de la structure. LUKS gère plusieurs emplacements de clé, ce qui aide à changer ou révoquer une phrase secrète sans rechiffrer tout le volume. Si tu perds la phrase secrète ou l’en-tête sans secours, les données peuvent devenir illisibles."},{"type":"text","content":"GnuPG permet un chiffrement symétrique avec « gpg -c », ou asymétrique avec « gpg -e -r ». Tu peux aussi déchiffrer avec « gpg -d », signer avec « gpg --detach-sign » et afficher l’empreinte d’une clé avec « gpg --fingerprint » pour la comparer à une source de confiance. Pour l’enseignement ici, la démonstration la plus sûre consiste à signer puis vérifier un fichier avec une clé de test jetable. Tu évites ainsi de passer un secret en argument de commande, ce qui serait visible dans un processus ou un historique. Les droits restent importants : un fichier sensible ou une clé privée devrait rester lisible seulement par son propriétaire."},{"type":"text","content":"Une empreinte seule ne suffit pas si elle vient du même site compromis que le fichier téléchargé. La signature ajoute un lien avec une clé publique connue. C’est pour cela que les projets sérieux publient à la fois une somme de contrôle et un moyen de vérifier l’identité du signataire. OpenSSL peut aussi calculer une empreinte ou générer de l’aléa avec « openssl rand -hex 16 », mais son chiffrement de fichier seul n’offre pas toujours les garanties d’authenticité que l’on attend d’une signature. Pour un support perdu ou volé, pense aussi aux sauvegardes chiffrées."},{"type":"text","content":"Démonstration guidée : dans Git Bash, calcule réellement une empreinte, demande à OpenSSL le même résumé, puis signe et vérifie un petit fichier avec une clé GnuPG temporaire. Sur un vrai Linux de test, tu peux ensuite lire un en-tête LUKS avec « cryptsetup luksDump ». Pour l’effacement, retiens une limite importante : « shred » n’est pas fiable partout, en particulier sur SSD et sur des systèmes de fichiers journalisés."},{"type":"code","content":"# Vérifier une archive avec deux outils\nsha256sum sauvegarde-demo.tar.gz\nopenssl dgst -sha256 sauvegarde-demo.tar.gz\n# exemple de sortie (valeurs fictives)\n# e0c527e1...5bb86df5  sauvegarde-demo.tar.gz\n# SHA2-256(sauvegarde-demo.tar.gz)= e0c527e1...5bb86df5\n\n# Signer puis vérifier un fichier avec une clé de test\ngpg --detach-sign rapport.txt\ngpg --verify rapport.txt.sig rapport.txt\n# exemple de sortie (valeurs fictives)\n# gpg: Good signature from \"Demo Linux C <demo-linux-c@example.com>\"","language":"bash"},{"type":"code","content":"# Lire un en-tête LUKS et préparer sa sauvegarde\ncryptsetup luksDump /dev/sdb1\n# exemple de sortie (valeurs fictives)\n# LUKS header information\n# Version:        2\n# UUID:           4b3a7b7d-6d8e-4bde-9c73-3b4f2e8c1234\n# Keyslots:\n#   0: luks2\n\ncryptsetup luksHeaderBackup /dev/sdb1 --header-backup-file entete-sdb1.img\n\ncryptsetup open /dev/sdb1 sauvegarde_luks\n# exemple de sortie (valeurs fictives)\n# Aucun texte si l’ouverture réussit","language":"text"},{"type":"example","content":"Exemple corrigé : tu télécharges une archive, une empreinte SHA-256 et une signature. Si l’empreinte correspond mais provient du même site compromis que l’archive, tu n’es pas encore rassuré. Le contrôle le plus solide consiste à vérifier la signature avec une clé publique de confiance, puis à confirmer que l’empreinte calculée localement correspond à celle annoncée par une source indépendante. Le hash seul détecte une modification ; la signature ajoute l’identité du signataire."},{"type":"callout","content":"Erreurs fréquentes : confondre empreinte et chiffrement ; vouloir lancer « luksFormat » sur un vrai disque juste pour tester ; passer une phrase secrète en argument de commande ; publier une clé privée ou un fichier secret avec des droits trop ouverts."},{"type":"callout","content":"Sécurité : ne chiffre que tes propres supports ou ceux que tu gères avec autorisation. Toute manipulation LUKS doit se faire sur un disque de test clairement identifié. N’inscris pas de secret dans une ligne de commande visible dans l’historique, et conserve les sauvegardes d’en-tête LUKS hors du volume chiffré."},{"type":"callout","content":"À retenir : le bon outil dépend du besoin : LUKS pour un volume, GnuPG pour un fichier ou une signature, « sha256sum » ou OpenSSL pour l’intégrité. Une empreinte ne prouve pas à elle seule l’origine d’un fichier, et une commande destructive sur un disque ne se teste jamais au hasard."},{"type":"callout","content":"Pour pratiquer : Dans « TP 5 : mises à jour, disques et sauvegardes », vérifie une empreinte, juge si un contrôle est suffisant et explique quelle preuve manque encore avant de répondre au quiz."},{"type":"resource","content":"Ubuntu-fr : GnuPG","url":"https://doc.ubuntu-fr.org/gpg"},{"type":"resource","content":"Debian : manuel de cryptsetup (en anglais)","url":"https://manpages.debian.org/stable/cryptsetup-bin/cryptsetup.8.en.html"},{"type":"resource","content":"OpenSSL : la documentation (en anglais)","url":"https://www.openssl.org/docs/"}]}'::jsonb, 24, 30, 3),
  ('65f63e26-d8b9-2dcb-0353-96ad3736df10', '776b1633-dd76-67f4-532f-87063a481f11', '5cfc6ce3-ee6c-80e9-8659-bda9989f2329', 'Écrire un premier script shell', 'Écris tes premiers scripts Bash, passe des arguments, lis un code de retour et automatise une petite tâche d’audit sans copier des commandes au hasard.', '{"blocks":[{"type":"callout","content":"Objectifs : écrire un script Bash avec un shebang, exécuter un fichier rendu exécutable, utiliser « $0 », « $1 », « $@ » et « $# », tester une condition simple, et relire la sortie avec « bash -n » puis « bash -x »."},{"type":"callout","content":"Prérequis : avoir suivi « Redirections et tubes : composer des commandes » et « Lire et chercher dans du texte : less, tail et grep »."},{"type":"callout","content":"Mise en situation : Awa reçoit un export de journal SSH et doit compter vite les échecs de connexion avant la réunion du matin. Elle travaille sur un poste Windows modeste, avec Git Bash, et veut éviter de retaper la même commande à chaque nouveau fichier. Un script shell lui permet d’encapsuler la logique, de la relire et de la rejouer sans rien oublier. Le but n’est pas de faire du « grand développement », mais d’automatiser proprement une tâche répétitive d’administration."},{"type":"callout","content":"Vidéo à venir : Écrire un premier script Bash sans magie"},{"type":"text","content":"Un script shell est un fichier texte que Bash lit ligne par ligne. La première ligne, « #!/bin/bash », s’appelle le shebang : elle indique quel interpréteur doit exécuter le fichier. Ensuite, tu rends le script exécutable avec « chmod +x ». Cette mécanique fonctionne sur un vrai Linux, mais aussi pour t’exercer gratuitement dans WSL, une machine virtuelle ou Git Bash. Sur Android, Termux suffit pour les scripts de base qui ne dépendent pas de « systemd » ou de droits d’administration."},{"type":"schema","content":"#!/bin/bash\n./script.sh journal.log\n\n$0  nom du script\n$1  premier argument\n$@  tous les arguments\n$#  nombre d’arguments\n$?  code de retour de la dernière commande\n\n0   succès\n1   erreur fonctionnelle simple\n2   mauvais usage du script"},{"type":"text","content":"Le shell remplace les variables avant d’exécuter une commande. « journal=$1 » stocke donc le premier argument dans la variable « journal ». Les tests de Bash, écrits avec « [[ ... ]] », servent à vérifier un fichier, un dossier ou un texte vide avant d’aller plus loin. Tu n’as pas besoin d’apprendre tout Bash d’un coup : pour un premier script utile, maîtrise d’abord les variables, « if », « for », « while », « $(commande) » et « printf »."},{"type":"text","content":"Démonstration guidée : voici un script minimal qui compte les lignes « Failed password » dans un export de journal. Il a été testé dans Git Bash sur un fichier d’exemple. La logique tient en trois étapes : prendre l’argument, compter avec « grep -c », puis afficher un résultat lisible."},{"type":"code","content":"# Script de base\ncat > compter-echecs.sh <<''EOF''\n#!/bin/bash\nfichier=$1\ncompte=$(grep -c \"Failed password\" \"$fichier\")\nprintf ''Echecs SSH: %s\\n'' \"$compte\"\nEOF\nchmod +x compter-echecs.sh\n./compter-echecs.sh auth.log\n# exemple de sortie (valeurs fictives)\n# Echecs SSH: 5","language":"bash"},{"type":"text","content":"Un deuxième usage classique consiste à boucler sur plusieurs fichiers. Le shell parcourt alors une liste, par exemple « ./*.jpg », et applique la même opération à chacun. Le mot-clé important est « même » : un script shell excelle sur des tâches répétitives, modestes et transparentes. Quand la logique devient longue ou fragile, tu gardes le shell pour l’orchestration et tu délègues le reste à un outil plus adapté."},{"type":"code","content":"# Renommer tous les JPG d''un dossier d''essai\ncat > renommer-jpg.sh <<''EOF''\n#!/bin/bash\nprefixe=$1\nfor fichier in ./*.jpg; do\n  base=${fichier#./}\n  nouveau=\"${prefixe}${base}\"\n  mv \"$base\" \"$nouveau\"\n  printf ''%s -> %s\\n'' \"$base\" \"$nouveau\"\ndone\nEOF\nchmod +x renommer-jpg.sh\n./renommer-jpg.sh archive-\nls -1 *.jpg *.txt\n# exemple de sortie (valeurs fictives)\n# photo final.jpg -> archive-photo final.jpg\n# photo-01.jpg -> archive-photo-01.jpg\n# archive-photo final.jpg\n# archive-photo-01.jpg\n# notes.txt","language":"bash"},{"type":"example","content":"Exemple corrigé : si ton dossier contient « photo-01.jpg », « photo final.jpg » et « notes.txt », le script de renommage ne touche que les fichiers qui correspondent au motif « *.jpg ». Il préserve l’espace dans « photo final.jpg » parce que le nouveau nom est construit dans une variable citée entre guillemets. Sans cette rigueur, tu passerais déjà d’un script utile à un script imprévisible."},{"type":"text","content":"Pour déboguer, commence par « bash -n script.sh » : Bash vérifie la syntaxe sans exécuter le fichier. Ensuite, « bash -x script.sh ... » montre chaque ligne au moment où elle part réellement vers l’interpréteur. Cette trace est précieuse quand un « if » ne prend pas la branche attendue ou quand une variable ne contient pas ce que tu crois."},{"type":"callout","content":"Erreurs fréquentes : oublier le shebang puis lancer le fichier comme un binaire ; confondre le nom du script « $0 » avec son premier argument « $1 » ; écrire un script sans le tester sur un petit jeu de données d’exemple ; croire qu’un copier-coller suffit sans relire les chemins et les variables."},{"type":"callout","content":"Sécurité : teste toujours tes premiers scripts dans un dossier de démonstration, sur ta machine, WSL, une machine virtuelle ou Termux. Évite les suppressions et les écritures sur des fichiers réels tant que tu n’as pas vérifié la sortie avec « echo », « printf » ou un simple « ls »."},{"type":"callout","content":"À retenir : un script shell est d’abord un fichier texte lisible. Le shebang choisit Bash, les arguments « $1 » et « $@ » font entrer les données, et le code de retour dit si l’exécution s’est bien passée. Commence petit, teste sur des exemples, puis ajoute une boucle ou une condition quand la tâche devient répétitive."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 6 : lire, tester et corriger des scripts shell », commence par prédire la sortie des petits scripts, puis rejoue la partie sur les arguments, les boucles et le débogage avec « bash -x ». Termine par le quiz de la leçon."},{"type":"resource","content":"Ubuntu-fr : les commandes de base de la console","url":"https://doc.ubuntu-fr.org/tutoriel/console_commandes_de_base"},{"type":"resource","content":"TLDP : guide de bash pour débutants (en anglais)","url":"https://tldp.org/LDP/Bash-Beginners-Guide/html/"},{"type":"resource","content":"GNU : le manuel de référence de Bash (en anglais)","url":"https://www.gnu.org/software/bash/manual/bash.html"}]}'::jsonb, 26, 30, 1),
  ('a42bf176-c05d-7248-ffa9-b7949df5db3c', '776b1633-dd76-67f4-532f-87063a481f11', '5cfc6ce3-ee6c-80e9-8659-bda9989f2329', 'Des scripts fiables et sûrs : guillemets, erreurs, ShellCheck', 'Rends tes scripts prévisibles : protège les variables, valide les arguments, nettoie les fichiers temporaires et comprends ce que ShellCheck signale vraiment.', '{"blocks":[{"type":"callout","content":"Objectifs : protéger une variable avec des guillemets, expliquer « set -euo pipefail », valider les arguments d’un script, utiliser « mktemp » et « trap » pour nettoyer, et corriger un avertissement ShellCheck de type SC2086."},{"type":"callout","content":"Prérequis : avoir suivi « Écrire un premier script shell » et déjà manipulé des fichiers avec espaces et jokers."},{"type":"callout","content":"Mise en situation : Koffi automatise une copie de journaux pour l’association Teranga. Le script marche sur « auth.log », mais casse le jour où quelqu’un lui donne « journal juin.log ». Comme il sera lancé plus tard par une tâche planifiée, il veut corriger le défaut avant de le déployer sur un serveur Debian. C’est exactement le moment où l’on passe d’un script « qui marche chez moi » à un script fiable."},{"type":"callout","content":"Vidéo à venir : Écrire des scripts Bash qui cassent moins"},{"type":"text","content":"Les trois pannes les plus courantes d’un script shell tiennent à peu de choses : une variable non citée entre guillemets, une variable vide qui change complètement le sens d’une commande, et une erreur ignorée qui laisse croire que tout va bien. Le shell découpe en mots et interprète les jokers avant de lancer la commande : si tu oublies les guillemets autour d’une variable, un simple espace dans un nom de fichier devient déjà un bug."},{"type":"schema","content":"Danger                     Symptôme                      Réflexe\nvariable non citée         espace découpe le nom         écrire \"$var\"\nvariable vide              chemin tronqué ou faux        vérifier l’argument\nerreur ignorée             script continue en silence    tester le retour\nfichier temporaire oublié  traces inutiles ou fuite      mktemp + trap"},{"type":"text","content":"Démonstration guidée : commence par observer l’échec, puis corrige-le. Le script cassé ci-dessous a été testé dans Git Bash avec un fichier nommé « journal juin.log ». Il tente de copier le fichier, mais comme « $fichier » n’est pas cité, Bash le découpe en deux morceaux. Le piège est double : la copie échoue, mais le script affiche quand même « copie terminee » et rend le code 0, car la dernière commande réussit. Le script corrigé ajoute « set -euo pipefail », cite la variable et affiche un message fiable."},{"type":"code","content":"# Script casse\ncat > copie-cassee.sh <<''EOF''\n#!/bin/bash\nfichier=$1\nmkdir -p copie\ncp $fichier copie/\nprintf ''copie terminee\\n''\nEOF\nchmod +x copie-cassee.sh\n./copie-cassee.sh \"journal juin.log\"\necho $?\n# exemple de sortie (valeurs fictives)\n# cp: cannot stat ''journal'': No such file or directory\n# cp: cannot stat ''juin.log'': No such file or directory\n# copie terminee\n# 0\n\n# Script corrige\ncat > copie-sure.sh <<''EOF''\n#!/bin/bash\nset -euo pipefail\nfichier=${1:?usage: ./copie-sure.sh \"fichier\"}\nmkdir -p copie\ncp -- \"$fichier\" copie/\nprintf ''copie terminee : %s\\n'' \"$(basename \"$fichier\")\"\nEOF\nchmod +x copie-sure.sh\n./copie-sure.sh \"journal juin.log\"\nls -1 copie\n# exemple de sortie (valeurs fictives)\n# copie terminee : journal juin.log\n# journal juin.log","language":"bash"},{"type":"text","content":"« set -euo pipefail » aide beaucoup, mais ne remplace pas la lecture du script. « -e » arrête sur beaucoup d’erreurs, « -u » refuse les variables non définies, et « pipefail » fait remonter l’échec d’une commande située à gauche d’un tube. Pourtant, « -e » ne déclenche pas dans tous les contextes : un test dans « if », la branche gauche de « || » ou un « grep » qui ne trouve rien peuvent demander un traitement explicite. Tu gardes donc un esprit critique : le but n’est pas de réciter une formule magique, mais de décider quand vérifier volontairement une condition."},{"type":"code","content":"# Squelette robuste pour un fichier temporaire\ncat > squelette.sh <<''EOF''\n#!/bin/bash\nset -euo pipefail\ntmp=$(mktemp)\ntrap ''rm -f \"$tmp\"'' EXIT\njournal=${1:?usage: ./squelette.sh journal.log}\n[[ -f \"$journal\" ]] || { printf ''fichier absent : %s\\n'' \"$journal\" >&2; exit 2; }\ngrep ''Failed password'' \"$journal\" > \"$tmp\"\nwc -l \"$tmp\"\nEOF\nbash -n squelette.sh\n# exemple de sortie (valeurs fictives)\n# aucune sortie : la syntaxe est correcte","language":"bash"},{"type":"text","content":"ShellCheck complète cette discipline. Son avertissement SC2086 signale précisément les expansions non citées, comme « cp $fichier copie/ ». Il ne faut pas suivre l’outil aveuglément, mais le message est souvent un bon déclencheur de relecture. Sur un poste modeste, tu peux déjà coller un script dans le site du projet si tu n’as pas encore l’outil installé localement."},{"type":"example","content":"Exemple corrigé : dans un script de dix lignes qui lance « tar -czf $archive $dossier », écrit « PATH=.:$PATH » et reçoit un mot de passe en argument, trois défauts sautent aux yeux. D’abord, « $archive » et « $dossier » doivent être cités. Ensuite, ajouter « . » au PATH expose à l’exécution d’un faux programme placé dans le dossier courant. Enfin, un secret en argument reste visible dans les colonnes « COMMAND » ou « CMD » de « ps » : mieux vaut lire ce secret depuis l’entrée standard, un fichier protégé ou une variable d’environnement bien contrôlée."},{"type":"callout","content":"Erreurs fréquentes : ajouter « set -euo pipefail » puis croire le script infaillible ; écrire des chemins relatifs dans un script prévu pour cron ; utiliser « eval » sur une entrée externe alors qu’une variable ou un tableau suffit ; laisser des fichiers temporaires traîner dans « /tmp » ou le dossier courant."},{"type":"callout","content":"Sécurité : n’exécute pas un script reçu d’un tiers sans le lire. Les scripts lancés avec des droits élevés doivent utiliser des chemins absolus, vérifier leurs entrées et éviter les secrets en argument, car ceux-ci peuvent apparaître dans la liste des processus."},{"type":"callout","content":"À retenir : un script robuste commence par des guillemets, une validation d’arguments et une gestion claire des erreurs. « set -euo pipefail » aide, « mktemp » et « trap » nettoient, et ShellCheck rappelle les pièges classiques avant qu’ils n’arrivent en production."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 6 : lire, tester et corriger des scripts shell », retrouve la ligne qui casse sur un espace, puis corrige les variables non protégées et les arguments manquants. Termine par le quiz de la leçon."},{"type":"resource","content":"ShellCheck : SC2086, mettre les variables entre guillemets (en anglais)","url":"https://www.shellcheck.net/wiki/SC2086"},{"type":"resource","content":"ShellCheck : analyser ses scripts shell (en anglais)","url":"https://www.shellcheck.net/"},{"type":"resource","content":"GNU : le manuel de référence de Bash (en anglais)","url":"https://www.gnu.org/software/bash/manual/bash.html"}]}'::jsonb, 24, 30, 2),
  ('d29853c9-a6eb-20d9-1606-8469dfbad22d', '776b1633-dd76-67f4-532f-87063a481f11', '5cfc6ce3-ee6c-80e9-8659-bda9989f2329', 'Automatiser la sécurité : inventaires, alertes et rapports', 'Écris trois petits scripts défensifs : compter des échecs SSH, suivre l’intégrité d’un dossier et déclencher une alerte simple sur l’occupation d’un disque.', '{"blocks":[{"type":"callout","content":"Objectifs : compter des échecs de connexion par adresse IP, générer puis vérifier un manifeste d’empreintes, parser une sortie « df » pour retourner un code d’alerte, et formater une sortie lisible pour cron ou une supervision simple."},{"type":"callout","content":"Prérequis : avoir suivi « Des scripts fiables et sûrs : guillemets, erreurs, ShellCheck » et connaître « Trouver, comparer et archiver : find, diff, tar »."},{"type":"callout","content":"Mise en situation : Nadia prépare une petite boîte à outils défensive pour Baobab Tech. Elle n’a pas encore accès au serveur de production, mais elle veut tester toute la logique dans Git Bash avant de la déployer sur Debian. Son objectif n’est pas d’écrire un énorme produit de supervision : elle veut trois scripts simples, lisibles et assez fiables pour l’alerter sur des symptômes concrets."},{"type":"callout","content":"Vidéo à venir : Trois petits scripts shell utiles pour la défense"},{"type":"text","content":"Un bon script de sécurité ne remplace ni une supervision complète, ni un EDR, ni un audit humain. En revanche, il sait faire une chose précise et la faire clairement : compter des échecs, produire un manifeste, signaler un seuil dépassé. La vraie valeur tient souvent dans la sortie : une ligne facile à relire, un code de retour cohérent, un jeu de données d’exemple pour vérifier que l’alerte part quand elle doit partir."},{"type":"schema","content":"Format de sortie conseillé\nOK;détail\nALERTE;détail\n\nCode de retour\n0  état normal\n1  alerte à relire\n2  mauvais usage du script"},{"type":"text","content":"Démonstration guidée : premier cas, repérer les adresses qui dépassent un seuil d’échecs SSH. Le script ci-dessous a été testé dans Git Bash sur un export de journal d’exemple. Il filtre les lignes « Failed password », récupère le champ placé après « from », compte avec « uniq -c » et n’affiche que les adresses au-dessus du seuil demandé. S’il n’y a aucun échec dans le fichier, il ne doit pas échouer juste parce que la recherche ne trouve rien."},{"type":"code","content":"# Script d''alerte sur les echecs SSH\ncat > alerte-bruteforce.sh <<''EOF''\n#!/bin/bash\nset -euo pipefail\njournal=${1:?usage: ./alerte-bruteforce.sh journal seuil}\nseuil=${2:?usage: ./alerte-bruteforce.sh journal seuil}\nawk ''/Failed password/ { for (i = 1; i <= NF; i++) if ($i == \"from\") print $(i + 1) }'' \"$journal\" | sort | uniq -c | awk -v seuil=\"$seuil\" ''$1 >= seuil { printf \"%s;%s\\n\", $2, $1 }''\nEOF\nchmod +x alerte-bruteforce.sh\n./alerte-bruteforce.sh auth.log 3\n# exemple de sortie (valeurs fictives)\n# 192.168.1.20;4","language":"bash"},{"type":"text","content":"Deuxième cas, l’intégrité. Tu peux figer l’état d’un dossier en calculant les empreintes SHA-256 de ses fichiers, puis vérifier plus tard si l’un d’eux a changé. Le manifeste doit être écrit dans le dossier audité avec un chemin cohérent, et la collecte doit accepter les noms contenant des espaces. Pour tester le cas d’échec, modifie ensuite un fichier avant de lancer la vérification. Cette méthode dit qu’un fichier a changé, pas pourquoi, ni qui l’a changé : elle complète un audit, elle ne le remplace pas."},{"type":"code","content":"# Initialiser puis verifier un manifeste d''integrite\ncat > integrite.sh <<''EOF''\n#!/bin/bash\nset -euo pipefail\nmode=${1:?usage: ./integrite.sh init|check dossier manifeste}\ndossier=${2:?usage: ./integrite.sh init|check dossier manifeste}\nmanifeste=${3:?usage: ./integrite.sh init|check dossier manifeste}\nmanifeste_nom=$(basename \"$manifeste\")\ncase \"$mode\" in\n  init)\n    (cd \"$dossier\" && find . -maxdepth 1 -type f ! -name \"$manifeste_nom\" -printf ''%P\\0'' | LC_ALL=C sort -z | xargs -0 sha256sum -- > \"$manifeste_nom\")\n    ;;\n  check)\n    (cd \"$dossier\" && sha256sum -c \"$manifeste_nom\")\n    ;;\n  *)\n    echo ''mode inconnu'' >&2\n    exit 2\n    ;;\nesac\nEOF\nchmod +x integrite.sh\n./integrite.sh init empreintes empreintes/manifeste.sha256\ncat empreintes/manifeste.sha256\nprintf ''port=2222\\n'' > empreintes/config.txt\n./integrite.sh check empreintes empreintes/manifeste.sha256\n# exemple de sortie (valeurs fictives)\n# 74a74a728a6f1b19a9a327f223db0c58cfa8c216d8ae75a1a636990c03de27ee *config.txt\n# f4a3b0f16b45a4139d92d6dd9993a35bb7328440d5aa8036b32f02c4ca167bb7 *liste.txt\n# config.txt: FAILED\n# liste.txt: OK\n# sha256sum: WARNING: 1 computed checksum did NOT match","language":"bash"},{"type":"text","content":"Troisième cas, la supervision minimale. Un script lancé par cron ou par un minuteur doit pouvoir dire rapidement « tout va bien » ou « alerte ». Le plus simple est de parser une sortie « df » exportée, puis de retourner 1 quand le seuil est atteint. Sur un vrai serveur Linux, tu liras directement la commande « df -hP / » ; pour t’exercer sans risque, tu peux commencer avec un fichier d’exemple."},{"type":"code","content":"# Alerter si un point de montage depasse un seuil\ncat > verifier-df.sh <<''EOF''\n#!/bin/bash\nset -euo pipefail\nfichier=${1:?usage: ./verifier-df.sh fichier seuil}\nseuil=${2:?usage: ./verifier-df.sh fichier seuil}\nawk -v seuil=\"$seuil\" ''NR==1 { next } { taux=$5; gsub(/%/, \"\", taux); if (taux + 0 >= seuil) { printf \"ALERTE;%s;%s\\n\", $6, taux; trouve=1; exit 1 } } END { if (!trouve && NR > 1) { printf \"OK;%s\\n\", seuil } }'' \"$fichier\"\nEOF\nchmod +x verifier-df.sh\n./verifier-df.sh df.txt 80\necho $?\n# exemple de sortie (valeurs fictives)\n# ALERTE;/;85\n# 1","language":"bash"},{"type":"example","content":"Exemple corrigé : si ton seuil vaut 85 % sur un volume de 20 Gio, l’alerte doit partir dès 17 Gio utilisés. Le calcul est simple, mais il faut l’écrire une bonne fois : 20 × 0,85 = 17. Dans un rapport, cette conversion aide à expliquer le seuil à une équipe qui raisonne en taille libre et non en pourcentage."},{"type":"text","content":"Ces trois scripts deviennent vraiment utiles quand tu les relies à une tâche planifiée, à un journal et à une habitude de relecture. Un script qui écrit « ALERTE » cinquante fois par jour sans tri finit ignoré. Un script qui produit une ligne sobre, une preuve vérifiable et un code de retour stable est beaucoup plus exploitable pour un administrateur débutant."},{"type":"callout","content":"Erreurs fréquentes : parser un format qui change sans le documenter ; mélanger un rôle d’alerte et un rôle de correction automatique dans le même script ; oublier de tester le code de retour, donc de laisser une supervision aveugle ; garder des exemples trop optimistes qui n’exercent jamais le cas d’échec."},{"type":"callout","content":"Sécurité : les scripts d’alerte se testent d’abord sur des exports ou dans un dossier d’essai. N’écris jamais de mot de passe en clair dans le script, et n’envoie pas automatiquement des actions de correction sur un serveur que tu n’as pas relu et autorisé."},{"type":"callout","content":"À retenir : un petit script défensif vaut par sa clarté : entrée simple, sortie lisible, code de retour cohérent. Compter, vérifier et alerter sont trois tâches parfaites pour le shell tant que tu travailles sur des formats bien compris et des jeux de données testés."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 6 : lire, tester et corriger des scripts shell », rejoue les parties sur les sorties de journaux, les empreintes et les codes de retour, puis adapte les scripts aux fichiers fournis. Termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives à un système GNU/Linux","url":"https://cyber.gouv.fr/publications/recommandations-de-securite-relatives-un-systeme-gnulinux"},{"type":"resource","content":"ShellCheck : analyser ses scripts shell (en anglais)","url":"https://www.shellcheck.net/"},{"type":"resource","content":"GNU : le manuel des coreutils (en anglais)","url":"https://www.gnu.org/software/coreutils/manual/coreutils.html"}]}'::jsonb, 26, 30, 3),
  ('88d61c39-020a-1667-0f76-711b251e13f2', '776b1633-dd76-67f4-532f-87063a481f11', 'c79314fa-4ab0-cdb2-daee-16b4b6c1dbc3', 'Durcir un serveur Linux : checklist, Lynis et référentiels', 'Réduis la surface d’attaque d’un serveur Linux avec une checklist claire, des commandes d’audit ciblées et des référentiels comme l’ANSSI, CIS ou Lynis.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer ce qu’est le durcissement, vérifier une checklist de base, interpréter un extrait de Lynis, justifier l’intérêt d’AppArmor ou SELinux, et prioriser des actions selon l’impact et l’exploitabilité."},{"type":"callout","content":"Prérequis : avoir suivi « SSH : connexion, clés et durcissement de sshd_config », « Pare-feu sous Linux : ufw et nftables » et « Correctifs de sécurité, mises à jour et fin de support »."},{"type":"callout","content":"Mise en situation : Moussa reprend un petit serveur web Ubuntu pour Sahel Services. Le site fonctionne, mais personne ne sait vraiment ce qui écoute, quels services sont actifs ni si les sauvegardes sont testées. Moussa ne cherche pas un score parfait pour faire joli : il veut fermer d’abord les portes les plus faciles à abuser, sans casser le service rendu aux utilisateurs."},{"type":"callout","content":"Vidéo à venir : Durcir un serveur Linux sans se perdre dans une liste infinie"},{"type":"text","content":"Durcir un serveur, c’est réduire la surface d’attaque et limiter les dégâts d’une compromission. On retire ce qui ne sert pas, on garde le système à jour, on applique le moindre privilège, on ferme le réseau par défaut et on journalise ce qui compte. Le durcissement n’est pas une course au réglage le plus obscur : c’est une suite de décisions défendables, testées une à une, avec retour arrière possible."},{"type":"schema","content":"Famille                 Vérifications de base\nservices                désactiver l’inutile, compte dédié\ncorrectifs              paquets à jour, redémarrage planifié\ncomptes et SSH          clés, sudo précis, pas de root direct\nréseau                  ports utiles, pare-feu en refus par défaut\nfichiers                droits stricts, partitions sensibles\npreuves                 journaux, sauvegardes, vérification"},{"type":"text","content":"Une checklist simple couvre déjà l’essentiel : installation minimale, comptes nominatifs, clés SSH plutôt que mots de passe, règle « deny incoming » au pare-feu, surveillance des ports à l’écoute, sauvegardes testées, et contrôle d’accès obligatoire si disponible. Sur Ubuntu et Debian, AppArmor ajoute une couche de contrôle d’accès au-dessus des droits classiques. Sur RHEL et Fedora, le rôle est souvent tenu par SELinux. Dans les deux cas, le but est le même : limiter ce qu’un service compromis peut faire."},{"type":"text","content":"Démonstration guidée : commence par relever l’état actuel avant de changer quoi que ce soit. Sur un vrai serveur Linux, tu peux lister les paquets à mettre à jour, les ports ouverts, les unités activées et les fichiers SUID. Tu peux aussi lire quelques paramètres « sysctl » utiles : « kernel.randomize_va_space = 2 » active la randomisation complète de l’espace d’adressage, « net.ipv4.tcp_syncookies = 1 » laisse le noyau activer les SYN cookies quand la file SYN déborde, et « net.ipv4.conf.all.accept_redirects = 0 » évite d’accepter des redirections ICMP sur un serveur durci."},{"type":"code","content":"# Releve de base sur un serveur Debian ou Ubuntu\napt list --upgradable\nss -tulpn\nsystemctl list-unit-files --state=enabled\nfind / -xdev -perm -4000 -type f 2>/dev/null\nsysctl kernel.randomize_va_space net.ipv4.tcp_syncookies net.ipv4.conf.all.accept_redirects\nlynis audit system\n# exemple de sortie (format reel, valeurs variables selon l''hote)\n# kernel.randomize_va_space = 2\n# net.ipv4.tcp_syncookies = 1\n# net.ipv4.conf.all.accept_redirects = 0","language":"bash"},{"type":"text","content":"Lynis et les référentiels CIS ou ANSSI servent de guide, pas de pilote automatique. Sur l’écran, Lynis enchaîne des tests marqués « [ OK ] » ou « [ WARNING ] », puis regroupe en fin d’exécution les sections « Warnings », « Suggestions » et un « Hardening index ». La documentation du projet précise aussi que le détail technique part dans « /var/log/lynis.log » et les constats utiles dans « lynis-report.dat ». Un indice ou une suggestion n’a donc de valeur que si tu la relies à ton contexte : un port ouvert sans usage, oui, c’est une priorité. Une recommandation qui casse une application critique sans alternative claire, non."},{"type":"schema","content":"Prioriser un constat\nimpact élevé + exploitable à distance      critique\nimpact élevé ou exploitable localement     important\nimpact limité et peu exploitable           mineur\n\nNote aussi l’exposition, la preuve et l’effort de correction."},{"type":"example","content":"Exemple corrigé : si « PasswordAuthentication yes » reste actif sur un SSH exposé à Internet, que le pare-feu autorise trop large et qu’un compte de service possède un shell interactif, tu cumules des constats à forte exploitabilité. Le premier et le deuxième valent facilement 9 sur 9 dans une matrice simple, car l’impact et l’exploitabilité sont élevés. À l’inverse, une rotation de journaux perfectible mais sans panne immédiate ressemble plutôt à un 4 sur 9 : il faut la corriger, mais après les accès distants et le filtrage."},{"type":"callout","content":"Erreurs fréquentes : empiler des changements en une seule maintenance, puis ne plus savoir lequel a cassé le service ; viser un score Lynis parfait sans relire les recommandations ; laisser des mots de passe SSH actifs « juste le temps de tester » ; oublier de documenter l’état avant et après le durcissement."},{"type":"callout","content":"Sécurité : ne durcis jamais directement un serveur que tu ne maîtrises pas sans sauvegarde, fenêtre de changement et retour arrière. Une règle de pare-feu ou un réglage SSH appliqué trop vite peut te couper l’accès ; garde une console ou une session déjà ouverte pendant le test."},{"type":"callout","content":"À retenir : durcir, c’est choisir et vérifier. La base reste simple : moins de services, moins de privilèges, moins de ports, plus de journaux et des sauvegardes testées. Les référentiels et Lynis aident à ne rien oublier, mais la décision finale doit toujours rester contextualisée."},{"type":"callout","content":"Pour pratiquer : ouvre le « Projet final : auditer un serveur Linux et rédiger le rapport », utilise la checklist du cours pour prioriser les écarts, puis compare ta hiérarchie avec les preuves du dossier. Termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives à un système GNU/Linux","url":"https://cyber.gouv.fr/publications/recommandations-de-securite-relatives-un-systeme-gnulinux"},{"type":"resource","content":"Lynis : audit de sécurité et durcissement des systèmes Unix (en anglais)","url":"https://cisofy.com/lynis/"},{"type":"resource","content":"CIS : les guides de configuration sécurisée (benchmarks) (en anglais)","url":"https://www.cisecurity.org/cis-benchmarks"},{"type":"resource","content":"Red Hat : durcissement de la sécurité de RHEL 9 (en anglais)","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9/html/security_hardening/index"}]}'::jsonb, 26, 30, 3),
  ('359dfa04-a40b-267c-8ce6-2aca7199de2c', '776b1633-dd76-67f4-532f-87063a481f11', 'c79314fa-4ab0-cdb2-daee-16b4b6c1dbc3', 'Mener un audit Linux et rédiger le rapport', 'Cadre, collecte de preuves, gravité, constats et restitution : apprends une méthode d’audit Linux défensive, lisible et compatible avec un vrai rapport.', '{"blocks":[{"type":"callout","content":"Objectifs : cadrer un audit avec autorisation écrite, collecter des preuves en lecture seule, horodater puis hacher les sorties, qualifier une gravité selon l’impact et l’exploitabilité, et rédiger un constat avec preuve, gravité, recommandation et effort."},{"type":"callout","content":"Prérequis : avoir suivi « Auditer droits, comptes et tâches planifiées » et « Durcir un serveur Linux : checklist, Lynis et référentiels »."},{"type":"callout","content":"Mise en situation : Fatou doit auditer un serveur Debian pour Cabinet Moussa avant une mise en production. Elle a l’autorisation écrite, une fenêtre courte et un objectif clair : relever les écarts sans modifier l’hôte. Son rapport devra être lisible par la direction, mais aussi assez précis pour qu’un administrateur puisse corriger les points relevés et prouver ensuite qu’ils le sont."},{"type":"callout","content":"Vidéo à venir : La méthode d’audit Linux, de la preuve au rapport"},{"type":"text","content":"Un audit Linux commence avant la première commande. Tu définis le périmètre, les comptes autorisés, la fenêtre de temps et le niveau d’intrusion acceptable. En pratique, le mot d’ordre est simple : lecture seule d’abord. Tu documentes les commandes prévues, la destination des preuves et la personne qui valide le cadre. Sans cela, tu risques de modifier le système audité ou de produire un rapport contestable."},{"type":"schema","content":"Étapes d’un audit\n1 cadrer : périmètre, accord écrit, fenêtre\n2 collecter : commandes en lecture seule\n3 figer : horodatage et empreintes\n4 croiser : comptes, réseau, services, journaux\n5 noter : gravité, effort, priorité\n6 restituer : résumé, constats, annexes"},{"type":"text","content":"La collecte de preuves doit être répétable. Tu récupères l’identité du système, la liste des comptes, les services activés, les ports à l’écoute, les tâches planifiées, la configuration SSH, le pare-feu, l’occupation disque et quelques journaux utiles. Chaque sortie est horodatée et conservée telle quelle, puis tu en calcules une empreinte. Cette discipline ne rend pas la preuve parfaite à elle seule, mais elle limite déjà les contestations du type « ce fichier a été retouché après coup »."},{"type":"text","content":"Démonstration guidée : même sans serveur Linux sous la main, tu peux déjà répéter la méthode dans Git Bash avec des commandes disponibles partout, puis réserver les commandes propres au noyau Linux au serveur audité. Le script ci-dessous a été testé sur des données d’exemple et produit un fichier de preuves horodaté avec son empreinte."},{"type":"code","content":"# Script d''inventaire minimal\ncat > inventaire.sh <<''EOF''\n#!/bin/bash\nset -euo pipefail\nsortie=${1:?usage: ./inventaire.sh sortie preuve}\npreuve=${2:?usage: ./inventaire.sh sortie preuve}\nbase=$(dirname \"$sortie\")\npreuve_nom=$(basename \"$preuve\")\nsortie_nom=$(basename \"$sortie\")\n{\n  printf ''# date_utc\\n''\n  date -u +\"%Y-%m-%dT%H:%M:%SZ\"\n  printf ''# uname\\n''\n  uname -a\n  printf ''# id\\n''\n  id\n  printf ''# sha256\\n''\n  (cd \"$base\" && sha256sum \"$preuve_nom\")\n} > \"$sortie\"\n(cd \"$base\" && sha256sum \"$sortie_nom\")\nEOF\nchmod +x inventaire.sh\nprintf ''preuve demo\\n'' > preuve.txt\n./inventaire.sh preuves.txt preuve.txt\ncat preuves.txt\n# exemple de sortie (format reel, valeurs variables selon l''hote et l''heure)\n# d440ec35ae9cdc870eee330cd0bff4976e5f71d5966f59a0fac3b1c928fc55f4 *preuves.txt\n# # date_utc\n# 2026-10-03T20:14:33Z\n# # uname\n# MINGW64_NT-10.0-26200 DESKTOP-HLJ4RBP 3.6.10-5a1665c8.x86_64 2026-09-28 10:40 UTC x86_64 Msys\n# # id\n# uid=197609(Evans Abah) gid=197609 groups=197609\n# # sha256\n# d816f0cc00168adbaa0a2e37f706f5ac289b8cf5c982c2f9e0cafd29186e4ce1 *preuve.txt","language":"bash"},{"type":"text","content":"Sur le vrai serveur, tu ajoutes ensuite les commandes de lecture seule utiles au périmètre : « uname -a », « getent passwd », « id », « ss -tulpn », « systemctl list-unit-files --state=enabled », « crontab -l », « journalctl -u ssh --since », « ufw status verbose », « find / -xdev -perm -0002 » et d’autres relevés comparables. L’idée n’est pas d’exécuter tout ce qui existe, mais de couvrir les familles de risque pertinentes et de pouvoir relier chaque constat à une preuve précise. Un bon rapport distingue aussi nettement la gravité du constat, l’effort de correction et l’éventuelle urgence métier."},{"type":"schema","content":"Structure d’un constat\nObservation : ce que tu vois\nPreuve : commande, fichier, extrait\nGravité : critique, importante, mineure\nRecommandation : quoi changer\nEffort : faible, moyen, élevé"},{"type":"example","content":"Exemple corrigé : 1) observation, « le fichier /etc/sudoers.d/nadia accorde NOPASSWD: ALL » ; preuve, la ligne extraite du fichier ; gravité, critique car l’impact et l’exploitabilité sont forts ; recommandation, limiter à des commandes précises ; effort, faible. 2) observation, « le service PostgreSQL écoute seulement sur 127.0.0.1 » ; preuve, la ligne « 127.0.0.1:5432 » dans « ss -tulpn » ; gravité, mineure ; recommandation, aucune urgente. 3) observation, « une tâche cron root appelle un script modifiable par tous » ; preuve, la ligne cron et le mode de fichier ; gravité, critique ; recommandation, corriger les droits et revoir la tâche ; effort, moyen."},{"type":"text","content":"Le rapport final parle à deux publics. En tête, un résumé d’une page maximum explique les risques majeurs, les priorités et les prochaines étapes. Ensuite, un tableau de constats aligne observation, preuve, gravité, recommandation et effort. Les annexes conservent les extraits de commandes et les empreintes. Un audit n’est pas une investigation d’incident : il décrit un état à un instant donné. Quand tu dois reconstruire une intrusion, tu t’orientes plutôt vers une chronologie, comme dans l’évaluation « Incident : un serveur web Linux compromis »."},{"type":"callout","content":"Erreurs fréquentes : auditer sans autorisation écrite ni périmètre ; modifier le système pendant la collecte alors que la mission porte sur l’état observé ; produire un constat sans preuve vérifiable ; écrire des recommandations vagues comme « améliorer la sécurité » sans indiquer quoi changer ni avec quel effort."},{"type":"callout","content":"Sécurité : un audit donne accès à des comptes, des journaux et parfois des données personnelles. Respecte la confidentialité, minimise les copies, protège les preuves collectées et ne conserve pas plus d’informations que nécessaire après la mission."},{"type":"callout","content":"À retenir : un audit Linux crédible repose sur le cadre, la preuve et la rédaction. Lecture seule d’abord, empreintes ensuite, puis constats argumentés. Un bon rapport dit ce qui a été vu, pourquoi c’est risqué, comment corriger, et quel effort prévoir."},{"type":"callout","content":"Pour pratiquer : ouvre le « Projet final : auditer un serveur Linux et rédiger le rapport », applique la méthode du cours pour tes preuves et tes constats, puis compare ton résumé avec les annexes. Reprends aussi « Incident : un serveur web Linux compromis » pour bien distinguer audit d’état et reconstitution d’intrusion. Termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : guide d’hygiène informatique","url":"https://cyber.gouv.fr/publications/guide-dhygiene-informatique"},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives à un système GNU/Linux","url":"https://cyber.gouv.fr/publications/recommandations-de-securite-relatives-un-systeme-gnulinux"},{"type":"resource","content":"NIST : cadre de cybersécurité (CSF) (en anglais)","url":"https://www.nist.gov/cyberframework"},{"type":"resource","content":"Lynis : audit de sécurité et durcissement des systèmes Unix (en anglais)","url":"https://cisofy.com/lynis/"}]}'::jsonb, 24, 30, 4)
