  ('c732c89f-61e7-2e2c-36dd-b7dc453f3595', '776b1633-dd76-67f4-532f-87063a481f11', '35577acc-dd9f-fb64-5e46-c4db2e0534b8', 'b064a56b-ffb8-202b-ce1c-8ec612a480eb', 'Quiz : chiffrement Linux', 70, 3),
  ('406a868c-2ae2-23ee-15ee-0b1424ca1fd4', '776b1633-dd76-67f4-532f-87063a481f11', '5cfc6ce3-ee6c-80e9-8659-bda9989f2329', '65f63e26-d8b9-2dcb-0353-96ad3736df10', 'Quiz : écrire un premier script shell', 70, 1),
