insert into public.labs (id, slug, title, description, category, difficulty, xp_reward, objectives, hints, terminal_lines, position, course_id, format, briefing, constraints, tools, requires_computer, is_assessment, estimated_minutes) values
  ('0ed89ec4-11bf-d087-9263-7049be0c2520', 'tp-linux-arborescence', 'TP 1 : explorer l’arborescence et chercher dans les fichiers', 'Tu lis un export d’arborescence, un historique de navigation, un journal web et un CSV d’adhérents pour retrouver des chemins, compter, comparer et filtrer des informations utiles.', 'linux', 'debutant', 130, array['Lire une arborescence au format « ls -lR »', 'Résoudre des chemins absolus et relatifs sans te tromper', 'Compter et regrouper des lignes utiles dans un journal web', 'Filtrer un CSV séparé par des points-virgules']::text[], array['Une section de l’arborescence décrit seulement le contenu direct du dossier affiché.', 'Dans l’historique, « cd - » revient au dossier précédent, pas au parent.', 'Pour le journal web, commence par isoler la méthode, le chemin et le code HTTP.', 'Dans le CSV, la ville est la troisième colonne et la formule la quatrième.']::text[], '{}'::text[], 600, '776b1633-dd76-67f4-532f-87063a481f11', 'logs', 'Le lundi 6 avril 2026, Cheikh Fall découvre les exports que lui a préparés Ousmane Diallo pour se repérer sur le serveur de fichiers de la Mutuelle Alizé. Il a sous les yeux une partie de l’arborescence de « /srv », « /home » et « /etc/alize », son historique de commandes, un journal d’accès web de la journée et la liste CSV d’adhérents. Tu dois lui montrer comment retrouver un dossier, suivre une suite de « cd », compter des événements dans les journaux et exploiter un CSV sans jamais toucher un vrai serveur.', array['Tout se résout à partir des fichiers fournis, dans un cadre fictif et figé.', 'Ne suppose rien du système de ta machine locale : raisonne seulement sur les exports du labo.']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour grep, awk et sort', 'PowerShell 5.1 si tu es sur Windows']::text[], false, false, 40),
  ('89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 'tp-linux-comptes-droits', 'TP 2 : auditer les droits, les comptes et sudo', 'Tu recoupes les exports de comptes, de groupes, de sudo, de permissions et de SUID pour repérer des défauts concrets sans toucher à une vraie machine.', 'linux', 'intermediaire', 150, array['Lire les champs utiles de passwd, shadow et group', 'Identifier un compte privilégié ou un shell anormal', 'Comparer des règles sudo et des permissions à risque', 'Repérer un binaire SUID inattendu et des comptes dormants']::text[], array['Le troisième champ de passwd est l’UID ; le septième est le shell.', 'Dans shadow, un champ vide n’est pas la même chose qu’un compte verrouillé.', 'Pour sudo, compare le périmètre réel de chaque règle, pas seulement le nom du fichier.', 'Dans lastlog, « Never logged in » compte comme absence totale de connexion.']::text[], '{}'::text[], 610, '776b1633-dd76-67f4-532f-87063a481f11', 'logs', 'Le mardi 7 avril 2026, Ousmane Diallo prépare l’arrivée d’un nouveau prestataire sur « srv-fichiers01 ». Avant d’ouvrir plus d’accès, il exporte « /etc/passwd », « /etc/shadow », « /etc/group », les règles sudo, des permissions sensibles, la liste des binaires SUID et les dernières connexions. Tu dois retrouver les comptes anormaux, lire correctement les empreintes, comparer les shells, évaluer les permissions et signaler les éléments les plus risqués avec des preuves précises.', array['Tous les comptes et empreintes de ce lab sont fictifs.', 'Tu ne modifies rien : tu interprètes uniquement des exports textuels.']::text[], array['Visionneuse du site', 'Git Bash ou WSL pour awk, grep et sort', 'PowerShell 5.1 pour les variantes Windows']::text[], false, false, 50),
  ('0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 'tp-linux-processus-services', 'TP 3 : processus, services et tâches planifiées', 'Tu relies des sorties de processus, de services, de ports, de cron et de minuteurs systemd pour comprendre une charge anormale sur un serveur web Linux.', 'linux', 'intermediaire', 150, array['Lire correctement « ps aux » et un arbre PID-PPID', 'Relier processus, ports et unités systemd', 'Comprendre un horaire cron et sa prochaine exécution', 'Repérer les minuteurs dont l’état n’est pas sain']::text[], array['Dans « ps aux », le RSS est en kilo-octets et la commande commence après la colonne TIME.', 'Le fichier d’arbre sert uniquement à retrouver les relations de parenté entre PID.', 'Un service à l’écoute se recoupe avec « ss -tulpn » grâce au nom de processus ou au PID.', 'Pour cron, lis séparément les cinq champs de temps avant la commande.']::text[], '{}'::text[], 620, '776b1633-dd76-67f4-532f-87063a481f11', 'logs', 'Le mercredi 8 avril 2026, la supervision signale une charge anormale sur « srv-web01 ». Ousmane Diallo exporte la liste des processus, un arbre PID-PPID, les services systemd, les ports à l’écoute, les tâches planifiées, les minuteurs et le contenu d’une unité suspecte. Ton rôle est de relier toutes ces pièces pour retrouver le processus le plus gourmand, le service inhabituel, la tâche planifiée douteuse et les minuteurs qui montrent un problème durable.', array['Tu n’analyses que des exports statiques fournis par le labo.', 'Aucune commande système réelle n’est nécessaire pour résoudre les tâches.']::text[], array['Visionneuse du site', 'Git Bash pour awk, sort et cut', 'PowerShell 5.1 pour les variantes Windows']::text[], false, false, 50),
  ('b3069c16-c0fe-fe17-c7df-6ea5518c2368', 'tp-linux-reseau-ssh', 'TP 4 : réseau, SSH et pare-feu', 'Tu relies la configuration réseau, la politique SSH, le journal d’authentification et les règles UFW pour décider ce qui est réellement exposé sur srv-web01.', 'linux', 'intermediaire', 160, array['Relire une configuration réseau Linux et retrouver passerelle, interface et préfixe', 'Appliquer correctement la règle « première valeur obtenue » dans sshd_config', 'Distinguer bruit normal, échecs de mot de passe et succès significatif dans auth.log', 'Décider le verdict d’un paquet en lisant les règles UFW dans le bon ordre', 'Repérer une clé SSH faible ou mal documentée dans un relevé d’autorisations']::text[], array['La valeur globale d’une option SSH ne se lit pas toujours sur la dernière ligne visible.', 'Pour les échecs de mot de passe, groupe d’abord par adresse IP puis seulement par nom de compte.', 'Le relevé de clés te donne à la fois des restrictions d’origine, un type, une taille et une empreinte.']::text[], '{}'::text[], 630, '776b1633-dd76-67f4-532f-87063a481f11', 'logs', 'Le jeudi 9 avril 2026, Ousmane Diallo prépare un durcissement de l’accès distant à srv-web01. Il a exporté les informations réseau, la configuration SSH, un extrait d’auth.log de la nuit, les règles UFW et un relevé des clés autorisées. Dans le fichier SSH, les contenus sont présentés l’un après l’autre : le fichier principal, puis les fragments du dossier .d ; ce n’est pas l’ordre dans lequel sshd les lit réellement. Tu dois reconstituer ce qui est déjà correct, ce qui reste trop large et ce qu’un attaquant a réussi à faire. Le but n’est pas de mémoriser des options par cœur, mais de croiser plusieurs fichiers pour retrouver l’ordre réel des décisions.', array['Tu travailles uniquement sur les exports fictifs du labo, sans ouvrir de session SSH réelle.', 'Les heures du journal sont en UTC et les règles UFW se lisent dans l’ordre affiché.']::text[], array['Visionneuse du site pour rechercher une directive ou une adresse IP', 'Git Bash avec grep, awk, sort et uniq si tu veux filtrer rapidement', 'Windows PowerShell 5.1 avec Get-Content, Select-String et Group-Object']::text[], false, false, 50),
  ('33390f57-d755-f342-9e56-4b3b7c83858b', 'tp-linux-maj-sauvegardes', 'TP 5 : mises à jour, disques et sauvegardes', 'Tu fais l’état d’un serveur de fichiers avant audit en croisant les mises à jour en attente, la pression sur les disques, fstab, les journaux de sauvegarde, les instantanés et un script restic.', 'linux', 'intermediaire', 150, array['Compter correctement les mises à jour et distinguer les correctifs de sécurité', 'Lire la pression sur les disques en blocs et en inodes sans les confondre', 'Appliquer une règle de durcissement simple aux options de montage', 'Mesurer la fraîcheur et la fiabilité réelles des sauvegardes', 'Relire un script de sauvegarde pour trouver une ligne techniquement risquée']::text[], array['Dans apt, seules les lignes de paquets comptent, pas la ligne « Listing... » ni os-release.', 'Le système de fichiers le plus plein en blocs n’est pas forcément celui qui manque d’inodes.', 'La politique de rétention est donnée telle quelle : ne rajoute pas de règle quotidienne ou mensuelle non écrite.']::text[], '{}'::text[], 640, '776b1633-dd76-67f4-532f-87063a481f11', 'logs', 'Le lundi 13 avril 2026, Ousmane Diallo prépare l’audit annuel de srv-fichiers01. Il a exporté la liste des paquets à mettre à jour, l’état des systèmes de fichiers, le contenu de fstab, trente nuits de journaux de sauvegarde, la liste des instantanés restic et le script de sauvegarde nocturne. Tu dois produire des constats utiles, pas seulement recopier des lignes. La difficulté principale consiste à séparer ce qui relève des blocs disque, des inodes, de la rétention et des risques de configuration.', array['Tu interprètes uniquement les exports fournis, sans lancer de mise à jour ni de vraie sauvegarde.', 'La date de référence pour les calculs d’ancienneté est le 13 avril 2026 et toutes les heures sont en UTC.']::text[], array['Visionneuse du site pour repérer rapidement un paquet ou une date', 'Git Bash avec grep pour filtrer les lignes utiles', 'Windows PowerShell 5.1 avec Select-String et Import-Csv si tu préfères ce format']::text[], false, false, 45),
  ('20c8d605-dbe8-7f91-ae87-eb52fb165eba', 'tp-linux-scripts', 'TP 6 : lire, tester et corriger des scripts shell', 'Tu exécutes réellement quatre petits scripts bash du labo, puis tu relies leurs sorties à des défauts classiques de robustesse comme les variables non protégées, les suppressions trop larges et l’usage de eval.', 'linux', 'intermediaire', 150, array['Exécuter un script simple et comparer sa sortie à ce que font réellement grep, awk et uniq', 'Repérer une variable de chemin non protégée et comprendre l’effet d’un espace ou d’une valeur vide', 'Lire un script d’inventaire qui combine règle métier et résumé final', 'Reconnaître le risque d’une commande construite depuis une entrée utilisateur']::text[], array['Pour un script bash, commence toujours par la syntaxe, puis relis chaque variable avant l’exécution.', 'Une variable non protégée devient particulièrement dangereuse dès qu’un chemin contient un espace.', 'Quand un script affiche un résumé final, n’oublie pas de regarder aussi cette dernière ligne.', 'Le fichier des sorties candidates aide à reconnaître un bloc, mais ne remplace pas la lecture réelle du script.']::text[], '{}'::text[], 650, '776b1633-dd76-67f4-532f-87063a481f11', 'logs', 'Le mardi 14 avril 2026, Cheikh Fall a préparé quatre petits scripts pour automatiser quelques contrôles. Ousmane Diallo veut les relire avant de les réutiliser. Les scripts comptent des échecs de connexion, nettoient un dossier de test dans un répertoire temporaire, signalent des comptes non conformes et construisent une commande d’archivage à partir d’un argument. Tu dois donc à la fois prédire le résultat obtenu sur les données fournies et repérer les défauts de sécurité ou de robustesse qui apparaissent dans le code.', array['Les scripts opèrent uniquement sur les fichiers du labo ou sur un dossier temporaire qu’ils créent eux-mêmes.', 'Le but est de comprendre et corriger, pas de lancer des scripts sur un vrai système de production.']::text[], array['Git Bash pour exécuter les scripts bash du labo tels quels', 'Windows PowerShell 5.1 pour lire les fichiers et lancer bash.exe si besoin', 'La visionneuse du site pour relire rapidement une ligne fautive ou un bloc de sortie attendu']::text[], false, false, 45),
  ('09c25ce8-74cc-4a83-fd21-f7be06616c16', 'incident-serveur-linux', 'Incident : un serveur web Linux compromis', 'Tu reconstitues une intrusion web puis SSH sur srv-web01, recoupes des exports bruyants et choisis un confinement qui préserve les preuves.', 'linux', 'avance', 240, array['Relier un point d’entrée web à une suite d’actions système', 'Lire auth.log, le journal nginx, un historique shell, ps et ss', 'Recouper comptes, cron, fichiers modifiés et empreintes pour confirmer la persistance', 'Choisir un confinement initial qui coupe l’attaque sans détruire les traces']::text[], array['Toutes les adresses publiques visibles dans les fichiers ne jouent pas le même rôle dans l’incident.', 'Le shell web apparaît côté nginx avant la connexion SSH réussie.', 'La persistance laisse des traces dans plusieurs familles de preuves, pas dans un seul fichier.', 'Un fichier ajouté et un fichier existant dont l’empreinte change ne répondent pas à la même question.']::text[], '{}'::text[], 660, '776b1633-dd76-67f4-532f-87063a481f11', 'logs', 'Le mardi 21 avril 2026 à 14:30 UTC, la supervision de la Mutuelle Alizé signale une hausse de charge sur srv-web01 et des connexions sortantes qui ne ressemblent pas au trafic habituel du site. Ousmane Diallo a exporté les traces avant toute action destructive. Tu dois reconstituer l’ordre de l’intrusion, comprendre comment un point d’entrée web mène à une session SSH, retrouver la persistance laissée sur la machine et proposer le premier geste de confinement. Les journaux couvrent environ trente heures et mêlent activité légitime, bruit réseau et séquence malveillante. Chaque réponse doit être justifiée par les fichiers fournis et, pour les tâches difficiles, par au moins deux preuves concordantes.', array['Tu travailles uniquement sur des exports fictifs et tu ne touches à aucun vrai serveur.', 'Ne télécharge ni n’exécute aucun fichier vu dans les traces et ne te connecte à aucune adresse observée dans les journaux.']::text[], array['Visionneuse de journaux CyberPingo pour rechercher dans les exports', 'Git Bash, WSL ou Termux si tu veux filtrer des lignes avec grep', 'Windows PowerShell 5.1 si tu préfères Select-String sur ton poste']::text[], false, true, 70),
  ('daa996d6-babf-81f5-21f8-955cb7d50c09', 'projet-audit-linux', 'Projet final : auditer un serveur Linux et rédiger le rapport', 'Tu notes toi-même 24 contrôles à partir des preuves, calcules les scores puis priorises les actions selon le risque et l’effort.', 'linux', 'intermediaire', 280, array['Déduire un statut de contrôle à partir d’un critère objectif et des preuves techniques', 'Calculer un score pondéré de domaine puis un score global', 'Prioriser les actions à partir des seuls contrôles jugés partiels ou non conformes', 'Transformer des exports bruts en synthèse d’audit défendable']::text[], array['Lis toujours le critère du contrôle avant d’ouvrir les preuves, sinon tu risques de compter la mauvaise chose.', 'Le registre de risques ne sert qu’après avoir repéré les contrôles partiels ou non conformes.', 'Les preuves d’accès couvrent les comptes, sudo, SSH, le pare-feu et les ports ; les preuves de services couvrent aussi les sauvegardes et MariaDB.', 'Le niveau de maturité se déduit du score global entier et des bornes écrites dans la grille.']::text[], '{}'::text[], 670, '776b1633-dd76-67f4-532f-87063a481f11', 'logs', 'Le lundi 27 avril 2026, tu interviens comme auditeur bénévole sur srv-fichiers01 pour la Mutuelle Alizé. Ousmane Diallo t’a remis une grille de 24 contrôles dont la colonne de statut est volontairement vide, ainsi qu’un dossier de preuves en lecture seule. Ton rôle n’est pas de recopier un verdict déjà donné, mais de noter toi-même chaque contrôle à partir des exports système, accès et services. Une fois les statuts déduits, tu recalcules les scores par domaine, le score global, le niveau de maturité et l’ordre des remédiations à lancer. Le rapport final doit rester factuel, chiffré et justifié par les preuves du dossier, sans ajouter de contrôles extérieurs à la grille.', array['Tu t’appuies uniquement sur les fichiers fournis et sur les règles écrites dans la grille.', 'Chaque statut doit être déduit des preuves, sans toucher au serveur et sans inventer un seuil non documenté.']::text[], array['Visionneuse de journaux CyberPingo pour relire les exports', 'Git Bash, WSL ou Termux pour compter, filtrer et trier si tu veux vérifier tes calculs', 'Windows PowerShell 5.1 pour relire les mêmes preuves avec Select-String ou Import-Csv']::text[], false, true, 100)
insert into public.lab_tasks (id, lab_id, position, prompt, hint, answer_format) values
  ('d479459c-4b54-dff3-92b5-0338d45be9c9', '0ed89ec4-11bf-d087-9263-7049be0c2520', 1, 'Dans « lnx-tp1-arborescence.txt », combien d’éléments directs contient le dossier « /srv/partage/communication/site » ?', 'Va à la section du dossier puis compte seulement les lignes de contenu direct avant la ligne vide suivante.', 'Un nombre entier'),
  ('72dd650c-4bed-0ba3-7ae9-53cfaf941a7f', '0ed89ec4-11bf-d087-9263-7049be0c2520', 2, 'Dans le dossier « /srv/partage/compta/2026-04 » de « lnx-tp1-arborescence.txt », quel fichier est le plus volumineux ?', 'Reste dans une seule section du listing et compare uniquement la colonne de taille en octets.', 'Nom exact du fichier'),
  ('f354a912-e9ad-43c5-40c8-17b2dd0c80f7', '0ed89ec4-11bf-d087-9263-7049be0c2520', 3, 'Quelle est la somme totale des tailles, en octets, de tous les fichiers PDF présents dans « /srv/partage/adhesions/contrats » ?', 'Filtre les lignes du dossier demandé sur l’extension « .pdf », puis additionne les tailles indiquées.', 'Un nombre entier d’octets'),
  ('beaea4d8-bbbf-bfe2-0410-efd17f10aef3', '0ed89ec4-11bf-d087-9263-7049be0c2520', 4, 'Dans « /etc/alize/conf.d », quel est le fichier le plus récemment modifié d’après « lnx-tp1-arborescence.txt » ?', 'Compare les horodatages de la section « /etc/alize/conf.d » et garde la date la plus récente.', 'Nom exact du fichier'),
  ('1ca1a066-7b30-b3db-6646-96cf11137f32', '0ed89ec4-11bf-d087-9263-7049be0c2520', 5, 'Combien de fichiers cachés ou dossiers cachés vois-tu directement dans le répertoire personnel « /home/cfall », sans compter « . » ni « .. » ?', 'Ne compte que les noms qui commencent par un point dans la section « /home/cfall » elle-même.', 'Un nombre entier'),
  ('0eadb313-fe46-4142-fc72-f291c1e969d4', '0ed89ec4-11bf-d087-9263-7049be0c2520', 6, 'Dans « lnx-tp1-historique.txt », si Cheikh démarre dans « /home/cfall », quel est le répertoire courant après la dernière commande « cd » affichée ?', 'Rejoue chaque changement de dossier dans l’ordre et traite correctement « cd - » puis « .config ».', 'Chemin absolu'),
  ('771d6ec9-55cd-81b6-b566-fc38afdd2f50', '0ed89ec4-11bf-d087-9263-7049be0c2520', 7, 'Dans « lnx-tp1-historique.txt », Cheikh tape « cat ../contrats/contrat-2026-04-07.pdf » alors qu’il se trouve déjà dans un sous-dossier de « /srv/partage/adhesions ». Quel est le chemin absolu du fichier qu’il ouvre ?', 'Retrouve d’abord le répertoire courant au moment de cette commande, puis résous le chemin relatif sans sauter d’étape.', 'Chemin absolu'),
  ('5332ec6f-dfac-9efc-b142-25248c6d2b07', '0ed89ec4-11bf-d087-9263-7049be0c2520', 8, 'Dans « lnx-tp1-acces.log », quelle adresse IP a envoyé le plus de requêtes sur la journée ?', 'Compte les lignes par IP source puis garde le total le plus élevé, sans mélanger les codes HTTP.', 'Adresse IPv4'),
  ('2203c1ad-2d9e-5f70-72c3-56d0a37bf2ce', '0ed89ec4-11bf-d087-9263-7049be0c2520', 9, 'Dans « lnx-tp1-acces.log », combien de requêtes ont répondu en code HTTP 404 ?', 'Isole uniquement les lignes dont le code de réponse vaut 404 puis compte-les toutes.', 'Un nombre entier'),
  ('7f83512e-9fb6-71ae-1443-3123eb89d820', '0ed89ec4-11bf-d087-9263-7049be0c2520', 10, 'Parmi les réponses 404 de « lnx-tp1-acces.log », quel chemin a été demandé le plus souvent ?', 'Après avoir filtré les 404, groupe les chemins demandés et trie-les par fréquence décroissante.', 'Chemin web exact'),
  ('860c541d-6b7e-4164-67e6-e4b8f6f08045', '0ed89ec4-11bf-d087-9263-7049be0c2520', 11, 'Dans « lnx-tp1-acces.log », combien de requêtes utilisent la méthode HTTP POST ?', 'Lis la méthode au début de la requête entre guillemets, puis compte uniquement les POST.', 'Un nombre entier'),
  ('8f91ca64-0d02-a1cd-c306-e8a09fcd007b', '0ed89ec4-11bf-d087-9263-7049be0c2520', 12, 'Combien d’adresses IP distinctes vois-tu dans « lnx-tp1-acces.log » ?', 'Ne compte qu’une fois chaque IP source, même si elle apparaît sur plusieurs lignes.', 'Un nombre entier'),
  ('08a25382-511b-754d-2f60-ca4c3c2444bf', '0ed89ec4-11bf-d087-9263-7049be0c2520', 13, 'Dans « lnx-tp1-adherents.csv », combien d’adhérents appartiennent à la ville « Lagune-Est » ?', 'Le séparateur est « ; ». Filtre la troisième colonne sur la ville demandée avant de compter.', 'Un nombre entier'),
  ('cb32c601-eecc-553b-8bf0-e79d324bc6be', '0ed89ec4-11bf-d087-9263-7049be0c2520', 14, 'Dans « lnx-tp1-adherents.csv », quelle formule d’adhésion apparaît le plus souvent, sans égalité ?', 'Regroupe la quatrième colonne par valeur, puis trie les totaux pour repérer le seul maximum.', 'Nom exact de la formule'),
  ('9576f637-2a89-9cc8-d8d1-0329afca3a3b', '0ed89ec4-11bf-d087-9263-7049be0c2520', 15, 'Dans « lnx-tp1-acces.log », combien d’octets ont été envoyés au total pour les réponses 200 du chemin « /membres/tableau-de-bord.php » ?', 'Filtre en même temps sur le chemin demandé et sur le code 200, puis additionne la colonne de taille.', 'Un nombre entier d’octets'),
  ('aed28fbe-7254-98f5-0874-b7582b8809e4', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 1, 'Dans « lnx-tp2-passwd.txt », quel compte possède l’UID 0 en plus de « root » ?', 'Filtre les lignes dont le troisième champ vaut 0, puis ignore « root ».', 'Nom de compte en minuscules'),
  ('786792a7-d70d-3e98-4332-152bcb98a265', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 2, 'Quel compte de service, dont le nom commence par « svc- », dispose d’un shell interactif alors qu’il devrait rester non connecté ?', 'Passe en revue les comptes « svc- », puis compare leur shell avec ceux en « nologin ».', 'Nom de compte en minuscules'),
  ('c56ddfe8-1ce0-63e5-db83-459ac1d9dd5d', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 3, 'Dans « lnx-tp2-shadow.txt », quel compte a un champ de mot de passe complètement vide ?', 'Dans shadow, le champ sensible est le deuxième, entre le premier et le troisième deux-points.', 'Nom de compte en minuscules'),
  ('a29758bd-0435-7a1e-ed1a-fd85661ea417', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 4, 'Pour le compte « nkamga » dans « lnx-tp2-shadow.txt », quel algorithme est indiqué par le préfixe de l’empreinte ? Réponds par une lettre. a) sha512-crypt b) yescrypt c) md5-crypt d) sha256-crypt', 'Le guide donne la table des préfixes : compare seulement le début de la chaîne de hachage.', 'Une seule lettre'),
  ('20a346c5-03b9-d8f7-6827-c1a7321d2ea4', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 5, 'Combien de comptes apparaissent comme verrouillés dans « lnx-tp2-shadow.txt » ?', 'Compte les lignes dont le deuxième champ commence par « ! » ou par « * ».', 'Un nombre entier'),
  ('c447653d-1ff6-bc59-eb36-95ba3dd8cad5', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 6, 'Pour le compte « straore », quelle est la date du dernier changement de mot de passe au format AAAA-MM-JJ ?', 'Le troisième champ de shadow est un nombre de jours depuis 1970-01-01 ; convertis-le en date UTC.', 'AAAA-MM-JJ'),
  ('3b0e91b5-86e3-f644-2b81-3acb2bd3a755', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 7, 'Combien de jours se sont écoulés entre ce changement et le mardi 7 avril 2026 ?', 'Utilise la date trouvée à la tâche précédente puis calcule l’écart en jours calendaires jusqu’au 2026-04-07.', 'Un nombre entier de jours'),
  ('f219de04-fe70-9b6b-a578-e7affe3fe4d7', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 8, 'Combien de membres le groupe « sudo » contient-il dans « lnx-tp2-group.txt » ?', 'Lis la liste après le quatrième deux-points puis compte les identifiants séparés par des virgules.', 'Un nombre entier'),
  ('40db2ba8-651e-64e1-d890-4cd740f7607a', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 9, 'Quel fichier sudoers concaténé contient la règle la plus dangereuse, celle qui accorde « NOPASSWD: ALL » ?', 'Cherche le périmètre le plus large possible et repère dans quel bloc commenté du fichier il apparaît.', 'Chemin ou identifiant du fichier sudoers.d'),
  ('241138d1-68c0-8cf3-d6e9-3d81ff4f5b87', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 10, 'Dans « lnx-tp2-permissions.txt », quel est le mode octal du fichier « /var/backups/export-adhesions.sh » ?', 'Transforme chaque triplet symbolique en somme 4, 2, 1 pour lecture, écriture et exécution.', 'Mode octal sur 3 chiffres'),
  ('9b86e158-548a-1efb-6871-93f131b91034', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 11, 'Quel est le premier fichier de la liste des permissions qui est modifiable par tous les utilisateurs ?', 'Cherche la première ligne de fichier dont le mode donne l’écriture au propriétaire, au groupe et aux autres.', 'Nom exact du fichier'),
  ('52097b5a-5685-04b0-cdd4-8bbb518507c4', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 12, 'Dans « lnx-tp2-suid.txt », combien de binaires SUID n’appartiennent pas à la liste de référence donnée dans le guide ?', 'Compare chaque chemin de la colonne finale à la liste normale fournie par le guide, puis compte seulement les écarts.', 'Un nombre entier'),
  ('4193bae5-b95f-b8f3-0d23-39530417663b', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 13, 'Quel compte nominatif à shell valide n’a jamais ouvert de session d’après « lnx-tp2-derniere-connexion.txt » ?', 'Croise lastlog avec passwd : cherche « Never logged in », écarte les comptes de service puis vérifie que le shell n’est pas « nologin ».', 'Nom de compte en minuscules'),
  ('65b5ee0d-8712-f6c5-bcc6-644b419f74b7', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 14, 'Combien de comptes de personnes (UID de 1000 ou plus et shell de connexion valide, c’est-à-dire autre que « nologin ») ne se sont pas connectés depuis plus de 90 jours au mardi 7 avril 2026 ?', 'Garde les comptes dont l’UID est de 1000 ou plus et dont le shell n’est pas « nologin », puis compare leur dernière connexion à la date de référence ; considère « Never logged in » comme plus ancien que 90 jours.', 'Un nombre entier'),
  ('0185d4fc-b367-27d8-3dc9-c2df23148a56', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 1, 'Dans « lnx-tp3-ps.txt », quel PID consomme le plus de CPU ?', 'Trie mentalement ou avec un outil sur la colonne %CPU et garde la plus grande valeur.', 'Un PID numérique'),
  ('1d456a28-acfc-a697-fc4b-52a938bdf320', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 2, 'Quel utilisateur lance ce processus très consommateur ? Réponds par une lettre. a) www-data b) mysql c) root d) odiallo', 'Lis la première colonne de la même ligne que le PID trouvé à la tâche précédente.', 'Une seule lettre'),
  ('436944f5-19c8-74d5-51e8-cb165143bb44', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 3, 'Quel est le chemin exact de l’exécutable ou de la commande lancé par ce processus très consommateur ?', 'Sur la ligne ciblée, lis la colonne COMMAND sans la tronquer.', 'Chemin ou commande exacte'),
  ('7d4032d9-2717-655f-eb4d-cb53e9202049', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 4, 'Dans « lnx-tp3-ps-arbre.txt », quel est le PID du parent direct de ce processus gourmand ?', 'Cherche la ligne du PID concerné, puis relève sa colonne PPID.', 'Un PID numérique'),
  ('64c9cf9c-80b7-991c-5d05-0c69d3863919', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 5, 'Combien de processus appartiennent à l’utilisateur « www-data » dans « lnx-tp3-ps.txt » ?', 'Compte uniquement les lignes dont la première colonne vaut exactement « www-data ».', 'Un nombre entier'),
  ('e9bf0f51-2212-1cb1-c7ab-1ee75ccb1230', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 6, 'Quelle est la mémoire résidente totale de « www-data », en Mio arrondis à l’entier le plus proche ?', 'Additionne tous les RSS de « www-data », puis convertis de kilo-octets vers Mio en divisant par 1024 avant d’arrondir.', 'Un nombre entier de Mio'),
  ('0958f146-60a1-3972-b754-7ed5991fc6b3', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 7, 'Quel service écoute sur le port 3306 d’après « lnx-tp3-ports.txt » et « lnx-tp3-services.txt » ?', 'Trouve d’abord le nom de processus dans « ss -tulpn », puis rapproche-le du nom d’unité systemd cohérent.', 'Nom d’unité systemd'),
  ('e319f59b-47db-1325-5690-6d676a859a76', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 8, 'Quel numéro de port à l’écoute paraît inattendu sur ce serveur web ?', 'Repère le port associé au service inhabituel et ouvert sur toutes les interfaces.', 'Numéro de port'),
  ('6190c3b8-b4f9-db35-8df4-a124f4e5c3a6', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 9, 'Combien de services sont actuellement en échec dans « lnx-tp3-services.txt » ?', 'Compte les lignes dont les colonnes ACTIVE et SUB indiquent toutes les deux « failed ».', 'Un nombre entier'),
  ('0bde3848-7a57-ffff-1062-86c5ae8c5ec6', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 10, 'Quelle ligne cron s’exécute toutes les cinq minutes dans « lnx-tp3-cron.txt » ? Réponds par le chemin du script appelé.', 'Cherche la ligne dont les cinq premiers champs commencent par « */5 * * * * » puis relève la commande.', 'Chemin absolu du script'),
  ('a3177086-3a93-ca91-36ae-a3bf50a2ac3a', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 11, 'Si l’on se place au mercredi 8 avril 2026 à 03:05 UTC, à quelle heure la ligne « */20 2-4 * * 1-5 root /usr/local/bin/collecte-charge.sh » se lancera-t-elle ensuite ?', 'Lis le pas « */20 », la plage d’heures « 2-4 » et les jours ouvrés, puis cherche la prochaine occurrence après 03:05.', 'HH:MM'),
  ('cb0ceeb0-d92e-2010-0703-1c0f3509ed15', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 12, 'Quelle tâche planifiée exécutée avec les privilèges du superutilisateur appelle un script que n’importe quel utilisateur peut modifier (droit d’écriture pour « autres ») ? Réponds par une lettre. a) « /usr/local/bin/verifier-sessions.sh » b) « /usr/local/bin/purger-miniatures.sh » c) « /usr/local/bin/rotation-longue.sh » d) « /usr/local/bin/rapport-cache.sh »', 'Pour chaque proposition, retrouve qui lance la tâche, puis lis les droits du script rappelés dans l’export.', 'Une seule lettre'),
  ('8582dde9-fed8-2d41-695f-b3a27652ea9a', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 13, 'Quel est le nom de l’unité systemd qui redémarre toujours et dont « ExecStart » pointe vers un chemin inhabituel ?', 'Lis « lnx-tp3-unite.service » puis retrouve la même unité dans la liste des services.', 'Nom d’unité systemd'),
  ('d0f93351-5f58-c91b-457f-1e5257ce7539', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 14, 'Combien de minuteurs de « lnx-tp3-minuteurs.txt » n’ont encore jamais tourné, c’est-à-dire ont la colonne LAST à « n/a » ?', 'Lis uniquement la colonne LAST et compte les lignes où cette colonne vaut exactement « n/a ».', 'Un nombre entier'),
  ('42026516-94c4-1c14-3a15-e790bd882870', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 15, 'À partir du mercredi 8 avril 2026 à 03:00 UTC, quelle est la prochaine date d’exécution de la ligne cron « 0 3 15 * 5 root /usr/local/bin/revue-hebdo.sh » ?', 'Rappelle-toi la règle de cron : si le jour du mois et le jour de la semaine sont tous les deux restreints, l’exécution a lieu quand l’un OU l’autre correspond.', 'AAAA-MM-JJ'),
  ('888821f4-19aa-e59d-e4a8-75f36dc3bc49', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 1, 'Dans lnx-tp4-reseau.txt, quelle est l’adresse de la passerelle par défaut de srv-web01 ?', 'Lis la ligne qui commence par « default via » dans la partie des routes.', 'Adresse IPv4'),
  ('24e5b7a6-c36e-f294-98aa-16418c446899', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 2, 'Dans lnx-tp4-reseau.txt, quelle interface porte l’adresse du serveur sur le réseau interne 10.20.0.0/24 ?', 'Croise la section « ip -br a » avec la route du réseau interne pour retrouver le bon nom d’interface.', 'Nom exact d’interface Linux'),
  ('48691d6f-e07c-4131-4c11-a4b0616441e1', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 3, 'Toujours dans lnx-tp4-reseau.txt, quel est le préfixe CIDR du réseau local de srv-web01 ?', 'Le suffixe après la barre oblique de l’adresse du serveur donne directement le préfixe.', 'Un nombre entier, sans la barre oblique'),
  ('1d90b270-3027-58a9-6e5b-2e27a6c618d8', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 4, 'En appliquant la règle « première valeur obtenue = valeur effective » au fichier lnx-tp4-sshd_config.txt, quelle est la valeur effective de PermitRootLogin ?', 'La directive Include apparaît avant le reste du fichier principal : tiens compte de l’ordre réel de lecture.', 'Valeur exacte de la directive, en minuscules'),
  ('95dc1e7c-588b-62a2-3bf6-7f559af36b8a', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 5, 'Dans lnx-tp4-sshd_config.txt, quelle est la valeur effective de PasswordAuthentication pour l’utilisateur cfall ?', 'Commence par la valeur globale, puis vérifie si un bloc Match User s’applique explicitement à ce compte.', 'oui ou non'),
  ('05e684a5-d77d-3402-1526-ff06756a7320', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 6, 'Dans lnx-tp4-auth.log, quelle adresse IP cumule le plus d’échecs de mot de passe ?', 'Filtre d’abord les lignes « Failed password », puis groupe-les par adresse IP source.', 'Adresse IPv4'),
  ('1d7af90f-1605-2d26-50bc-534ec73731d7', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 7, 'Dans lnx-tp4-auth.log, combien de noms d’utilisateurs inexistants différents ont été tentés au moins une fois ?', 'Ne compte que les lignes « invalid user » et retiens les noms distincts, pas le nombre total d’échecs.', 'Un nombre entier'),
  ('c92d8013-0048-6d34-0ae0-59c07297ad73', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 8, 'Dans lnx-tp4-auth.log, à quelle heure UTC apparaît le premier succès par mot de passe ?', 'Cherche « Accepted password », puis garde la première ligne par ordre chronologique.', 'HH:MM:SS'),
  ('532192ec-08b2-f866-46db-b6259afc1592', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 9, 'Toujours dans lnx-tp4-auth.log, quel compte est concerné par ce premier succès par mot de passe ?', 'Lis le nom de compte sur la même ligne que le premier « Accepted password ».', 'Nom de compte Linux, en minuscules'),
  ('ff77006e-dd56-0118-202f-d849958a3fa5', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 10, 'Dans lnx-tp4-auth.log, combien d’échecs précèdent ce premier succès depuis la même adresse IP ?', 'Conserve la même adresse source que la ligne du succès, puis ne compte que les échecs antérieurs.', 'Un nombre entier'),
  ('f4babcd2-6091-9d13-f277-53495bd6aa76', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 11, 'Dans lnx-tp4-ufw.txt, quel numéro de règle UFW ouvre inutilement un port à tout Internet alors que le SSH effectif n’écoute pas dessus ?', 'Croise le port réellement retenu dans la configuration SSH avec les règles UFW autorisant « Anywhere ».', 'Un nombre entier'),
  ('b703eb76-e1b1-2d03-2217-055c50531f0a', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 12, 'Dans lnx-tp4-ufw.txt, pour un paquet TCP entrant depuis 203.0.113.90 vers le port SSH effectif du serveur, quel numéro de règle UFW décide du sort du paquet ?', 'Retrouve d’abord le port SSH effectif dans la configuration, puis lis les règles UFW dans l’ordre numérique jusqu’à la première qui correspond.', 'Un nombre entier'),
  ('2248cc21-785a-56d3-99c3-2de0c8815d90', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 13, 'Dans lnx-tp4-cles.txt, combien de clés RSA autorisées ont une taille strictement inférieure à 3072 bits ?', 'Repère les lignes RSA, puis compare leur taille à la borne générale donnée par le guide.', 'Un nombre entier'),
  ('293cb2f2-6f4a-2a7c-c259-f4c2ff18d976', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 14, 'Dans lnx-tp4-cles.txt, combien de clés autorisées n’ont aucune restriction « from= » ?', 'Relis seulement la partie des options au début de chaque ligne, sans te laisser distraire par le type ou l’empreinte.', 'Un nombre entier'),
  ('f58ec194-246a-3b3a-2acb-05454aa5df01', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 15, 'Toujours dans lnx-tp4-sshd_config.txt, quel port SSH est réellement à l’écoute après application de l’ordre de lecture effectif ?', 'Cherche toutes les directives Port, mais retiens la première réellement obtenue.', 'Numéro de port'),
  ('1c9e02f1-cfb7-dfc0-bcaa-7c2c8264971b', '33390f57-d755-f342-9e56-4b3b7c83858b', 1, 'Dans lnx-tp5-maj.txt, combien de paquets sont en attente de mise à jour ?', 'Compte uniquement les lignes de paquets listées dans la section apt list --upgradable.', 'Un nombre entier'),
  ('e492ad1f-6916-a4f9-d211-f2e140ce5a16', '33390f57-d755-f342-9e56-4b3b7c83858b', 2, 'Toujours dans lnx-tp5-maj.txt, combien de mises à jour proviennent explicitement du canal de sécurité ?', 'Cherche le suffixe « -security » dans la provenance de chaque paquet.', 'Un nombre entier'),
  ('8172f91c-2b45-409a-3b2f-8239bcace133', '33390f57-d755-f342-9e56-4b3b7c83858b', 3, 'Dans lnx-tp5-maj.txt, quelle version d’openssh-server est proposée par apt ?', 'Lis la ligne du paquet openssh-server et retiens la version située avant l’architecture.', 'Version complète du paquet'),
  ('ee3b3203-3e50-2d5c-8d32-942753f9137a', '33390f57-d755-f342-9e56-4b3b7c83858b', 4, 'Dans lnx-tp5-disques.txt, quel point de montage dépasse 90 % d’occupation en blocs et est donc le plus critique de ce point de vue ?', 'Lis la section df -h et compare uniquement la colonne Use%.', 'Chemin de point de montage absolu'),
  ('8064d60a-c37c-2b0c-59a6-894d88ffe7fd', '33390f57-d755-f342-9e56-4b3b7c83858b', 5, 'Dans lnx-tp5-disques.txt, quel point de montage est presque à court d’inodes ?', 'Cette fois, utilise uniquement la section df -i et compare IUse%.', 'Chemin de point de montage absolu'),
  ('4bbf8a25-7fc1-f367-060c-53f02e1680a3', '33390f57-d755-f342-9e56-4b3b7c83858b', 6, 'En croisant lnx-tp5-disques.txt et lnx-tp5-fstab.txt, quel point de montage temporaire présente un risque parce qu’il lui manque l’option noexec selon la règle du guide ?', 'Cherche le point de montage temporaire cité dans le guide, puis relis ses options dans findmnt et fstab.', 'Chemin de point de montage absolu'),
  ('b067c785-352d-ad8f-c14b-1397034a1a83', '33390f57-d755-f342-9e56-4b3b7c83858b', 7, 'Dans lnx-tp5-disques.txt, quelle est la somme de la colonne Avail de toutes les lignes de la section df -h (tmpfs compris), exprimée en gibioctets (le « G » de df -h) et arrondie à un chiffre après la virgule ?', 'Additionne la colonne Avail de chaque ligne de la section df -h, sans utiliser les autres sections du fichier.', 'Un nombre décimal avec un chiffre après la virgule'),
  ('be2b40bc-b63c-f8ed-d1f9-f1609d364bf2', '33390f57-d755-f342-9e56-4b3b7c83858b', 8, 'Dans lnx-tp5-sauvegarde.log, combien de nuits sur 30 se terminent par un statut SUCCESS ?', 'Ne compte que les lignes dont le statut est exactement SUCCESS.', 'Un nombre entier'),
  ('31ca1a21-2d1f-20ce-429b-9143ac9427a5', '33390f57-d755-f342-9e56-4b3b7c83858b', 9, 'Toujours dans lnx-tp5-sauvegarde.log, quelle est la plus longue série d’échecs consécutifs ?', 'Lis le journal dans l’ordre des dates et repère la plus longue suite continue de lignes FAIL.', 'Un nombre entier'),
  ('bad3d440-b536-8e4d-d993-a2a7348bddfe', '33390f57-d755-f342-9e56-4b3b7c83858b', 10, 'Dans lnx-tp5-sauvegarde.log, quelle est la date de la dernière sauvegarde réussie avant le 13 avril 2026 ?', 'Pars de la fin du fichier et remonte jusqu’à la première ligne SUCCESS.', 'AAAA-MM-JJ'),
  ('5236d36d-f707-8148-55ce-c8e01bcc4d43', '33390f57-d755-f342-9e56-4b3b7c83858b', 11, 'Toujours à partir de lnx-tp5-sauvegarde.log, quelle est l’ancienneté de cette dernière sauvegarde réussie au 13 avril 2026 ?', 'Prends la date de la dernière réussite puis calcule la différence en jours calendaires jusqu’au 13 avril 2026.', 'Un nombre entier de jours'),
  ('5e8b3431-2b26-5e29-6e82-e2614dad7423', '33390f57-d755-f342-9e56-4b3b7c83858b', 12, 'En appliquant la politique donnée dans le guide au fichier lnx-tp5-instantanes.txt, et en sachant que dans ce labo chaque instantané porte une seule étiquette qui dit à quelle règle de conservation il appartient, combien d’instantanés sont conservés avec la règle « garder au plus 7 daily, 4 weekly et 2 monthly » ?', 'Appuie-toi sur la colonne des tags et sur le plafond de chaque catégorie donné dans le guide.', 'Un nombre entier'),
  ('76c1093d-4b05-7054-6cfd-9cdf5d0a45dd', '33390f57-d755-f342-9e56-4b3b7c83858b', 13, 'Dans lnx-tp5-instantanes.txt, quel identifiant d’instantané faut-il restaurer pour retrouver l’état de la veille d’un incident survenu le 11 avril 2026 à 15:00 UTC ?', 'Cherche l’instantané le plus récent dont l’horodatage reste antérieur à la date et à l’heure données.', 'Identifiant court de snapshot restic'),
  ('f6d23d1b-918d-2a46-99e2-22ba88c285b5', '33390f57-d755-f342-9e56-4b3b7c83858b', 14, 'Dans lnx-tp5-sauvegarde.sh, quelle ligne est défectueuse parce qu’elle envoie un chemin potentiellement contenant des espaces sans le protéger correctement ?', 'Cherche la commande restic qui reprend la variable du chemin source telle quelle.', 'Numéro de ligne'),
  ('8d059359-a72b-c279-f19d-d032f259c01b', '33390f57-d755-f342-9e56-4b3b7c83858b', 15, 'D’après les informations de lnx-tp5-sauvegarde.log, lnx-tp5-instantanes.txt, lnx-tp5-copies.txt et lnx-tp5-sauvegarde.sh, la règle 3-2-1 est-elle respectée ?', 'Applique la règle de validité d’une copie du guide à la date d’audit du 13 avril 2026, puis vérifie chaque condition de la règle 3-2-1 sur des preuves positives.', 'oui ou non'),
  ('b5e85bbe-3b2a-ec3a-c502-988268f670ab', '33390f57-d755-f342-9e56-4b3b7c83858b', 16, 'Parmi les trois critères de la règle 3-2-1, lequel n’est pas satisfait d’après lnx-tp5-copies.txt, une fois la règle de validité d’une copie appliquée ? a) avoir trois copies b) avoir deux supports différents c) avoir une copie hors site d) aucun, les trois critères sont satisfaits', 'Compte d’abord les copies valides à la date d’audit du 13 avril 2026, puis leurs supports, puis cherche une copie hors site valide.', 'Une seule lettre'),
  ('1cee3ec5-7360-8de8-57df-2a0cc2e0dcfa', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 1, 'Quel bloc numéroté de lnx-tp6-attendus.txt correspond exactement à la sortie de lnx-tp6-compter.sh lorsqu’il lit lnx-tp6-journal.log ?', 'Compare le format du résumé et l’ordre réel des trois adresses affichées par le script.', 'Un nombre entier de bloc'),
  ('124351c1-979c-bea1-8e90-ebec08ee7927', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 2, 'Combien de lignes d’échec le script lnx-tp6-compter.sh compte-t-il réellement dans lnx-tp6-journal.log ?', 'Relis le motif de recherche du script, puis confronte-le au journal ou à son exécution réelle.', 'Un nombre entier'),
  ('b9829dd9-2fdb-9a72-50a1-271541c9a627', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 3, 'Dans la sortie de lnx-tp6-compter.sh, quelle adresse IP arrive en tête du classement ?', 'Observe le premier élément du classement réellement produit, sans te limiter au premier paquet du journal.', 'Adresse IPv4'),
  ('f584b7fa-45cb-97d2-be3c-1b76ce5d34c0', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 4, 'Combien de lignes de sortie standard produit lnx-tp6-compter.sh lorsqu’il reçoit lnx-tp6-journal.log comme argument ?', 'Regarde la forme complète de la sortie standard, du résumé jusqu’au classement.', 'Un nombre entier'),
  ('c5685e41-7b66-e35a-b4a9-879c86109c53', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 5, 'Quel code de retour renvoie lnx-tp6-compter.sh lorsqu’il est lancé correctement avec lnx-tp6-journal.log ?', 'Un script qui termine sans erreur et sans appel explicite à exit différent de zéro renvoie normalement le code zéro.', 'Un nombre entier'),
  ('35be7210-b85c-fd74-f888-04e3e78b3be9', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 6, 'Lorsqu’on lance lnx-tp6-nettoyer.sh sans argument, combien de fichiers anciens de plus de 30 jours détecte-t-il dans son dossier temporaire de démonstration ?', 'Lis ou exécute le script : il crée quatre fichiers, puis calcule d’abord le nombre de candidats anciens avant toute suppression.', 'Un nombre entier'),
  ('d331ed39-9d20-53e9-bd7b-ba38f5ce3793', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 7, 'Dans lnx-tp6-nettoyer.sh, quelle ligne contient la variable de chemin non protégée la plus dangereuse ?', 'Cherche la ligne de suppression qui réutilise directement la variable du dossier et un joker.', 'Numéro de ligne'),
  ('d0b5d21a-3c5f-529b-649a-ffa91c094f61', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 8, 'Dans lnx-tp6-nettoyer.sh, même si on protège correctement la variable de chemin, quel fichier non ancien serait quand même visé par le joker de suppression ?', 'Compare les fichiers considérés comme anciens avec la portée réelle du motif utilisé dans la ligne rm.', 'Nom exact du fichier'),
  ('a63d06c8-174d-7696-3867-ac71335173cc', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 9, 'Combien de fichiers restent dans le dossier temporaire à la fin de l’exécution de lnx-tp6-nettoyer.sh sans argument ?', 'Le chemin créé par défaut contient un espace : observe l’effet de ce détail sur la commande rm non protégée.', 'Un nombre entier'),
  ('af5aff42-4ca1-ab10-48ee-0870bd47db49', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 10, 'Dans lnx-tp6-comptes.csv, combien de comptes lnx-tp6-inventaire.sh signale-t-il au total comme non conformes lorsqu’on l’exécute sans filtre supplémentaire ?', 'Relis la règle métier du script, puis vérifie quels comptes du CSV y correspondent réellement.', 'Un nombre entier'),
  ('8691e1a0-1f54-b2dc-6951-fa75b521e759', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 11, 'Combien de lignes affiche lnx-tp6-inventaire.sh lorsqu’on lui passe lnx-tp6-comptes.csv et le préfixe « svc- » ?', 'Regarde la sortie complète jusqu’au résumé final, pas seulement les comptes listés avant lui.', 'Un nombre entier'),
  ('49560405-6d1c-f7d1-e3d5-b54881d57b6e', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 12, 'Dans lnx-tp6-sauvegarde.sh, quelle ligne exécute avec eval le texte assemblé à partir de l’entrée utilisateur ?', 'Repère d’abord l’endroit où le script passe d’un simple texte stocké à une exécution réelle par le shell.', 'Numéro de ligne'),
  ('8e2e7600-c565-2cb3-2651-12851ff9b5c0', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 13, 'Quel identifiant ShellCheck correspond au défaut de variable non protégée visible dans lnx-tp6-nettoyer.sh ?', 'Colle le script dans ShellCheck, sur le site officiel, ou relis la leçon sur les scripts fiables.', 'Code ShellCheck, en minuscules'),
  ('21ff6cf5-3f80-21d3-2337-f2ba96e04093', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 14, 'Quelle correction est correcte pour la ligne dangereuse de lnx-tp6-nettoyer.sh ? Réponds par une lettre. a) rm -f $cleanup_dir/* b) rm -f -- "$cleanup_dir"/* c) rm -f "$cleanup_dir*" d) rm -f ''$cleanup_dir''/*', 'Une seule proposition protège correctement la variable tout en laissant le motif s’appliquer au bon dossier.', 'Une seule lettre'),
  ('c0619ac8-4a4d-95fc-f6c7-e26013392221', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 15, 'Quelle option de « set » fait échouer un script au premier code de retour non nul ?', 'Retrouve dans la leçon sur les scripts fiables l’option qui interrompt un script dès qu’une commande simple échoue.', 'Réponse courte, par exemple set -x'),
  ('43d706b0-4b5d-29d1-714d-477f534cb7d8', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 1, 'Dans « lnx-inc-auth.log », quelle adresse IP mène la force brute SSH sans jamais obtenir d’accès ?', 'Repère la source publique qui accumule les échecs d’authentification tout en restant absente des succès.', 'Adresse IPv4'),
  ('ce5d83ba-89fb-c231-ae8c-23f8d8d8cff7', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 2, 'Toujours dans « lnx-inc-auth.log », combien d’échecs SSH sont attribués à cette adresse de force brute ?', 'Une fois la bonne source trouvée, recompte seulement ses lignes d’échec.', 'Nombre entier'),
  ('78f57daf-e5ed-dc60-8de4-05178b3f71de', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 3, 'En lisant « lnx-inc-acces.log », quelle adresse IP publique exploite le téléversement puis appelle le shell web ?', 'Cherche la même source sur un envoi de fichier puis sur plusieurs requêtes qui déclenchent des commandes.', 'Adresse IPv4'),
  ('29713d46-fbbb-f177-0545-27f314a8d453', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 4, 'Dans « lnx-inc-acces.log », à quelle heure UTC apparaît la première requête malveillante vers le shell web ?', 'Ignore le simple téléversement et garde la première requête qui déclenche réellement une commande.', 'Heure UTC au format HH:MM:SS'),
  ('c62fc3f5-e16a-1cd8-9246-4ee1b96bce92', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 5, 'En croisant « lnx-inc-acces.log » et « lnx-inc-fichiers-modifies.txt », quel est le chemin absolu du fichier PHP téléversé par l’attaquant ?', 'Le journal web donne le nom utilisé ensuite, puis la liste des fichiers modifiés donne son emplacement complet sur le disque.', 'Chemin absolu Linux'),
  ('43ed48aa-7fd7-d295-bbe1-a499df2d9997', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 6, 'Dans « lnx-inc-ps.txt », sous quel compte non privilégié tournent les processus de travail (workers) de nginx et du pool php-fpm ?', 'Ignore les processus maîtres lancés par root et relève le compte des processus de travail.', 'Nom de compte en minuscules'),
  ('76f3bd55-6a30-ed8b-8c7f-09823dc200ea', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 7, 'En croisant « lnx-inc-auth.log » et « lnx-inc-historique.txt », quel compte de service est réutilisé pour la connexion SSH réussie de l’attaquant ?', 'Le compte concerné apparaît dans le succès SSH, puis dans l’historique des commandes ouvertes juste après.', 'Nom de compte en minuscules'),
  ('83bc7b22-9cf1-9f6f-37c5-f372a4d86e15', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 8, 'Dans « lnx-inc-auth.log », à quelle heure UTC se produit le premier succès SSH de l’attaquant ?', 'Concentre-toi sur la première authentification réussie associée à l’adresse d’exploitation, pas sur les sessions légitimes du reste de la journée.', 'Heure UTC au format HH:MM:SS'),
  ('8161db28-196f-a4f5-7cef-93d61fc633fc', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 9, 'Toujours dans « lnx-inc-auth.log », depuis quelle adresse l’attaquant obtient-il ce premier accès SSH réussi ?', 'Relis la même ligne de succès que pour la tâche précédente et compare-la au journal web.', 'Adresse IPv4'),
  ('d2d2c3a5-0a2b-63cb-9787-45b4bcb5b28e', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 10, 'En croisant « lnx-inc-auth.log » et « lnx-inc-passwd.txt », quel nom de compte caché l’attaquant ajoute-t-il ensuite ?', 'La création laisse une trace explicite dans auth.log, puis le nouveau compte apparaît dans passwd.', 'Nom de compte en minuscules'),
  ('e42a8f14-e7f1-4903-eeaf-389734476487', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 11, 'En croisant « lnx-inc-cron.txt » et « lnx-inc-historique.txt », quel chemin de script est ajouté pour la persistance cron ?', 'Le cron montre le fichier lancé régulièrement, et l’historique shell montre sa création quelques minutes plus tôt.', 'Chemin absolu Linux'),
  ('8a375f28-7dd5-484f-3473-0b26df43bec6', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 12, 'En croisant « lnx-inc-ps.txt », « lnx-inc-ports.txt » et « lnx-inc-historique.txt », quelle destination complète reçoit la connexion sortante inhabituelle ?', 'Cherche d’abord le processus anormal, puis retrouve la même cible côté réseau et dans la ligne de commande qui l’a lancée.', 'Adresse et port au format ip:port'),
  ('d697cd6d-d6e6-27e1-c24d-b5c8c488452f', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 13, 'Dans « lnx-inc-empreintes.txt », quel fichier du site a une empreinte différente entre le manifeste de référence et l’état actuel ?', 'Compare seulement les chemins présents dans les deux sections, puis cherche celui dont le hash change.', 'Chemin absolu Linux'),
  ('61ee1099-4b2a-5441-c91c-3d93fe89c184', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 14, 'Entre la première requête malveillante de « lnx-inc-acces.log » et la création du compte caché visible dans « lnx-inc-auth.log », combien de minutes s’écoulent-elles ?', 'Relève d’abord les deux horodatages exacts, puis calcule l’écart en minutes entières.', 'Nombre entier de minutes, secondes ignorées'),
  ('8d07bdbe-857b-863b-5cd0-29ae6b12e8b0', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 15, 'Quelle est la première mesure de confinement la plus appropriée ? Réponds par la lettre. a) supprimer le shell web et remettre le site en ligne tout de suite b) isoler la machine du réseau, sans l’éteindre et sans toucher aux journaux c) redémarrer le serveur pour couper les processus de l’attaquant d) changer le mot de passe du compte utilisé et surveiller la suite', 'Choisis l’action qui coupe les communications malveillantes sans effacer ce que l’enquête devra encore relire.', 'Une seule lettre'),
  ('2192a860-968d-8bcd-0ee6-df3962a83c50', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 16, 'Quel ordre d’actions suit une gestion propre de cet incident ? Réponds par la lettre. a) redémarrer le serveur, nettoyer les journaux, puis changer les mots de passe b) prévenir les adhérents, analyser les journaux, puis isoler la machine c) supprimer le compte caché et le shell web, remettre le site en ligne, puis chercher l’origine de l’attaque d) isoler la machine, figer les preuves utiles, puis changer les secrets et remettre en état', 'Cherche la séquence qui commence par casser la capacité de nuisance, puis qui protège l’analyse avant la remédiation.', 'Une seule lettre'),
  ('629d8a96-38b5-a0c8-b622-9ad867dedb57', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 17, 'En réunissant les adresses publiques trouvées aux questions 1, 3, 9 et 12 (sans le port), combien d’adresses IP distinctes obtiens-tu ?', 'Plusieurs questions peuvent désigner la même adresse : compte chaque adresse une seule fois.', 'Nombre entier'),
  ('d0fd2aa2-6bc3-48ac-ea6c-2d7784a86694', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 1, 'Quel est le statut du contrôle AC1 dans « lnx-proj-grille-audit.md » ? Réponds par la lettre c, p ou n.', 'Lis d’abord le critère du contrôle AC1, puis relève la valeur effective correspondante dans les preuves d’accès.', 'Une seule lettre : c, p ou n'),
  ('a8e49eb9-9db7-ef1b-24ec-b2b3c43162af', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 2, 'Quel est le statut du contrôle AC2 dans « lnx-proj-grille-audit.md » ? Réponds par la lettre c, p ou n.', 'Le critère combine la valeur de PasswordAuthentication et le périmètre réel d’accès SSH d’administration.', 'Une seule lettre : c, p ou n'),
  ('8525db84-a2a0-5d6b-f12e-6a04e9ad31b5', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 3, 'Quel est le statut du contrôle AC3 dans « lnx-proj-grille-audit.md » ? Réponds par la lettre c, p ou n.', 'Compte les comptes de service ayant un shell interactif, puis applique la borne écrite dans la grille.', 'Une seule lettre : c, p ou n'),
  ('0c773d7e-8525-fe5a-85ab-bf7faecafcbd', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 4, 'Quel est le statut du contrôle SY1 dans « lnx-proj-grille-audit.md » ? Réponds par la lettre c, p ou n.', 'Compte uniquement les correctifs du canal de sécurité dans la sortie apt, puis applique le seuil du contrôle.', 'Une seule lettre : c, p ou n'),
  ('16d2a36e-da24-20ab-6880-e271148d6472', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 5, 'Quel est le statut du contrôle SY3 dans « lnx-proj-grille-audit.md » ? Réponds par la lettre c, p ou n.', 'Relis les options de montage de /tmp et vérifie combien des trois options exigées sont présentes.', 'Une seule lettre : c, p ou n'),
  ('7bb55702-5800-dde2-f2f5-cfbc641e378a', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 6, 'Quel est le statut du contrôle JO3 dans « lnx-proj-grille-audit.md » ? Réponds par la lettre c, p ou n.', 'Cherche le service auditd dans la liste systemd et compare son état à la règle du contrôle.', 'Une seule lettre : c, p ou n'),
  ('b5b6e97d-2986-d892-a894-3803430a3529', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 7, 'Quel est le statut du contrôle JO4 dans « lnx-proj-grille-audit.md » ? Réponds par la lettre c, p ou n.', 'Vérifie si la configuration du collecteur central existe et si elle est réellement active.', 'Une seule lettre : c, p ou n'),
  ('08cc5911-3be8-c8ee-9129-390c85e33611', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 8, 'Quel est le statut du contrôle SA1 dans « lnx-proj-grille-audit.md » ? Réponds par la lettre c, p ou n.', 'Pars de la dernière ligne de sauvegarde réussie, calcule son âge au 27 avril 2026, puis applique le seuil.', 'Une seule lettre : c, p ou n'),
  ('afa5e74a-b1cc-5975-a6b4-f9cf63e2ca6f', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 9, 'Quel est le statut du contrôle SE2 dans « lnx-proj-grille-audit.md » ? Réponds par la lettre c, p ou n.', 'Regarde si la configuration du dossier d’upload bloque explicitement l’exécution de PHP ou si cette protection manque.', 'Une seule lettre : c, p ou n'),
  ('dd6de528-f085-0819-fb6e-6e76298b00b3', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 10, 'Dans « lnx-proj-preuves-systeme.txt », combien de correctifs de sécurité restent en attente ?', 'Ne compte que les lignes du canal security dans la section apt.', 'Nombre entier'),
  ('30b00056-f76d-2705-73b8-1b728144862e', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 11, 'Quelle est la valeur effective de PermitRootLogin visible dans « lnx-proj-preuves-acces.txt » ?', 'Lis la section sshd -T, qui donne déjà la valeur effective et non une simple valeur de fichier source.', 'Valeur exacte, par exemple no'),
  ('f5860175-31ef-df01-ef6a-312761b62faf', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 12, 'En relisant « lnx-proj-preuves-acces.txt », combien de ports TCP écoutent sur toutes les interfaces (adresse locale 0.0.0.0) ?', 'Compte les lignes LISTEN dont l’adresse locale commence par 0.0.0.0:, sans inclure 127.0.0.1.', 'Nombre entier'),
  ('a9fd1095-470b-5a0a-3b5c-f187e9d73f07', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 13, 'Quel est l’âge en jours de la dernière sauvegarde réussie à la date d’audit du 2026-04-27, d’après « lnx-proj-preuves-services.txt » ?', 'Repère la dernière ligne SUCCESS dans le journal de sauvegarde, puis calcule l’écart calendaire avec le 27 avril 2026.', 'Nombre entier de jours'),
  ('98617ae2-2009-ab8e-78bf-da83a2059ebf', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 14, 'Quel est le score pondéré du domaine « journalisation » dans « lnx-proj-grille-audit.md » ?', 'Déduis d’abord le statut des quatre contrôles du domaine, puis applique la formule de score pondéré avec leurs poids.', 'Pourcentage entier'),
  ('1b652c55-a77e-df9f-3d47-f3415da30338', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 15, 'Quel est le score global du serveur après avoir noté l’ensemble de la grille « lnx-proj-grille-audit.md » ?', 'Ne calcule le score global qu’après avoir déduit les 24 statuts, puis additionne tous les poids et toutes les valeurs.', 'Pourcentage entier'),
  ('b4f6a29f-2fdd-e9ba-3940-bf0eae56e4d5', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 16, 'Quel domaine obtient le score le plus faible ? Réponds par la lettre. a) accès et comptes b) réseau c) système et correctifs d) journalisation e) sauvegardes f) configuration des services', 'Calcule ou compare les six scores de domaine, puis convertis le domaine le plus faible en lettre.', 'Une seule lettre'),
  ('6a703c43-593b-30e2-848b-39a6808a4577', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 17, 'Dans « lnx-proj-risques.txt », quel identifiant d’action arrive en priorité n°1 une fois les contrôles partiels et non conformes retenus ?', 'Garde seulement les actions liées à des contrôles que tu as jugés partiels ou non conformes, puis trie selon la règle écrite dans la grille.', 'Identifiant d’action'),
  ('453018d5-b177-33aa-efba-33d865e68507', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 18, 'Combien de gains rapides restent dans « lnx-proj-risques.txt » après avoir filtré sur les seuls contrôles partiels ou non conformes ?', 'Commence par écarter les actions liées à des contrôles conformes, puis applique la définition de gain rapide de la grille.', 'Nombre entier'),
  ('807cfd32-a0d7-1ef6-a697-79a79b9aab89', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 19, 'Quel niveau global de maturité correspond au score final ? Réponds par la lettre. a) initial b) fragile c) maîtrise d) robuste', 'Calcule d’abord le score global entier, puis reporte-le sur les bornes de maturité de la grille.', 'Une seule lettre')
insert into private.lab_task_keys (task_id, accepted, explanation) values
  ('d479459c-4b54-dff3-92b5-0338d45be9c9', array['8']::text[], 'Dans un export « ls -lR », chaque section correspond à un dossier précis. Il faut ouvrir la section « /srv/partage/communication/site », ignorer « total », puis compter uniquement les lignes de contenu direct. Cette méthode donne 8 éléments et t’évite de mélanger ce dossier avec ses voisins.'),
  ('72dd650c-4bed-0ba3-7ae9-53cfaf941a7f', array['justificatifs-2026-04.zip']::text[], 'La bonne méthode consiste à rester dans la section du dossier demandé puis à comparer les tailles affichées sur la même colonne. Le fichier le plus volumineux y est justificatifs-2026-04.zip. Relever un nom depuis la plus grande taille évite les confusions liées à l’ordre alphabétique du listing.'),
  ('f354a912-e9ad-43c5-40c8-17b2dd0c80f7', array['2181288']::text[], 'Dans ce type d’export, chaque ligne de fichier porte déjà sa taille en octets. Il faut donc isoler les PDF du dossier indiqué puis additionner leurs tailles. En procédant ainsi, on obtient 2181288 octets, sans rien supposer du système réel.'),
  ('beaea4d8-bbbf-bfe2-0410-efd17f10aef3', array['40-adhesions.conf']::text[], 'Pour un dossier donné, le fichier le plus récent se déduit du plus grand horodatage affiché dans la même section. Ici, 40-adhesions.conf porte la date la plus récente. Cette lecture est utile pour trouver rapidement la dernière configuration touchée.'),
  ('1ca1a066-7b30-b3db-6646-96cf11137f32', array['5']::text[], 'Sous Linux, un nom commençant par un point est caché. Il faut donc lire la section « /home/cfall » puis compter les entrées dont le nom commence par « . », sans descendre dans les sous-dossiers. Ce comptage donne 5 éléments cachés.'),
  ('0eadb313-fe46-4142-fc72-f291c1e969d4', array['/home/cfall/.config', '/home/cfall/.config/']::text[], 'L’historique se suit pas à pas comme si tu étais dans le shell. En partant de « /home/cfall », il faut appliquer chaque « cd » dans l’ordre, mémoriser le dossier précédent pour « cd - » puis terminer sur la cible finale. On arrive ainsi dans /home/cfall/.config.'),
  ('771d6ec9-55cd-81b6-b566-fc38afdd2f50', array['/srv/partage/adhesions/contrats/contrat-2026-04-07.pdf']::text[], 'Résoudre un chemin relatif consiste à partir du dossier donné, remonter avec chaque « .. », puis suivre les segments restants. Depuis « /srv/partage/adhesions/imports », la cible devient /srv/partage/adhesions/contrats/contrat-2026-04-07.pdf. C’est exactement la méthode à employer sans dépendre d’un shell réel.'),
  ('5332ec6f-dfac-9efc-b142-25248c6d2b07', array['10.20.0.100']::text[], 'Le journal web commence par l’adresse IP source. En regroupant toutes les lignes par IP puis en triant les totaux, on trouve un seul maximum : 10.20.0.100. Cette méthode reste valable même quand les chemins, les méthodes et les statuts changent.'),
  ('2203c1ad-2d9e-5f70-72c3-56d0a37bf2ce', array['116']::text[], 'Le code HTTP se lit dans le champ juste après la requête. En filtrant uniquement les lignes 404 et en les comptant, on obtient 116. Ce type de total aide à distinguer un simple bruit normal d’un volume inhabituel d’erreurs.'),
  ('7f83512e-9fb6-71ae-1443-3123eb89d820', array['/admin/backup.php']::text[], 'Il faut d’abord isoler les lignes 404, puis ne garder que le chemin demandé afin de compter les répétitions. Le chemin qui revient le plus souvent est /admin/backup.php. Regrouper les erreurs par URL est une bonne base pour repérer des scans ciblés.'),
  ('860c541d-6b7e-4164-67e6-e4b8f6f08045', array['111']::text[], 'La méthode HTTP apparaît au début de la requête, entre les guillemets du journal nginx. En comptant toutes les lignes qui commencent par POST dans ce champ, on trouve 111 requêtes. Cette mesure permet de séparer navigation simple et envois de formulaires.'),
  ('8f91ca64-0d02-a1cd-c306-e8a09fcd007b', array['14']::text[], 'La bonne approche consiste à extraire la première colonne du journal, à supprimer les doublons puis à compter les valeurs restantes. On obtient 14 adresses distinctes. Cela donne une vision plus juste de la diversité des clients que le simple volume de requêtes.'),
  ('08a25382-511b-754d-2f60-ca4c3c2444bf', array['10']::text[], 'Le fichier est un CSV à points-virgules. Il faut donc lire la troisième colonne, garder les lignes où la ville vaut « Lagune-Est », puis compter ces lignes. Le résultat est 10, ce qui montre l’importance de choisir la bonne colonne avant d’agréger.'),
  ('cb32c601-eecc-553b-8bf0-e79d324bc6be', array['famille-plus']::text[], 'Après avoir regroupé les lignes sur la quatrième colonne du CSV, une seule formule arrive en tête sans égalité : famille-plus. Cette méthode est plus sûre que l’inspection visuelle, surtout quand les catégories sont proches en volume.'),
  ('9576f637-2a89-9cc8-d8d1-0329afca3a3b', array['234495']::text[], 'Le calcul demandé combine deux filtres : le chemin exact et le code HTTP 200. Une fois ces lignes isolées, il suffit d’additionner la taille envoyée en octets. Le total vaut 234495, ce qui illustre un vrai croisement de conditions dans un journal web.'),
  ('aed28fbe-7254-98f5-0874-b7582b8809e4', array['sysmaint']::text[], 'L’UID 0 correspond au superutilisateur, quel que soit le nom du compte. En lisant la troisième colonne de passwd, on voit que sysmaint partage ce privilège avec root. C’est exactement le genre d’anomalie à signaler dans un audit.'),
  ('786792a7-d70d-3e98-4332-152bcb98a265', array['svc-backup']::text[], 'Un compte de service devrait en général utiliser « nologin » ou un shell non interactif. Ici, svc-backup possède un shell interactif, ce qui ouvre une surface d’usage ou d’abus inutile. Il faut donc lire à la fois la nature du compte et son shell final.'),
  ('c56ddfe8-1ce0-63e5-db83-459ac1d9dd5d', array['cfall']::text[], 'Un champ vide dans shadow n’est pas la même chose qu’un compte verrouillé : il indique l’absence de mot de passe défini. Le compte concerné ici est cfall. Vérifier la forme exacte du deuxième champ évite une mauvaise interprétation.'),
  ('a29758bd-0435-7a1e-ed1a-fd85661ea417', array['c']::text[], 'Le préfixe de l’empreinte du compte nkamga correspond à l’option c, donc à md5-crypt. Lire ce préfixe est la bonne manière d’identifier la famille de hachage sans rien craquer. Cela permet ensuite d’évaluer si l’algorithme est moderne ou trop ancien.'),
  ('20a346c5-03b9-d8f7-6827-c1a7321d2ea4', array['24']::text[], 'Dans ce lab, un compte verrouillé se reconnaît à un deuxième champ commençant par « ! » ou « * ». En appliquant cette règle sur tout le fichier shadow, on obtient 24 comptes verrouillés. C’est un comptage simple, mais il repose sur une convention précise à respecter.'),
  ('c447653d-1ff6-bc59-eb36-95ba3dd8cad5', array['2026-03-14']::text[], 'Le troisième champ de shadow donne un nombre de jours écoulés depuis le 1 janvier 1970. Une fois converti, le dernier changement du compte straore tombe le 2026-03-14. Cette conversion de base est souvent nécessaire dans un audit Linux.'),
  ('3b0e91b5-86e3-f644-2b81-3acb2bd3a755', array['24']::text[], 'À partir de la date de changement extraite depuis shadow, il faut calculer l’écart jusqu’au 7 avril 2026. Le résultat est 24 jours. Ce type de mesure sert à vérifier si une politique de renouvellement reste respectée.'),
  ('f219de04-fe70-9b6b-a578-e7affe3fe4d7', array['3']::text[], 'Le groupe sudo se lit dans le dernier champ de la ligne correspondante du fichier group. En séparant cette liste sur les virgules, on compte 3 membres. C’est une première mesure simple de la surface d’administration locale.'),
  ('40db2ba8-651e-64e1-d890-4cd740f7607a', array['/etc/sudoers.d/99-web-maint', '99-web-maint', 'sudoers.d/99-web-maint']::text[], 'La règle la plus dangereuse est celle qui permet toutes les commandes sans demande de mot de passe. Dans l’export concaténé, elle se trouve dans /etc/sudoers.d/99-web-maint. Il faut donc comparer le contenu réel des règles, pas seulement leur commentaire.'),
  ('241138d1-68c0-8cf3-d6e9-3d81ff4f5b87', array['754']::text[], 'La ligne du fichier /var/backups/export-adhesions.sh se convertit en additionnant chaque triplet symbolique. On obtient 754. Savoir faire cette conversion reste indispensable pour juger rapidement si une permission est raisonnable ou trop large.'),
  ('9b86e158-548a-1efb-6871-93f131b91034', array['imports.conf', '/etc/alize/imports.conf']::text[], 'Un fichier modifiable par tout le monde se reconnaît à un mode avec écriture pour les trois catégories. Dans cet export, le premier fichier qui correspond à ce critère est imports.conf. L’ordre de lecture compte donc autant que le motif de permission.'),
  ('52097b5a-5685-04b0-cdd4-8bbb518507c4', array['1']::text[], 'Le guide donne une liste de binaires SUID normaux pour ce lab. En comparant chaque chemin du listing à cette référence, on obtient 1 écart. Ce comptage est une technique d’audit très concrète pour réduire le bruit et confirmer qu’il ne reste qu’une vraie anomalie à examiner.'),
  ('4193bae5-b95f-b8f3-0d23-39530417663b', array['pkamga']::text[], 'La tâche demande un croisement entre deux fichiers : un compte jamais connecté d’après lastlog, mais disposant d’un shell valide dans passwd. Le compte qui réunit ces deux critères est pkamga. Ce type de compte oublié mérite une revue rapide.'),
  ('65b5ee0d-8712-f6c5-bcc6-644b419f74b7', array['2']::text[], 'On ne garde que les comptes de personnes : UID de 1000 ou plus et shell différent de « nologin », ce qui écarte par exemple « nobody » malgré son UID élevé. On compare ensuite leur dernière connexion à la date du 7 avril 2026. En comptant « Never logged in » comme plus ancien que 90 jours, on obtient 2 comptes dormants. Cette lecture combine hygiène des accès et suivi d’activité.'),
  ('0185d4fc-b367-27d8-3dc9-c2df23148a56', array['4821']::text[], 'La colonne %CPU du fichier « ps aux » permet d’identifier immédiatement le processus le plus gourmand. En comparant toutes les valeurs, le maximum revient au PID 4821. Ce réflexe est essentiel quand on cherche l’origine d’une charge anormale.'),
  ('1d456a28-acfc-a697-fc4b-52a938bdf320', array['c']::text[], 'Une fois la bonne ligne trouvée, la première colonne donne l’utilisateur effectif du processus. Ici, le processus au CPU maximal tourne sous root, donc l’option correcte est c. Associer charge et utilisateur aide ensuite à distinguer un service normal d’un processus lancé hors cadre.'),
  ('436944f5-19c8-74d5-51e8-cb165143bb44', array['/tmp/.cache/kworker']::text[], 'La colonne COMMAND révèle le chemin ou la ligne de lancement du processus. Pour le PID le plus gourmand, elle vaut /tmp/.cache/kworker. Lire ce champ en entier est souvent ce qui permet de distinguer un binaire légitime d’un programme rangé dans un emplacement douteux.'),
  ('7d4032d9-2717-655f-eb4d-cb53e9202049', array['4680']::text[], 'Le parent direct se lit dans la colonne PPID de l’export d’arbre. Pour le processus le plus gourmand, cette relation remonte au PID 4680. Retrouver le parent aide à comprendre comment le processus a été lancé et quelle chaîne d’exécution l’a engendré.'),
  ('64c9cf9c-80b7-991c-5d05-0c69d3863919', array['12']::text[], 'Pour ce comptage, il suffit d’isoler les lignes de « ps aux » dont l’utilisateur est exactement « www-data ». On en trouve 12. C’est une façon simple de mesurer le nombre de workers ou de shells actifs sous le compte du serveur web.'),
  ('e9bf0f51-2212-1cb1-c7ab-1ee75ccb1230', array['222']::text[], 'La mémoire résidente totale se calcule en additionnant les RSS de toutes les lignes « www-data », puis en divisant par 1024 pour passer en Mio et en arrondissant. Le total obtenu est 222 Mio. Cette somme donne une image plus réaliste que la lecture d’une seule ligne.'),
  ('0958f146-60a1-3972-b754-7ed5991fc6b3', array['mariadb.service']::text[], 'Le port 3306 apparaît dans l’export des ports avec un nom de processus explicite. En le rapprochant de la liste des unités, on retrouve le service mariadb.service. Cette mise en relation entre port et service est un geste d’administration courant.'),
  ('e319f59b-47db-1325-5690-6d676a859a76', array['4545']::text[], 'Le port inattendu est 4545. Il se distingue par le fait qu’il est ouvert sur toutes les interfaces et lié à un service qui ne fait pas partie des composants web attendus. Savoir relever ce type d’écart permet de prioriser une investigation.'),
  ('6190c3b8-b4f9-db35-8df4-a124f4e5c3a6', array['2']::text[], 'La liste systemd signale les services en échec avec les colonnes ACTIVE et SUB à « failed ». En comptant ces lignes, on obtient 2 services en échec. C’est une lecture rapide mais très utile pour repérer les problèmes persistants.'),
  ('0bde3848-7a57-ffff-1062-86c5ae8c5ec6', array['/usr/local/bin/cache-flush.sh']::text[], 'Dans cron, « */5 * * * * » signifie une exécution toutes les cinq minutes. La ligne correspondante appelle /usr/local/bin/cache-flush.sh. Lire l’expression puis extraire seulement le script demandé est la bonne façon d’éviter les erreurs de copie.'),
  ('a3177086-3a93-ca91-36ae-a3bf50a2ac3a', array['03:20', '3:20']::text[], 'L’expression « */20 2-4 * * 1-5 » déclenche une exécution toutes les 20 minutes entre 02:00 et 04:59 les jours ouvrés. Après 03:05 UTC le mercredi 8 avril 2026, la prochaine occurrence tombe donc à 03:20. Ce calcul montre qu’il faut lire pas, plage d’heures et jour autorisé ensemble.'),
  ('cb0ceeb0-d92e-2010-0703-1c0f3509ed15', array['d']::text[], 'L’export rappelle les droits des quatre scripts proposés. « purger-miniatures.sh » est lui aussi modifiable par tout le monde, mais il est lancé par le compte svc-web et non par root : le modifier ne donnerait pas les droits du superutilisateur. Les deux autres ne sont modifiables que par leur propriétaire. Le script lancé par root et modifiable par n’importe qui est /usr/local/bin/rapport-cache.sh, donc la bonne réponse est d.'),
  ('8582dde9-fed8-2d41-695f-b3a27652ea9a', array['telemetry-relay.service']::text[], 'Le fichier d’unité montre explicitement « Restart=always » et un « ExecStart » rangé dans un chemin inhabituel. L’unité correspondante est telemetry-relay.service. C’est un bon exemple d’anomalie qui ne se voit qu’en combinant service et contenu d’unité.'),
  ('d0f93351-5f58-c91b-457f-1e5257ce7539', array['2']::text[], 'L’énoncé donne ici une définition opérationnelle unique : il faut compter seulement les minuteurs dont la colonne LAST vaut « n/a ». En appliquant ce critère direct à l’export, on en trouve 2. Cela évite de mélanger absence d’exécution et échec de service.'),
  ('42026516-94c4-1c14-3a15-e790bd882870', array['2026-04-10']::text[], 'La ligne « 0 3 15 * 5 » se déclenche à 03:00 quand le jour du mois vaut 15 ou quand le jour de semaine vaut vendredi. À partir du mercredi 8 avril 2026 03:00 UTC, la prochaine date atteinte par cette règle est 2026-04-10. Cette tâche vérifie que tu connais bien le piège du OU dans cron.'),
  ('888821f4-19aa-e59d-e4a8-75f36dc3bc49', array['10.20.0.1']::text[], 'La route par défaut indique vers quelle passerelle le serveur envoie le trafic qui sort de son réseau local. Ici, la ligne « default via » montre clairement 10.20.0.1, ce qui en fait la bonne réponse après une simple lecture de la table de routage.'),
  ('24e5b7a6-c36e-f294-98aa-16418c446899', array['ens18']::text[], 'La section « ip -br a » montre l’adresse du serveur et la route du réseau local confirme quelle interface porte 10.20.0.10/24. Le bon nom est ens18. Cette méthode évite de répondre depuis une intuition sur le nom habituel des cartes réseau.'),
  ('48691d6f-e07c-4131-4c11-a4b0616441e1', array['24', '/24']::text[], 'L’adresse de srv-web01 est écrite avec son masque directement dans la sortie d’interface. Le préfixe visible est 24, soit /24. Lire le suffixe CIDR est la manière la plus rapide de retrouver la taille du réseau local.'),
  ('1d90b270-3027-58a9-6e5b-2e27a6c618d8', array['prohibit-password']::text[], 'La première valeur rencontrée pour PermitRootLogin est prohibit-password. Les lignes suivantes visibles dans le même fichier concaténé ne remplacent pas cette valeur globale. Il faut donc lire dans l’ordre d’obtention réel, pas seulement prendre la dernière occurrence affichée.'),
  ('95dc1e7c-588b-62a2-3bf6-7f559af36b8a', array['oui', 'yes']::text[], 'La valeur globale visible plus haut est complétée par un bloc Match dédié à cfall. Comme ce bloc s’applique à cet utilisateur, PasswordAuthentication devient oui pour ce cas précis. Il faut donc croiser la valeur globale et le contexte du bloc Match concerné.'),
  ('05e684a5-d77d-3402-1526-ff06756a7320', array['198.51.100.47']::text[], 'Après regroupement des lignes « Failed password », l’adresse 198.51.100.47 arrive nettement en tête. C’est cette adresse qu’il faut retenir pour caractériser la source la plus insistante du journal.'),
  ('1d7af90f-1605-2d26-50bc-534ec73731d7', array['6']::text[], 'Le journal distingue les comptes existants des comptes inexistants avec la mention « invalid user ». En comptant les noms distincts de cette seule catégorie, on obtient 6. Cette différence entre total d’échecs et comptes distincts est importante pour qualifier la nature du bruit observé.'),
  ('c92d8013-0048-6d34-0ae0-59c07297ad73', array['03:17:42', '3:17:42']::text[], 'Le premier succès par mot de passe apparaît à 03:17:42 UTC. Cette lecture demande de distinguer les succès par clé publique, normaux pour l’administration, des succès par mot de passe, beaucoup plus sensibles dans ce contexte.'),
  ('532192ec-08b2-f866-46db-b6259afc1592', array['nkamga']::text[], 'La ligne du premier « Accepted password » cite explicitement le compte nkamga. La bonne méthode consiste à retrouver d’abord l’heure du succès, puis à relire la même ligne pour isoler le compte sans te laisser distraire par les lignes voisines.'),
  ('ff77006e-dd56-0118-202f-d849958a3fa5', array['6']::text[], 'Avant le premier succès par mot de passe depuis cette adresse, le journal montre 6 échecs. Cette chronologie appuie l’idée d’une tentative insistante plutôt que d’une simple erreur ponctuelle d’un utilisateur légitime.'),
  ('f4babcd2-6091-9d13-f277-53495bd6aa76', array['6']::text[], 'Le port SSH réellement retenu dans la configuration n’est pas celui que cette règle large expose à tout le monde. La règle inutilement permissive est la numéro 6. Il faut croiser deux fichiers pour le voir : la configuration SSH et les règles UFW.'),
  ('b703eb76-e1b1-2d03-2217-055c50531f0a', array['4']::text[], 'La règle décisive est la numéro 4. Une règle plus générale apparaît plus bas, mais elle ne sera jamais consultée ici, car la première règle compatible avec cette source et ce port tranche déjà le verdict.'),
  ('2248cc21-785a-56d3-99c3-2de0c8815d90', array['2']::text[], 'Le guide fixe une borne générale de 3072 bits pour les clés RSA d’administration. En croisant type et taille, on trouve 2 clés RSA en dessous de ce seuil, ce qui justifie une revue ou un remplacement.'),
  ('293cb2f2-6f4a-2a7c-c259-f4c2ff18d976', array['4']::text[], 'La restriction « from= » borne les adresses autorisées à utiliser une clé. En relisant les options d’ouverture de ligne, on voit que 4 clés n’ont pas cette restriction. Cette absence n’est pas toujours interdite, mais elle mérite une revue pour les usages d’administration.'),
  ('f58ec194-246a-3b3a-2acb-05454aa5df01', array['2202']::text[], 'Le port réellement retenu est 2202. Ici encore, il faut relire l’ordre d’obtention causé par Include avant de conclure. Une règle UFW sur un autre port peut donc rester présente sans protéger le vrai service.'),
  ('1c9e02f1-cfb7-dfc0-bcaa-7c2c8264971b', array['16']::text[], 'Le nombre total se calcule en comptant les lignes de paquets réellement proposées par apt. Ici, on en trouve 16. Cette méthode évite de compter la ligne « Listing... » ou les lignes de /etc/os-release qui ne sont pas des mises à jour.'),
  ('e492ad1f-6916-a4f9-d211-f2e140ce5a16', array['6']::text[], 'Le canal de sécurité apparaît directement dans le nom de provenance du paquet. En ne gardant que ces lignes, on compte 6 mises à jour de sécurité. C’est un bon premier indicateur de l’exposition immédiate du système.'),
  ('8172f91c-2b45-409a-3b2f-8239bcace133', array['1:9.6p1-3ubuntu13.12']::text[], 'La ligne du paquet openssh-server annonce la version 1:9.6p1-3ubuntu13.12. Relever la version proposée plutôt que la version précédente permet de savoir ce qu’apt installerait réellement si l’on lançait la mise à jour.'),
  ('ee3b3203-3e50-2d5c-8d32-942753f9137a', array['/backup/local', '/backup/local/']::text[], 'Dans la section df -h, le point de montage /backup/local dépasse 90 % et atteint la pression la plus forte. Ici, on raisonne bien sur l’occupation en blocs, pas sur les inodes ni sur la taille totale brute du disque.'),
  ('8064d60a-c37c-2b0c-59a6-894d88ffe7fd', array['/var/log', '/var/log/']::text[], 'Le point de montage /var/log atteint le pourcentage d’inodes le plus préoccupant. Un système peut manquer d’inodes même quand plusieurs gigaoctets restent libres, d’où l’intérêt de lire les deux tableaux séparément.'),
  ('4bbf8a25-7fc1-f367-060c-53f02e1680a3', array['/tmp', '/tmp/']::text[], 'Le point de montage concerné est /tmp. Les options visibles montrent déjà nodev et nosuid, mais pas noexec. Pour ce type d’emplacement temporaire, l’absence de cette option reste un signal de risque selon la règle générale du guide.'),
  ('b067c785-352d-ad8f-c14b-1397034a1a83', array['45.7', '45,7', '45.7 g', '45,7 g']::text[], 'En additionnant l’espace disponible de chaque ligne de la section df -h, tmpfs compris, on obtient 45.7 Gio. Cette addition donne une vue synthétique de la marge totale restante, même si chaque point de montage a ensuite sa propre urgence.'),
  ('be2b40bc-b63c-f8ed-d1f9-f1609d364bf2', array['25']::text[], 'Le journal compte 25 nuits réellement réussies. Les lignes FAIL documentent des tentatives, mais elles ne doivent pas être comptées comme des sauvegardes utilisables.'),
  ('31ca1a21-2d1f-20ce-429b-9143ac9427a5', array['3']::text[], 'La plus longue série d’échecs successifs vaut 3. Cette mesure décrit mieux la fragilité opérationnelle qu’un simple nombre total d’échecs, car plusieurs nuits ratées d’affilée augmentent fortement le risque de perte.'),
  ('bad3d440-b536-8e4d-d993-a2a7348bddfe', array['2026-04-10', '10/04/2026', '10-04-2026']::text[], 'La dernière ligne SUCCESS avant la date d’audit correspond au 2026-04-10. Les échecs plus récents ne changent pas cette date de dernière sauvegarde effectivement exploitable.'),
  ('5236d36d-f707-8148-55ce-c8e01bcc4d43', array['3']::text[], 'La dernière sauvegarde réussie date du 2026-04-10. Entre cette date et le 13 avril 2026, il s’écoule 3 jours calendaires. C’est cette ancienneté qui intéresse l’audit, pas la date du dernier essai tout court.'),
  ('5e8b3431-2b26-5e29-6e82-e2614dad7423', array['13']::text[], 'La politique s’applique par catégorie et conserve seulement les plus récents de chaque type. En l’appliquant à la liste fournie, on garde 13 instantanés. Il ne faut pas inventer de règle supplémentaire ni fusionner daily, weekly et monthly dans un seul compteur.'),
  ('76c1093d-4b05-7054-6cfd-9cdf5d0a45dd', array['f39aa111']::text[], 'Pour revenir à l’état de la veille de l’incident, il faut choisir le dernier instantané antérieur à cette date, soit f39aa111. Le raisonnement consiste à lire les horodatages et non à prendre automatiquement le plus récent tout court.'),
  ('f6d23d1b-918d-2a46-99e2-22ba88c285b5', array['15']::text[], 'La ligne 15 réutilise la variable du chemin source sans la protéger correctement. Avec un chemin qui contient des espaces, la commande peut alors recevoir plusieurs arguments au lieu d’un seul, ce qui change complètement son comportement.'),
  ('8d059359-a72b-c279-f19d-d032f259c01b', array['non', 'no']::text[], 'La réponse correcte est non. Au 13 avril 2026, trois copies comptent (la production, le miroir USB et le dépôt restic local) et elles reposent sur au moins deux supports différents. En revanche, la seule copie hors site est en échec et sa dernière synchronisation date du 30 mars : elle ne compte pas, il n’existe donc aucune copie hors site valide.'),
  ('b5e85bbe-3b2a-ec3a-c502-988268f670ab', array['c']::text[], 'Le critère qui n’est pas satisfait est la copie hors site valide, donc la lettre attendue est c. Il y a bien trois copies valides et plusieurs supports, mais la copie distante, en échec depuis le 30 mars, ne compte pas.'),
  ('1cee3ec5-7360-8de8-57df-2a0cc2e0dcfa', array['5']::text[], 'Le bloc correct est le numéro 5. Pour le retrouver proprement, il faut comprendre que le script affiche d’abord un total, puis les trois adresses IP les plus fréquentes parmi les lignes d’échec du journal.'),
  ('124351c1-979c-bea1-8e90-ebec08ee7927', array['27']::text[], 'Le script compte 27 lignes contenant « Failed password ». Cette réponse peut se vérifier de deux façons indépendantes : en exécutant réellement le script ou en comptant les lignes correspondantes dans le journal fourni.'),
  ('b9829dd9-2fdb-9a72-50a1-271541c9a627', array['198.51.100.23']::text[], 'L’adresse 198.51.100.23 arrive en tête, car c’est elle qui apparaît le plus souvent dans les lignes d’échec. La méthode consiste à regrouper les adresses et à comparer leurs fréquences plutôt qu’à parcourir le journal à l’œil.'),
  ('f584b7fa-45cb-97d2-be3c-1b76ce5d34c0', array['4']::text[], 'Le script produit 4 lignes sur la sortie standard : une ligne de total, puis trois lignes de classement. Distinguer la structure de sortie aide à reconnaître le bon bloc parmi les propositions du fichier d’attendus.'),
  ('c5685e41-7b66-e35a-b4a9-879c86109c53', array['0']::text[], 'Le code de retour est 0. Le script trouve son fichier, compte les lignes et termine sans erreur explicite. Vérifier le code de sortie fait partie d’une lecture complète d’un script, au-delà de l’écran affiché.'),
  ('35be7210-b85c-fd74-f888-04e3e78b3be9', array['3']::text[], 'Le script détecte 3 fichiers anciens. Cette valeur vient du comptage effectué avant la suppression potentielle. Comprendre l’ordre des opérations évite de confondre les fichiers candidats et les fichiers réellement retirés ensuite.'),
  ('d331ed39-9d20-53e9-bd7b-ba38f5ce3793', array['37']::text[], 'La ligne 37 réutilise la variable de chemin sans la protéger. Avec un espace ou une valeur vide, l’expansion du shell change complètement ce qui sera passé à rm. C’est le défaut central du script de nettoyage.'),
  ('d0b5d21a-3c5f-529b-649a-ffa91c094f61', array['recent.txt']::text[], 'Même avec une variable bien protégée, le motif de suppression reste trop large : il vise tous les fichiers du dossier. Le fichier non ancien qui serait donc touché est recent.txt. Cela montre que corriger les guillemets ne suffit pas quand la logique de sélection elle-même est trop large.'),
  ('a63d06c8-174d-7696-3867-ac71335173cc', array['4']::text[], 'À la fin, il reste 4 fichiers. Le script annonce bien des candidats anciens, mais la suppression échoue à cause du chemin non protégé contenant un espace. L’exécution réelle confirme donc le défaut théorique du code.'),
  ('af5aff42-4ca1-ab10-48ee-0870bd47db49', array['7']::text[], 'Le script signale 7 comptes au total. Cette réponse demande de croiser la règle métier codée dans le script avec les colonnes du CSV, puis de compter seulement les lignes effectivement retenues par awk.'),
  ('8691e1a0-1f54-b2dc-6951-fa75b521e759', array['4']::text[], 'Avec le préfixe « svc- », le script produit 4 lignes. Il liste d’abord les comptes de service concernés, puis ajoute toujours une ligne de total final. Compter cette dernière fait partie de la lecture exacte de la sortie.'),
  ('49560405-6d1c-f7d1-e3d5-b54881d57b6e', array['24']::text[], 'La ligne 24 exécute avec eval le texte préparé juste avant. Même si l’exemple reste inoffensif dans ce labo, cette étape transforme une simple chaîne en commande shell réelle, ce qui ouvre la porte à une injection si l’entrée n’est pas validée.'),
  ('8e2e7600-c565-2cb3-2651-12851ff9b5c0', array['sc2086']::text[], 'Le code attendu est SC2086. Le connaître aide à relier un avertissement d’outil à un défaut concret de robustesse dans un vrai script shell.'),
  ('21ff6cf5-3f80-21d3-2337-f2ba96e04093', array['b']::text[], 'La bonne réponse est b. Cette écriture protège bien la variable de chemin tout en laissant le joker s’appliquer aux fichiers du dossier visé. Les autres variantes cassent soit l’expansion, soit la sécurité de la commande.'),
  ('c0619ac8-4a4d-95fc-f6c7-e26013392221', array['set -e', '-e', 'set -o errexit', '-o errexit']::text[], 'La bonne réponse est set -e. Cette option demande au shell d’arrêter le script dès qu’une commande simple échoue, ce qui évite souvent de continuer sur un état déjà incohérent.'),
  ('43d706b0-4b5d-29d1-714d-477f534cb7d8', array['203.0.113.91']::text[], 'Il faut filtrer les lignes d’échec dans auth.log puis vérifier qu’aucune ligne de succès ne correspond à cette même source. L’adresse 203.0.113.91 ne fait que du bruit de force brute et n’obtient jamais de session.'),
  ('ce5d83ba-89fb-c231-ae8c-23f8d8d8cff7', array['14']::text[], 'Après avoir isolé la source de force brute, il suffit de recompter ses lignes Failed password. On en trouve 14, ce qui confirme une séquence distincte du reste de l’attaque.'),
  ('78f57daf-e5ed-dc60-8de4-05178b3f71de', array['198.51.100.62']::text[], 'L’adresse 198.51.100.62 apparaît d’abord sur le téléversement malveillant, puis sur plusieurs GET contenant cmd=. Il faut donc croiser l’écriture initiale et les exécutions suivantes pour l’identifier proprement.'),
  ('29713d46-fbbb-f177-0545-27f314a8d453', array['14:06:11']::text[], 'La première exécution visible du shell web a lieu à 14:06:11 UTC. La méthode consiste à repérer la première requête contenant cmd= sur le fichier téléversé, et non le POST d’envoi lui-même.'),
  ('c62fc3f5-e16a-1cd8-9246-4ee1b96bce92', array['/var/www/html/espace-adherents/uploads/scan-review.php']::text[], 'Le journal nginx montre le nom du shell web appelé ensuite, puis la sortie de find -ls donne son emplacement exact. En recoupant les deux, on obtient /var/www/html/espace-adherents/uploads/scan-review.php.'),
  ('43ed48aa-7fd7-d295-bbe1-a499df2d9997', array['www-data']::text[], 'Les processus maîtres tournent sous root pour ouvrir les ports, mais les workers nginx et le pool php-fpm s’exécutent sous www-data. Cette lecture vient directement de ps aux et explique pourquoi le point d’entrée web ne démarre pas avec les privilèges root.'),
  ('76f3bd55-6a30-ed8b-8c7f-09823dc200ea', array['svc-web']::text[], 'Le succès SSH cite svc-web, et l’historique shell montre les commandes lancées depuis cette session. Le recoupement prouve qu’il s’agit bien du compte de service réutilisé par l’attaquant.'),
  ('83bc7b22-9cf1-9f6f-37c5-f372a4d86e15', array['14:18:07']::text[], 'Le premier succès SSH malveillant apparaît à 14:18:07 UTC. Pour le trouver, il faut ignorer les connexions légitimes en clé publique et ne retenir que le premier Accepted password lié à l’attaque.'),
  ('8161db28-196f-a4f5-7cef-93d61fc633fc', array['198.51.100.62']::text[], 'Le premier accès SSH réussi vient de 198.51.100.62. Cette même source apparaît aussi dans le journal nginx, ce qui relie l’exploitation web et la session SSH.'),
  ('d2d2c3a5-0a2b-63cb-9787-45b4bcb5b28e', array['sysmaint']::text[], 'Auth.log contient l’appel à useradd puis passwd confirme la présence du nouveau compte. Le nom ajouté est sysmaint, ce qui valide une persistance de type compte local.'),
  ('e42a8f14-e7f1-4903-eeaf-389734476487', array['/usr/local/bin/system-cache-refresh.sh']::text[], 'La tâche cron pointe vers /usr/local/bin/system-cache-refresh.sh, et l’historique shell montre quand ce script a été écrit. Les deux preuves ensemble établissent la persistance planifiée.'),
  ('8a375f28-7dd5-484f-3473-0b26df43bec6', array['192.0.2.77:8088', '192.0.2.77 8088', '192.0.2.77 port 8088']::text[], 'Le processus anormal de ps, la connexion ESTAB de ss et l’historique shell pointent tous vers la même cible. La destination complète est 192.0.2.77:8088.'),
  ('d697cd6d-d6e6-27e1-c24d-b5c8c488452f', array['/var/www/html/espace-adherents/upload.php']::text[], 'Le manifeste de référence et l’état actuel ont un chemin commun dont l’empreinte ne correspond plus. Ce fichier modifié est /var/www/html/espace-adherents/upload.php, ce qui documente une altération d’un composant déjà présent sur le site.'),
  ('61ee1099-4b2a-5441-c91c-3d93fe89c184', array['19']::text[], 'Il faut partir de la première exécution du shell web, puis s’arrêter à la création du compte local. L’écart obtenu est de 19 minutes.'),
  ('8d07bdbe-857b-863b-5cd0-29ae6b12e8b0', array['b']::text[], 'Le bon premier geste doit stopper l’attaque en cours tout en préservant les traces. Ici, la lettre b correspond à l’isolement maîtrisé de la machine avant toute remise en état. Supprimer le shell ou redémarrer efface des preuves, et un seul mot de passe changé laisse le compte caché et la tâche cron en place.'),
  ('2192a860-968d-8bcd-0ee6-df3962a83c50', array['d']::text[], 'La séquence correcte commence par l’isolement, protège ensuite les preuves puis passe à la rotation des secrets et à la remise en état. Dans les choix proposés, cela correspond à la lettre d.'),
  ('629d8a96-38b5-a0c8-b622-9ad867dedb57', array['3']::text[], 'Les adresses des questions 1, 3, 9 et 12 se ramènent à trois acteurs : la source de force brute, la source qui exploite le shell web puis se connecte en SSH (la même adresse aux questions 3 et 9) et la destination de la connexion sortante. Le nombre d’adresses distinctes est 3.'),
  ('d0fd2aa2-6bc3-48ac-ea6c-2d7784a86694', array['c']::text[], 'Le contrôle AC1 se juge sur la valeur effective de PermitRootLogin. Les preuves d’accès montrent la valeur no, ce qui place ce contrôle au statut c.'),
  ('a8e49eb9-9db7-ef1b-24ec-b2b3c43162af', array['p']::text[], 'AC2 ne dépend pas seulement de PasswordAuthentication, mais aussi de la restriction de la source d’administration. Comme l’authentification par mot de passe reste active tout en étant cantonnée à une source précise pour l’administration, le statut correct est p.'),
  ('8525db84-a2a0-5d6b-f12e-6a04e9ad31b5', array['p']::text[], 'AC3 se déduit du nombre de comptes de service dotés d’un shell interactif. Les preuves montrent un seul compte de service dans ce cas, ce qui mène au statut p.'),
  ('0c773d7e-8525-fe5a-85ab-bf7faecafcbd', array['n']::text[], 'SY1 repose sur le nombre de correctifs de sécurité encore en attente. Les preuves système en montrent 4, ce qui place ce contrôle au statut n.'),
  ('16d2a36e-da24-20ab-6880-e271148d6472', array['c']::text[], 'Le contrôle SY3 vérifie la présence de nodev, nosuid et noexec sur /tmp. Les trois options sont présentes dans les preuves, ce qui donne le statut c.'),
  ('7bb55702-5800-dde2-f2f5-cfbc641e378a', array['n']::text[], 'JO3 se lit dans l’état du service auditd. Les preuves montrent qu’il n’est pas actif, ce qui mène au statut n.'),
  ('b5b6e97d-2986-d892-a894-3803430a3529', array['p']::text[], 'JO4 dépend de l’existence d’une configuration de transfert central et de son activation effective. Ici, la configuration existe mais reste commentée, ce qui conduit au statut p.'),
  ('08cc5911-3be8-c8ee-9129-390c85e33611', array['p']::text[], 'Le contrôle SA1 se juge sur l’ancienneté de la dernière sauvegarde réussie. Celle-ci date du 2026-04-25, soit 2 jours avant l’audit, ce qui donne le statut p.'),
  ('afa5e74a-b1cc-5975-a6b4-f9cf63e2ca6f', array['n']::text[], 'SE2 se déduit de la protection réelle du dossier d’upload. Les preuves de services ne montrent pas de blocage effectif de l’exécution PHP à cet endroit, d’où le statut n.'),
  ('dd6de528-f085-0819-fb6e-6e76298b00b3', array['4']::text[], 'Il faut isoler les paquets du canal security dans la sortie apt list --upgradable. Le total observé est 4 correctifs de sécurité en attente.'),
  ('30b00056-f76d-2705-73b8-1b728144862e', array['no']::text[], 'La sortie sshd -T donne directement la valeur effective du paramètre. Ici, PermitRootLogin vaut no.'),
  ('f5860175-31ef-df01-ef6a-312761b62faf', array['4']::text[], 'Le comptage se fait dans la sortie ss en ne gardant que les écoutes sur 0.0.0.0. On en trouve 4.'),
  ('a9fd1095-470b-5a0a-3b5c-f187e9d73f07', array['2']::text[], 'La dernière sauvegarde réussie visible dans les preuves de services date du 2026-04-25. Par rapport à la visite du 2026-04-27, elle a 2 jours.'),
  ('98617ae2-2009-ab8e-78bf-da83a2059ebf', array['50', '50%', '50 %']::text[], 'Après avoir statué sur les contrôles du domaine journalisation, on applique la formule de la grille et l’arrondi demandé. Le score obtenu est 50 %.'),
  ('1b652c55-a77e-df9f-3d47-f3415da30338', array['64', '64%', '64 %']::text[], 'Le score global se calcule sur l’ensemble des 24 contrôles, avec les poids donnés par la grille et l’arrondi demandé. Le résultat final est 64 %.'),
  ('b4f6a29f-2fdd-e9ba-3940-bf0eae56e4d5', array['d']::text[], 'Une fois les six domaines recalculés, le domaine le plus faible correspond à la lettre d. Il s’agit de celui dont le pourcentage pondéré est le plus bas.'),
  ('6a703c43-593b-30e2-848b-39a6808a4577', array['r11']::text[], 'On ne priorise que les actions liées à des contrôles partiels ou non conformes, puis on trie par risque décroissant et effort croissant. L’action qui arrive en tête est R11.'),
  ('453018d5-b177-33aa-efba-33d865e68507', array['6']::text[], 'Après avoir filtré le registre sur les contrôles réellement à traiter, il faut garder les actions d’effort 1 avec un risque d’au moins 6. On obtient ainsi 6 gains rapides.'),
  ('807cfd32-a0d7-1ef6-a697-79a79b9aab89', array['c']::text[], 'Le score global du serveur tombe dans la tranche correspondant au niveau maîtrise. Dans les choix proposés, cela correspond à la lettre c.')
insert into public.lab_assets (id, lab_id, kind, title, description, url, position) values
  ('86272a3c-90ff-9fc3-90d2-982faf73d480', '0ed89ec4-11bf-d087-9263-7049be0c2520', 'log', 'Export d’arborescence', 'Arborescence partielle de « /srv », « /home » et « /etc/alize » au format « ls -lR --time-style=long-iso ».', '/labs/lnx-tp1-arborescence.txt', 1),
  ('7aa4c27c-e80d-6b46-e66c-766947095342', '0ed89ec4-11bf-d087-9263-7049be0c2520', 'log', 'Historique de navigation', 'Historique daté de commandes « cd » tapées par Cheikh Fall pour se repérer.', '/labs/lnx-tp1-historique.txt', 2),
  ('c9e41676-2ad0-8f83-c01f-417b95c26e53', '0ed89ec4-11bf-d087-9263-7049be0c2520', 'log', 'Journal d’accès web', 'Journal nginx de la journée du 6 avril 2026 au format « combined ».', '/labs/lnx-tp1-acces.log', 3),
  ('37f7ea83-816d-eedd-fbb6-e667d4545109', '0ed89ec4-11bf-d087-9263-7049be0c2520', 'log', 'Liste CSV des adhérents', 'Fichier séparé par des points-virgules avec ville et formule d’adhésion.', '/labs/lnx-tp1-adherents.csv', 4),
  ('2c3bce22-c1ff-490f-796c-8c1f957611fc', '0ed89ec4-11bf-d087-9263-7049be0c2520', 'guide', 'Guide du TP 1', 'Méthode de lecture de l’arborescence, de l’historique, des journaux web et du CSV.', '/labs/lnx-tp1-guide.pdf', 5),
  ('d98593cd-77d3-228b-f36a-d76474297327', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 'log', 'Export de passwd', 'Comptes locaux de « srv-fichiers01 » avec UID, GID, répertoire personnel et shell.', '/labs/lnx-tp2-passwd.txt', 1),
  ('75a48aa1-87ab-ef0a-fd45-d0aa61f02eb7', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 'log', 'Export de shadow', 'Empreintes fictives, dates de changement et politique de mot de passe.', '/labs/lnx-tp2-shadow.txt', 2),
  ('5a6e758a-3497-bb5e-3d42-095e17a43402', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 'log', 'Export de group', 'Groupes locaux et listes de membres utiles pour l’audit.', '/labs/lnx-tp2-group.txt', 3),
  ('bfd98c99-3ed1-91b6-47be-aa3ea045deb0', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 'log', 'Règles sudo concaténées', 'Fichier principal sudoers et fichiers de « /etc/sudoers.d » rassemblés dans un seul export.', '/labs/lnx-tp2-sudoers.txt', 4),
  ('65e08ca9-02fa-a0e2-732c-fc2542bc98fe', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 'log', 'Permissions sensibles', 'Listing « ls -l » de répertoires et fichiers critiques.', '/labs/lnx-tp2-permissions.txt', 5),
  ('f84c1f93-b1da-1bf2-1936-8eb1a120ed36', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 'log', 'Liste des binaires SUID', 'Sortie de « find / -xdev -perm -4000 -type f -ls ».', '/labs/lnx-tp2-suid.txt', 6),
  ('efa41708-61a3-7104-19ed-9230aaee22d0', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 'log', 'Dernières connexions', 'Export « lastlog » des comptes du serveur.', '/labs/lnx-tp2-derniere-connexion.txt', 7),
  ('35642a0d-8256-6491-6ade-6f7f576abd81', '89d0cbbb-6bf4-0663-fe49-3fdea161f63b', 'guide', 'Guide du TP 2', 'Repères de lecture de passwd, shadow, sudo, permissions et SUID.', '/labs/lnx-tp2-guide.pdf', 8),
  ('150781d2-81a3-94e0-7d82-e3530b3ec320', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 'log', 'Liste des processus', 'Sortie « ps aux » exportée depuis « srv-web01 ».', '/labs/lnx-tp3-ps.txt', 1),
  ('d807b1a0-c929-0996-530b-b717ded92cb0', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 'log', 'Arbre PID-PPID', 'Export simplifié pour relier parents et enfants utiles.', '/labs/lnx-tp3-ps-arbre.txt', 2),
  ('ba6202d4-4568-4dfa-67a5-a6ffd47b1116', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 'log', 'Services systemd', 'Liste complète « systemctl list-units --type=service --all --no-pager ».', '/labs/lnx-tp3-services.txt', 3),
  ('55c6f5cf-64c8-1c6a-0337-ddd1b190b45e', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 'log', 'Ports à l’écoute', 'Sortie « ss -tulpn » du serveur.', '/labs/lnx-tp3-ports.txt', 4),
  ('b78074f6-5a74-3c8b-c7ba-9026475b8342', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 'log', 'Tâches planifiées', 'Concaténation de crontab et de fichiers « /etc/cron.d » avec commentaires utiles.', '/labs/lnx-tp3-cron.txt', 5),
  ('71e38607-3384-7896-1d09-4a7ad51e1ee0', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 'log', 'Minuteurs systemd', 'Sortie « systemctl list-timers --all --no-pager ».', '/labs/lnx-tp3-minuteurs.txt', 6),
  ('7cae109a-2aa4-df8d-ed3a-5b3a182460f0', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 'log', 'Unité systemd suspecte', 'Contenu d’une unité retrouvée dans la liste des services.', '/labs/lnx-tp3-unite.service', 7),
  ('62a61a4b-558e-1a99-81a6-247ed5e40a6b', '0b9ed4ef-5694-81ce-6a4d-b017d26bb9d0', 'guide', 'Guide du TP 3', 'Méthode de lecture des processus, services, ports, cron et minuteurs.', '/labs/lnx-tp3-guide.pdf', 8),
  ('02c82a7b-b1ac-ca8c-7e7b-aa1999ec72a2', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 'log', 'Informations réseau (lnx-tp4-reseau.txt)', 'Sorties ip, voisinage ARP, resolv.conf et hosts de srv-web01.', '/labs/lnx-tp4-reseau.txt', 1),
  ('ba9fdc55-6d7a-bb8a-1cc3-79a3034610a7', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 'log', 'Configuration SSH concaténée (lnx-tp4-sshd_config.txt)', 'Fichier principal, fichiers inclus et blocs Match lus dans leur ordre réel.', '/labs/lnx-tp4-sshd_config.txt', 2),
  ('7bffcd2a-245c-ccea-c3ef-66d655a79635', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 'log', 'Journal d’authentification (lnx-tp4-auth.log)', 'Bruit normal, connexions légitimes, échecs et un succès par mot de passe à analyser.', '/labs/lnx-tp4-auth.log', 3),
  ('92a05544-88f9-f598-51d0-f1f54433675b', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 'log', 'Règles et journal UFW (lnx-tp4-ufw.txt)', 'État numéroté du pare-feu et quelques lignes du journal noyau.', '/labs/lnx-tp4-ufw.txt', 4),
  ('59a21b9b-e5d8-2ddc-7190-8ab6849aef9e', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 'log', 'Relevé des clés autorisées (lnx-tp4-cles.txt)', 'Empreintes, tailles, types et commentaires des clés autorisées sur le serveur.', '/labs/lnx-tp4-cles.txt', 5),
  ('e8db190c-5d8e-854d-799f-059d0012e1bf', 'b3069c16-c0fe-fe17-c7df-6ea5518c2368', 'guide', 'Guide du TP 4', 'Méthode pas à pas, commandes bash, variantes PowerShell et rappels sur l’ordre des règles.', '/labs/lnx-tp4-guide.pdf', 6),
  ('338015d5-e1a5-5c9b-af1e-db2b619d2c77', '33390f57-d755-f342-9e56-4b3b7c83858b', 'log', 'Mises à jour et version système (lnx-tp5-maj.txt)', 'Extrait de /etc/os-release et sortie apt list --upgradable.', '/labs/lnx-tp5-maj.txt', 1),
  ('5e25a38b-4710-fd2d-1242-1f79b1b89419', '33390f57-d755-f342-9e56-4b3b7c83858b', 'log', 'Disques, inodes et montages (lnx-tp5-disques.txt)', 'Sorties df -h, df -i, lsblk -f et findmnt de srv-fichiers01.', '/labs/lnx-tp5-disques.txt', 2),
  ('655b55c9-ede3-9dca-1d1e-8c99ad2133f4', '33390f57-d755-f342-9e56-4b3b7c83858b', 'log', 'Table de montage (lnx-tp5-fstab.txt)', 'Contenu réaliste de /etc/fstab à relire avec les options de montage.', '/labs/lnx-tp5-fstab.txt', 3),
  ('7b808e53-9cba-f884-6e88-ae9cba6e08dd', '33390f57-d755-f342-9e56-4b3b7c83858b', 'log', 'Journal des sauvegardes (lnx-tp5-sauvegarde.log)', 'Trente nuits d’exécution avec succès, échecs et panne d’espace disque.', '/labs/lnx-tp5-sauvegarde.log', 4),
  ('d56355b4-d5af-687c-e328-b4c764b36961', '33390f57-d755-f342-9e56-4b3b7c83858b', 'log', 'Liste des instantanés restic (lnx-tp5-instantanes.txt)', 'Instantanés daily, weekly et monthly à relire avec une politique de rétention donnée.', '/labs/lnx-tp5-instantanes.txt', 5),
  ('92b8f3c0-e403-f8cb-907f-f73981b7351e', '33390f57-d755-f342-9e56-4b3b7c83858b', 'log', 'Inventaire des copies de sauvegarde (lnx-tp5-copies.txt)', 'Copies locales et distante, avec support, emplacement, date de synchronisation et statut.', '/labs/lnx-tp5-copies.txt', 6),
  ('2f7e0ab9-6174-1cb3-863f-9d25804813b6', '33390f57-d755-f342-9e56-4b3b7c83858b', 'log', 'Script de sauvegarde nocturne (lnx-tp5-sauvegarde.sh)', 'Script shell court qui synchronise un miroir local puis lance restic.', '/labs/lnx-tp5-sauvegarde.sh', 7),
  ('097370c0-6f59-4224-4c7c-5b01c85a24b3', '33390f57-d755-f342-9e56-4b3b7c83858b', 'guide', 'Guide du TP 5', 'Méthode, règles de rétention, variantes de commandes et points de contrôle pour l’audit.', '/labs/lnx-tp5-guide.pdf', 8),
  ('5869716c-57c3-44d1-d592-f9ced0cf9f07', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 'log', 'Script de comptage (lnx-tp6-compter.sh)', 'Petit script bash qui compte les lignes d’échec et classe les adresses IP.', '/labs/lnx-tp6-compter.sh', 1),
  ('a1797f4a-0bfe-47ae-ccda-4d1c61f9d87d', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 'log', 'Script de nettoyage (lnx-tp6-nettoyer.sh)', 'Script de démonstration qui crée un dossier temporaire puis tente de supprimer des fichiers anciens.', '/labs/lnx-tp6-nettoyer.sh', 2),
  ('3b39efc8-f56e-3458-ba0f-7fb6ea3fedb2', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 'log', 'Script d’inventaire (lnx-tp6-inventaire.sh)', 'Script awk qui filtre un CSV de comptes et affiche un total final.', '/labs/lnx-tp6-inventaire.sh', 3),
  ('557cb376-9ce9-ebb7-ebf1-8d048de59b98', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 'log', 'Script d’archivage (lnx-tp6-sauvegarde.sh)', 'Script minimal qui construit une commande d’affichage à partir d’un argument.', '/labs/lnx-tp6-sauvegarde.sh', 4),
  ('0c7dff19-5c13-23b0-d5aa-30c4b3acab6d', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 'log', 'Journal d’authentification d’exercice (lnx-tp6-journal.log)', 'Lignes auth.log fictives utilisées par le script de comptage.', '/labs/lnx-tp6-journal.log', 5),
  ('a50ad717-0613-c397-c554-72bf33151157', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 'log', 'Inventaire CSV des comptes (lnx-tp6-comptes.csv)', 'Comptes humains, locaux et de service avec shell et âge de mot de passe.', '/labs/lnx-tp6-comptes.csv', 6),
  ('84b2d9f1-d692-c4b2-7114-9342252591b5', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 'log', 'Blocs de sortie candidats (lnx-tp6-attendus.txt)', 'Plusieurs sorties plausibles pour le script de comptage, dont une seule correspond exactement à l’exécution réelle.', '/labs/lnx-tp6-attendus.txt', 7),
  ('a50436af-0115-f93a-65fa-8a34a3803072', '20c8d605-dbe8-7f91-ae87-eb52fb165eba', 'guide', 'Guide du TP 6', 'Méthode de lecture pas à pas, commandes de test et rappels ShellCheck utiles.', '/labs/lnx-tp6-guide.pdf', 8),
  ('a2077821-ac0d-f5fe-8d06-ca1e95433e2f', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'log', 'Journal SSH et sudo', 'Les authentifications, les échecs de force brute, les sessions cron et les actions sudo observées.', '/labs/lnx-inc-auth.log', 1),
  ('7098fd70-c065-f6d1-aee9-bc5203492e86', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'log', 'Journal web nginx', 'Le trafic normal du site, les robots, les scanners opportunistes et la séquence d’exploitation.', '/labs/lnx-inc-acces.log', 2),
  ('d5218718-1c00-9335-3301-9a4235341385', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'log', 'Historique shell du compte compromis', 'Les commandes lancées après la connexion SSH réussie.', '/labs/lnx-inc-historique.txt', 3),
  ('196bb995-1ab9-06c3-1473-9cbfccde571a', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'log', 'Processus actifs', 'Une sortie ps aux complète avec les services légitimes et le processus malveillant.', '/labs/lnx-inc-ps.txt', 4),
  ('57b9d1ae-eecc-204c-d38b-01ae9eeed937', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'log', 'Ports et connexions', 'Les écoutes, les sessions établies et la connexion sortante inhabituelle.', '/labs/lnx-inc-ports.txt', 5),
  ('e1d5566a-521f-4bde-51bc-7d4afff94290', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'log', 'Tâches planifiées', 'Le crontab système, plusieurs tâches légitimes et la persistance ajoutée.', '/labs/lnx-inc-cron.txt', 6),
  ('025f68ff-248f-b80e-067c-b6ebb9edbe6d', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'log', 'Fichiers modifiés', 'La fenêtre find -ls qui mélange bruit normal et traces d’intrusion.', '/labs/lnx-inc-fichiers-modifies.txt', 7),
  ('0fb1e257-fa1c-697b-ac25-1b4369884a12', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'log', 'Comptes locaux', 'L’export de passwd du serveur avec comptes système, humains et de service.', '/labs/lnx-inc-passwd.txt', 8),
  ('b52753c9-753a-3894-260b-f5d36008c891', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'log', 'Empreintes du site', 'Le manifeste de référence puis l’état actuel de l’arborescence web.', '/labs/lnx-inc-empreintes.txt', 9),
  ('d87ee2a3-640b-045f-5772-accc9754f430', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'guide', 'Guide de l’évaluation', 'La méthode, les commandes utiles et les repères de confinement.', '/labs/lnx-inc-guide.pdf', 10),
  ('94b385c2-2cf0-9d9b-57b4-49877fd2d818', '09c25ce8-74cc-4a83-fd21-f7be06616c16', 'report_template', 'Modèle de chronologie', 'Un tableau vide pour reconstituer la séquence complète de l’incident.', '/labs/lnx-inc-chronologie.pdf', 11),
  ('f83cb95d-0ba4-0b7c-363c-c0aad205eaff', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 'log', 'Preuves système', 'Version du système, correctifs en attente, occupation disque, montage de tmp et paramètres sysctl.', '/labs/lnx-proj-preuves-systeme.txt', 1),
  ('cf6ebd63-06c6-8bf0-3bb3-5be4bf602d13', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 'log', 'Preuves d’accès', 'Comptes, shadow, groupes, sudo, configuration SSH effective, pare-feu et ports ouverts.', '/labs/lnx-proj-preuves-acces.txt', 2),
  ('fd7b1a2a-c5ca-844c-b5a1-dd9b2ede58c0', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 'log', 'Preuves de services', 'Services systemd, rotation des journaux, cron, sauvegardes, restauration, MariaDB et configuration web.', '/labs/lnx-proj-preuves-services.txt', 3),
  ('53425368-9b40-67d0-51a6-94f9c5264733', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 'log', 'Registre de risques', 'Les actions envisagées, chacune liée à un contrôle de la grille, avec vraisemblance, impact et effort.', '/labs/lnx-proj-risques.txt', 4),
  ('f91161da-bb69-886a-100a-c7ae5cdffc12', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 'guide', 'Grille d’audit Linux', 'Les 24 contrôles, leurs poids, leurs seuils objectifs et les règles de calcul.', '/labs/lnx-proj-grille-audit.pdf', 5),
  ('73cea38f-5c2d-c994-6a59-7584f61070d5', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 'report_template', 'Modèle de rapport', 'Une structure à remplir pour la synthèse, les scores et le plan d’action.', '/labs/lnx-proj-modele-rapport.pdf', 6),
  ('5c405c07-24ee-ad75-c862-ce69e24468db', 'daa996d6-babf-81f5-21f8-955cb7d50c09', 'guide', 'Guide du projet final', 'La méthode, les commandes utiles et les repères de calcul.', '/labs/lnx-proj-guide.pdf', 7)
insert into public.skills (id, domain_id, slug, name, description, position) values
  ('266c0bef-fba6-31e1-e6ec-99aa88db25e3', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'ligne-de-commande', 'Ligne de commande et traitement du texte', 'Se déplacer dans l’arborescence, manipuler des fichiers, enchaîner des commandes et filtrer du texte avec grep, sort, uniq et awk.', 510),
  ('3135fa13-e6b5-ad83-5c54-28c486fc1029', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'droits-et-comptes', 'Droits, comptes et sudo', 'Lire des permissions, repérer les comptes et les règles sudo à risque et corriger les droits trop larges.', 520),
  ('67a19f76-58e3-4403-de11-1c9899acc3a6', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'processus-services', 'Processus, services et tâches planifiées', 'Lire les processus, les services systemd, les ports à l’écoute et les tâches cron, et repérer ce qui est anormal.', 530),
  ('81a2b04f-3156-ba3d-0acb-a05a467c93ab', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'logiciels-correctifs', 'Logiciels et correctifs', 'Gérer les paquets, juger les mises à jour en attente et comprendre la fenêtre d’exposition d’un correctif.', 540),
  ('6e727daa-eb7f-a43e-4daa-c2dce3e60f9e', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'reseau-ssh-pare-feu', 'Réseau, SSH et pare-feu', 'Lire une configuration réseau, durcir SSH, appliquer la règle de la première valeur et juger des règles de pare-feu.', 550),
  ('2c1e26b6-3d8e-e93e-0f01-3a842be6c8cb', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'sauvegarde-chiffrement-linux', 'Stockage, sauvegardes et chiffrement', 'Lire l’occupation des disques et le fstab, juger une politique de sauvegarde et chiffrer ou vérifier des fichiers.', 560),
  ('796e6e45-231c-a70b-9772-23f6d61fd584', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'scripts-shell', 'Scripts shell fiables', 'Prédire la sortie d’un script, repérer les variables non protégées et les entrées non validées, et corriger.', 570),
  ('d262da04-8106-1b4e-35d7-155af4298d99', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'durcissement-linux', 'Durcissement et audit d’un serveur Linux', 'Appliquer une checklist de durcissement, noter un serveur avec une grille, prioriser les actions et rédiger un rapport.', 580)
